BEGIN;

-- Generated once from tools/<key>/definition.ts before those files were removed.
-- Sets spec only where it is still empty, so re-running keeps Admin edits.

UPDATE managed_tools SET spec = $spec${"messages":{"progress.numberingPdfPage":"Numbering PDF page","progress.pageComplete":"Page complete","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","color.commaChannels":"Use three comma-separated channels and optional alpha, or spaces with / alpha.","color.spaceChannels":"Use three space-separated channels and optional / alpha.","color.consistentChannels":"Comma-separated RGB channels must all use numbers or all use percentages.","color.hslSuffix":"HSL saturation and lightness need a % suffix.","color.finiteHue":"Hue must be a finite number.","color.hexFormat":"HEX color must use #RGB, #RGBA, #RRGGBB, or #RRGGBBAA.","color.finiteChannel":"{channel, select, alpha {Alpha} rgbPercentage {RGB percentage} rgbChannel {RGB channel} hue {Hue} hslPercentage {HSL percentage} saturation {Saturation} lightness {Lightness} other {Color channel}} must be a finite number.","color.channelRange":"{channel, select, alpha {Alpha} rgbPercentage {RGB percentage} rgbChannel {RGB channel} hue {Hue} hslPercentage {HSL percentage} saturation {Saturation} lightness {Lightness} other {Color channel}} must be {min}–{max}.","color.syntax":"Enter HEX, rgb(), hsl(), or a CSS color name.","color.standaloneRecovery":"Use a standalone color; variables and relative colors need stylesheet context."},"toolId":"media.add-page-numbers","app":"media","category":"pdf-optimization","keywords":["pdf","page numbers","pagination","numbering","footer","header","stamp"],"name":"Add Page Numbers","description":"Add configurable page numbers to a PDF.","input":{"kind":"files","label":"Add a PDF to number","dropzoneDescription":"PDF · 1 file · 50 MiB max · processed on this device","accept":"application/pdf,.pdf","multiple":false,"engine":"pdf","inspect":true,"maxFiles":1,"maxBytes":52428800,"maxTotalBytes":52428800},"settings":{"fields":{"format":{"kind":"select","label":"Format","help":"What is printed on each page: the bare number, a Page N label, or N / total.","default":"number","choices":[{"label":"1","value":"number"},{"label":"Page 1","value":"page-number"},{"label":"1 / 10","value":"number-of-total"}]},"start":{"kind":"number","label":"Start at","help":"The number printed on the first page. Use it to continue the numbering of another document.","default":1,"min":0},"fontSize":{"kind":"number","label":"Font size","help":"Size of the number in PDF points. 12 matches typical body text.","default":12,"min":6,"suffix":"pt"},"textColor":{"kind":"color","label":"Text color","help":"Choose a color or enter a six-digit hex value, such as #1a1a1a.","default":"#1a1a1a"},"position":{"kind":"position","label":"Position","help":"Where the number sits on the page. It is inset 24 points from the edges.","default":"bottom-center"}}},"trigger":{"mode":"manual","actionLabel":"Add page numbers"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"#+"},"labels":{"empty":"Drop one PDF (.pdf, up to 50 MiB) to add page numbers.","ready":"Your numbered PDF is ready to download.","running":"Adding page numbers…"},"content":{"howToUse":["Add a single PDF. Every page in it is numbered — the numbering is applied to the whole document.","Choose the format: a bare number for a clean look, Page N when the label helps, or N / total when readers need to know how much is left.","Set the starting number if this document continues another one, so a second volume can begin at 51 rather than 1.","Pick the position on the nine-point grid, font size, and text color, then run and download the numbered PDF."],"limitations":["Numbers are drawn on top of the existing page. If the chosen corner already has content, the number will overlap it — move it to a clearer corner.","Every page is numbered; there is no way to skip a cover page or number only a range.","Numbers use Helvetica; the typeface is not configurable.","The document is capped at 500 pages, and encrypted or password-protected PDFs are rejected."],"faq":[{"q":"What does the total in 1 / 10 count?","a":"The number of pages in the document, offset by your starting number — starting at 5 on a 10-page file gives 5 / 14, so the last page still reads correctly."},{"q":"Can I skip the cover page?","a":"Not directly. Split the cover off, number the rest starting at 2, and merge the cover back on."},{"q":"Can the numbers be removed later?","a":"No. They are drawn into the page content, so keep the original file if you may need an unnumbered copy."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.add-page-numbers' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","execution.errors.invalid-prefix":"Prefix may contain only letters, numbers, underscores, and hyphens.","execution.recovery.invalid-prefix":"Use something short such as sk or pk_live, up to 32 characters."},"toolId":"devtools.api-key-generator","app":"devtools","category":"developer-generators","keywords":["api key","secret","token","generator","random","prefix","credentials"],"name":"API Key Generator","description":"Generate prefixed cryptographically secure API keys.","input":{"kind":"none"},"settings":{"fields":{"prefix":{"kind":"text","label":"Prefix","help":"Letters, numbers, underscores and hyphens. Joined to the key with an underscore. Leave empty for no prefix.","default":"sk","placeholder":"sk","maxLength":32,"pane":"main"},"environment":{"kind":"select","label":"Environment","help":"Adds an environment segment after the prefix.","default":"none","choices":[{"label":"No environment","value":"none"},{"label":"Development","value":"dev"},{"label":"Test","value":"test"},{"label":"Production","value":"live"}],"pane":"main"},"length":{"kind":"number","label":"Length","help":"Characters in the random body, not counting the prefix. 32 gives about 190 bits of entropy.","default":32,"min":8,"max":256,"pane":"main"},"count":{"kind":"number","label":"How many","default":3,"min":1,"max":100,"pane":"main"},"characterSet":{"kind":"select","label":"Character set","help":"Controls which characters can appear in the random body.","default":"url-safe","choices":[{"label":"URL-safe","value":"url-safe"},{"label":"Alphanumeric","value":"alphanumeric"}],"pane":"main"},"avoidAmbiguous":{"kind":"toggle","label":"Avoid ambiguous chars","help":"Removes 0, O, 1, I and l from the selected set.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Generate"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"KEY"},"labels":{"empty":"Choose a prefix and length, then generate.","ready":"API keys are ready.","running":"Generating keys…"},"content":{"howToUse":["Pick a short prefix that says what the key is — `sk` for a secret key, `pk` for a publishable one, or something environment-specific such as `sk_live`. A prefix makes a leaked key identifiable in logs and lets secret scanners spot it.","Leave the length at 32 unless you have a reason to change it; that is roughly 190 bits from the URL-safe alphabet, far past any brute-force concern.","Generate, then store the key as a hash on your server and show the plaintext to the user exactly once. Do not paste it into a ticket, a chat message, or a source file."],"limitations":["Randomness comes from the Web Crypto API in this browser tab. Nothing is uploaded, but nothing is recorded either — once you close the tab the value is gone.","This generates an opaque random string. It is not a JWT, carries no claims, no expiry, and no signature; revocation and scoping are your server's job.","There is no checksum in the key, so a truncated or mistyped key cannot be detected client-side the way a Stripe- or GitHub-style checksummed key can.","The prefix is joined with an underscore and is not itself random, so it contributes no entropy.","Keys are generated in the browser, so treat any key produced on a machine you do not control as compromised."],"faq":[{"q":"How long should a key be?","a":"32 characters from this 64-character alphabet is about 190 bits — comfortably beyond brute force. Anything above 20 is fine; the extra length costs nothing."},{"q":"Should I store these in my database?","a":"Store a hash, not the key. Hash with SHA-256 on receipt and compare hashes; that way a database leak does not hand over working credentials."},{"q":"Why does the key use `-` and `_`?","a":"The alphabet is URL-safe Base64 characters, so a key can go in a URL path, a query string, or a header without escaping."},{"q":"Are these keys unique?","a":"Not by construction — they are random, with no registry behind them. At 32 characters a collision is astronomically unlikely, but your server should still enforce uniqueness on insert."}],"examples":[{"label":"Production service keys","text":"","settings":{"prefix":"svc","environment":"live","length":48,"count":5,"characterSet":"alphanumeric","avoidAmbiguous":true}}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.api-key-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","execution.gifDecoded":"GIF decoded · {width} × {height} px","execution.fileDecoded":"File decoded","execution.downloadToOpen":"Preview unavailable. Download to open.","execution.decodedImage":"Decoded Base64 image"},"toolId":"devtools.base64-decoder","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["base64","decode","base64url","utf-8","atob","data uri"],"name":"Base64 Decoder","description":"Decode Base64 text, images, and binary files.","layout":"stacked","input":{"kind":"text","label":"Base64 input","placeholder":"SGVsbG8g8J+Riw=="},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Decode"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"64-"},"labels":{"empty":"Paste Base64 to decode its contents.","ready":"Decoded content is ready.","running":"Decoding Base64…"},"content":{"howToUse":["Paste the Base64 string. Standard and URL-safe alphabets both work, and missing `=` padding is added for you.","Whitespace and line breaks inside the value are ignored, so a wrapped PEM-style block or a value copied across several lines decodes fine.","Decode, then copy text or preview and download the decoded file."],"limitations":["Recognized PNG, JPEG, WebP, and GIF images are previewed. Tiny or transparent images can look blank. Other binary payloads are downloaded as `decoded.bin` with an explanation when no preview is available.","Base64 data URIs are accepted directly; the encoded body is extracted automatically.","A JWT is three Base64url segments joined by dots. Paste one segment, or use the JWT Decoder for the whole token.","Invalid characters or a length that cannot be padded to a multiple of four are rejected with 'Base64 input is invalid.'"],"faq":[{"q":"Do I need to convert Base64url to standard Base64 first?","a":"No. `-` and `_` are translated automatically and the padding is restored, so Base64url values decode as-is."},{"q":"What happens when the result is not text?","a":"Recognized images are previewed. Any other binary payload is preserved and offered as a download."},{"q":"Is my data uploaded?","a":"No. Decoding happens entirely in this browser tab."}],"examples":[{"label":"Text with an emoji","text":"SGVsbG8g8J+Riw=="}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.base64-decoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text."},"toolId":"devtools.base64-encoder","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["base64","encode","url safe","base64url","utf-8","data uri"],"name":"Base64 Encoder","description":"Encode UTF-8 text as Base64.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"Hello 👋"},"settings":{"fields":{"urlSafe":{"kind":"toggle","label":"URL-safe","help":"Emit base64url: + becomes -, / becomes _, and the = padding is dropped.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Encode"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"64+"},"labels":{"empty":"Enter text to encode it as Base64.","ready":"Base64 text is ready.","running":"Encoding text as Base64…"},"content":{"howToUse":["Paste the text to encode. It is treated as UTF-8, so emoji and non-Latin scripts encode correctly.","Leave URL-safe off for standard Base64 (the RFC 4648 alphabet with = padding).","Turn URL-safe on when the value goes in a URL path, a query string, or a JWT segment."],"limitations":["Text only. Binary files cannot be pasted here — encode those with a file-aware tool.","Base64 is an encoding, not encryption. Anyone can decode the output; never use it to hide a secret.","Encoding inflates the payload by roughly one third."],"faq":[{"q":"When do I need the URL-safe variant?","a":"Whenever + and / would be reinterpreted — URL paths, query parameters, filenames, and JWT header/payload segments all use base64url."},{"q":"Does my text leave the browser?","a":"No. Encoding happens locally in this tab."}],"examples":[{"label":"Text with an emoji","text":"Hello 👋"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.base64-encoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"codeRun.source.required":"Write some code to run.","codeRun.source.encoding":"Source code is not valid UTF-8 text.","codeRun.source.nul":"Source code contains a NUL character.","codeRun.source.too-large":"Source code is larger than {max}.","codeRun.stdin.encoding":"Input is not valid UTF-8 text.","codeRun.stdin.nul":"Input contains a NUL character.","codeRun.stdin.too-large":"Input is larger than {max}.","codeRun.ok":"Your program ran successfully in {duration} and printed {lines, plural, =0 {nothing} one {# line} other {# lines}}.","codeRun.okDetail":"It exited with code 0.","codeRun.compileError":"Compilation failed.","codeRun.compileErrorAt":"Compilation failed at line {line}: {message}","codeRun.compileErrorDetail":"Fix the error in the compiler output below, then run again.","codeRun.runtimeError":"Your program stopped with an error (exit code {code}).","codeRun.runtimeErrorDetail":"Check the error output below for the cause.","codeRun.killed":"Your program was stopped by the signal {signal}.","codeRun.killedDetail":"{signal, select, SIGKILL {SIGKILL usually means the memory or process limit was reached.} SIGSEGV {SIGSEGV means the program touched memory it does not own, for example an invalid pointer or unbounded recursion.} SIGABRT {SIGABRT means the program aborted itself, often after a failed assertion or an unhandled error.} SIGFPE {SIGFPE means an illegal arithmetic operation, such as dividing an integer by zero.} SIGXCPU {SIGXCPU means the CPU time limit was reached.} SIGXFSZ {SIGXFSZ means the program tried to write a file larger than allowed.} other {The operating system ended the program with this signal.}}","codeRun.timeLimitRun":"Stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitCompile":"Compilation was stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitDetail":"Look for an endless loop or work that can be made smaller, then run again.","codeRun.outputLimit":"Your program printed more than the allowed amount of {stream, select, stderr {error output} other {output}}.","codeRun.outputLimitDetail":"The output below is cut off. Print less, then run again.","codeRun.unavailable":"Code execution is not available right now.","codeRun.unavailableDetail":"{reason, select, notConfigured {Running code is switched off on this server.} runtimeMissing {This language version is not installed on the execution server.} other {The execution server did not respond.}} Your code is kept. Try again in a minute.","codeRun.busy":"The execution server is busy.","codeRun.busyDetail":"Your code is kept. Try again in {seconds} seconds.","codeRun.fact.time":"Run time","codeRun.fact.cpu":"CPU time","codeRun.fact.memory":"Memory","codeRun.fact.exit":"Exit code","codeRun.fact.signal":"Signal","codeRun.fact.language":"Language","codeRun.section.stdout":"Standard output","codeRun.section.stderr":"Error output","codeRun.section.compiler":"Compiler output","codeRunner.editor":"{language} source code","codeRunner.stdin":"Standard input (stdin)","codeRunner.stdinHelp":"Type anything your program reads before you press Run. Input cannot be typed while the program is running.","codeRunner.stdinPlaceholder":"Optional. For example: Ada","codeRunner.run":"Run","codeRunner.cancel":"Cancel","codeRunner.runTooltip":"Run your program ({shortcut})","codeRunner.cancelTooltip":"Stop this run. Your code stays as it is.","codeRunner.running":"Running your program…","codeRunner.cancelled":"Run cancelled. Your code is unchanged.","codeRunner.reset":"Reset to starter","codeRunner.resetTitle":"Reset to the starter program?","codeRunner.resetBody":"Your current code is replaced by the starter program and your saved draft is removed.","codeRunner.resetConfirm":"Reset","codeRunner.resetKeep":"Keep my code","codeRunner.upload":"Upload file","codeRunner.uploadFailed":"{name} could not be read as text.","codeRunner.uploadTooLarge":"{name} is larger than {max} KiB. Choose a smaller file.","codeRunner.download":"Download source","codeRunner.version":"{language} version","codeRunner.versionTooltip":"Choose which version runs your code. Each run uses exactly that version.","codeRunner.draftNote":"Your code is saved in this browser only, until you run it.","codeRunner.resultPlaceholder":"Press Run to see what your program prints, or why it stopped."},"toolId":"devtools.bash-compiler","slug":"bash-compiler","app":"devtools","category":"compilers","keywords":["bash","shell","bash compiler","online bash","run bash","shell script"],"name":"Bash Compiler","description":"Write and run Bash 5.2 code in your browser. Add input, press Run, and read the output or the exact error. Nothing to install.","input":{"kind":"text","label":"Bash code","language":"bash","showLineNumbers":true,"maxLength":65536,"acceptFiles":{"accept":".sh,text/plain","maxBytes":65536},"secondary":{"label":"Standard input (stdin)","placeholder":"Optional. For example: Ada"}},"settings":{"fields":{"version":{"kind":"select","label":"Version","help":"Each run uses exactly this version.","default":"5.2","choices":[{"value":"5.2","label":"Bash 5.2"}]}}},"resultStats":"status-only","trigger":{"mode":"manual","actionLabel":"Run"},"capabilities":{"cancel":true,"copy":true,"download":true,"network":true},"workbenchMark":{"text":"SH","tone":"contrast"},"labels":{"result":"Result","empty":"Press Run to see what your program prints, or why it stopped.","ready":"Your program finished. The result explains what happened.","running":"Running your program…"},"content":{"seoTitle":"Online Bash Compiler — Run Bash 5.2 Code","howToUse":["The editor starts with a small Bash program that reads a name from standard input and greets it, so you can press Run straight away.","Write or paste your Bash code. Anything your program reads from the keyboard goes in the Standard input box before you run it.","Press Run or Ctrl/Cmd+Enter. The result starts with one sentence saying what happened, followed by the output, error output and exit code.","If something goes wrong the message names the cause. Fix your code and run again. Your code is kept in this browser while you work."],"limitations":["This page runs Bash 5.2.0 exactly, so results stay the same until the page is updated.","Each run is stopped after 5 seconds of running time (3 seconds of CPU time), and is limited to 256 MiB of memory and 64 KiB of output.","Source code and input are each limited to 64 KiB. Command-line arguments are not supported.","There is no network access, no way to install packages and no files that last between runs.","Input cannot be typed while the program runs. Put everything it will read in the Standard input box first.","If many people run code at once, the server may ask you to wait a few seconds. Your code is kept when that happens."],"faq":[{"q":"Is my code sent to a server, and is it saved?","a":"Yes, your code and input are sent to Canopy's execution server so it can run the program. It runs once in an isolated sandbox and is not stored. A draft stays in your own browser so a refresh does not lose your work."},{"q":"Which Bash version does this use?","a":"Bash 5.2.0. The version is pinned, so results stay the same until the page is updated."},{"q":"Which commands can I use?","a":"Bash built-ins and the basic tools installed in the sandbox. There is no network, so commands such as curl cannot reach anything."},{"q":"Why was my program stopped?","a":"Programs that run longer than the time limit, use too much memory or print too much are stopped to keep the service fair. The result tells you which limit was reached."}],"examples":[{"label":"Hello with input","text":"read -r name\necho \"Hello, ${name:-world}!\"\n","secondary":"Ada"}],"relatedToolIds":["devtools.python-compiler","devtools.javascript-compiler","devtools.typescript-compiler"]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.bash-compiler' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","execution.errors.invalid-username":"Username cannot contain a colon (:).","execution.recovery.invalid-username":"Use a username without a colon.","execution.errors.invalid-credentials":"Username and password cannot contain control characters.","execution.recovery.invalid-credentials":"Remove line breaks, tabs, and other control characters, then try again.","workspace.base64_is_reversible_ac9bab":"Base64 is reversible. Treat this output as a password and use HTTPS.","workspace.formatHelp.header":"Copy this complete Authorization header into your HTTP client.","workspace.formatHelp.value":"Use this value for a header named Authorization. The Basic prefix is included.","workspace.formatHelp.base64":"This is the encoded username:password token. Add Basic followed by a space when using it as an Authorization header value.","workspace.formatHelp.curl":"Replace https://example.com/api with your HTTPS endpoint, then run the command in your terminal.","workspace.formatHelp.fetch":"Replace https://example.com/api with your HTTPS endpoint. Browser requests to another origin require the server to allow CORS."},"toolId":"devtools.basic-auth-generator","app":"devtools","category":"jwt-api-tools","keywords":["basic auth","authorization header","http","credentials","base64","curl"],"name":"Basic Auth Generator","description":"Generate Basic Auth headers, Base64 tokens, and cURL or JavaScript fetch snippets.","layout":"stacked","inputSize":{"default":50},"input":{"kind":"fields","label":"Username and password","fields":[{"channel":"text","label":"Username","placeholder":"ada@example.com","required":true},{"channel":"secondary","label":"Password or API secret (optional)","placeholder":"correct horse battery staple","secret":true}]},"settings":{"fields":{"format":{"kind":"select","label":"Output format","help":"Choose how you will use the credentials. All formats use UTF-8 and standard Base64.","default":"header","choices":[{"label":"Authorization header","value":"header"},{"label":"Header value","value":"value"},{"label":"Base64 token","value":"base64"},{"label":"cURL command","value":"curl"},{"label":"JavaScript fetch","value":"fetch"}],"pane":"input"}}},"trigger":{"mode":"manual","actionLabel":"Generate Basic Auth"},"capabilities":{"copy":true},"workbenchMark":{"text":"AUTH"},"labels":{"empty":"Enter a username and optional password, choose an output format, then generate Basic Auth.","ready":"Basic Auth output is ready.","running":"Encoding Basic Auth credentials…"},"content":{"howToUse":["Enter the username. Many API providers want a key id here and leave the password empty — that is valid, and the trailing colon is still required.","Enter the password or API secret. It stays in this browser tab — it is never sent to a server or written to a log.","Choose a full Authorization header, its value, a Base64 token, a cURL command, or JavaScript fetch. Generate, then copy the selected output.","For cURL and fetch, replace https://example.com/api with your HTTPS endpoint. This tool generates the snippet without sending a request."],"limitations":["Base64 is an encoding, not encryption. Anyone who sees the header can recover the credentials, so Basic auth is only safe over HTTPS.","Usernames cannot contain a colon. Neither username nor password may contain control characters. Colons in passwords are allowed.","Credentials are encoded as UTF-8. Servers that expect Latin-1 may reject non-ASCII characters."],"faq":[{"q":"Is the generated header safe to paste into a shared document?","a":"No. It is your password in a trivially reversible form. Treat the header exactly as you would treat the raw credential."},{"q":"Can I leave the password empty?","a":"Yes. Token-style APIs often use the key as the username and an empty password; the encoded value still contains the trailing colon, which is what the server expects."}],"examples":[{"label":"Username and password","text":"Ada","secondary":"secret"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.basic-auth-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","execution.match":"Match","execution.noMatch":"No match","execution.errors.hash-invalid":"Bcrypt hash is invalid.","execution.recovery.hash-invalid":"Paste the whole stored hash, including the $2b$ prefix and cost."},"toolId":"devtools.bcrypt-compare","app":"devtools","category":"hashing-crypto","keywords":["bcrypt","compare","verify","password","hash","check"],"name":"Bcrypt Compare","description":"Check plain text against a bcrypt hash.","layout":"stacked","input":{"kind":"fields","label":"Password and bcrypt hash","fields":[{"channel":"text","label":"Plain-text password","placeholder":"password","required":true,"secret":true,"multiline":true},{"channel":"secondary","label":"Bcrypt hash","placeholder":"$2b$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.","required":true,"secret":true,"multiline":true}]},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Compare"},"capabilities":{"copy":true},"workbenchMark":{"text":"BC?"},"labels":{"empty":"Enter a plain-text password and bcrypt hash to compare them.","ready":"Bcrypt comparison result is ready.","running":"Comparing password with bcrypt hash…"},"content":{"howToUse":["Enter the plain password. It stays in this browser tab — it is never sent to a server or written to a log.","Paste the stored bcrypt hash, including the $2b$ prefix and cost. The salt is inside the hash, so you do not supply it separately.","Compare. The answer is Match or No match; the verification itself is bcrypt's own constant-time check, so no timing signal is leaked."],"limitations":["Only bcrypt hashes are understood ($2a$, $2b$, $2y$). Any other format is rejected as invalid.","Verification costs the same work the hash was created with, so a high-cost hash takes noticeably longer in a browser.","Bcrypt truncates at 72 bytes, so two long passphrases that share their first 72 bytes both verify against the same hash."],"faq":[{"q":"Why can I not just compare two hash strings?","a":"Every bcrypt hash carries its own random salt, so hashing the same password twice yields different strings. Only a bcrypt comparison is meaningful."},{"q":"Is the comparison timing-safe?","a":"Yes. The check is delegated to bcrypt's own comparison, which does not exit early on the first differing byte."}],"examples":[{"label":"Password against a stored hash","text":"password","secondary":"$2b$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.bcrypt-compare' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again."},"toolId":"devtools.bcrypt-generator","app":"devtools","slug":"bcrypt-generator","category":"hashing-crypto","keywords":["bcrypt","hash","password","salt","cost","rounds"],"name":"Bcrypt Hash Generator","description":"Hash a password or text using bcrypt.","layout":"stacked","input":{"kind":"fields","label":"Password or text","fields":[{"channel":"text","label":"Password or text","placeholder":"correct horse battery staple","required":true,"secret":true}]},"settings":{"fields":{"rounds":{"kind":"number","label":"Cost rounds","help":"Work factor. Each extra round doubles the time to hash and to crack.","default":4,"min":4,"max":14}}},"trigger":{"mode":"manual","actionLabel":"Generate bcrypt hash"},"capabilities":{"copy":true},"workbenchMark":{"text":"BC#"},"labels":{"empty":"Enter a password or plain text to generate a bcrypt hash.","ready":"Bcrypt hash is ready.","running":"Generating bcrypt hash…"},"content":{"howToUse":["Enter the password or text to hash. It stays in this browser tab — it is never sent to a server or written to a log.","Pick a cost factor. Higher is slower and stronger; this tool caps at 14 so the browser stays responsive.","Generate, then copy the 60-character hash. The salt is embedded in it, so store the whole string and nothing else."],"limitations":["The cost range here (4–14) is chosen so hashing completes in a browser. Production systems normally use 12 or higher — benchmark on your own hardware and set it server-side.","A fresh random salt is generated on every run, so hashing the same password twice gives two different hashes. That is correct bcrypt behaviour, not a bug.","Bcrypt truncates input at 72 bytes. A longer passphrase is silently cut, and everything past byte 72 has no effect on the hash.","This is for testing and fixtures. Never generate a real user's production credential in a browser tool."],"faq":[{"q":"Why is the hash different every time?","a":"Each run uses a new random salt, which is embedded in the output. Verify with a bcrypt comparison, never by comparing two hash strings."},{"q":"What do the leading characters mean?","a":"$2b$ is the bcrypt version, the next two digits are the cost, and the following 22 characters are the salt. The rest is the digest."},{"q":"Which cost should I use?","a":"Whatever keeps a single hash around 250ms on your production hardware — commonly 12 or 13 today. The low values here exist so the tool stays usable in a browser."}],"examples":[{"label":"Passphrase","text":"correct horse battery staple"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.bcrypt-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","sharedJwt.parts":"JWT must contain three dot-separated parts.","sharedJwt.payload":"JWT header or payload is not valid Base64URL JSON.","execution.token":"Token","execution.length":"Length","execution.errors.authorization-header-required":"Authorization header must start with Bearer.","execution.recovery.authorization-header-required":"Paste the whole Authorization header or choose Raw token.","execution.errors.token-required":"Bearer token is required.","execution.recovery.token-required":"Paste the token itself, not just the Bearer prefix.","workspace.algorithm_and_token_b36ea4":"Algorithm and token metadata","workspace.claims_supplied_by_6cc4c4":"Claims supplied by the token","workspace.field_f45fc1":"Field","workspace.value_8e3795":"Value","workspace.no_claims_96fbdb":"No claims.","workspace.jwt_decoded_0d82e9":"JWT decoded","workspace.token_extracted_27065a":"Token extracted","workspace.header_and_payload_fa6f01":"Header and payload decoded. Signature not verified.","workspace.token_content_has_4b4a3c":"Token content has not been decoded.","workspace.extracted_token_5ea203":"Extracted token","workspace.copy_length_fe45ee":"Copy length","workspace.copy_token_d35b4e":"Copy token","workspace.parts.Header":"Header","workspace.parts.Payload":"Payload","workspace.decoded.Header":"Decoded header","workspace.decoded.Payload":"Decoded payload","workspace.copyJson.Header":"Copy header JSON","workspace.copyJson.Payload":"Copy payload JSON","workspace.claimsLabel.Header":"Header claims","workspace.claimsLabel.Payload":"Payload claims","workspace.tokenPreview":"Token preview","workspace.characterCount":"{count, plural, one {# character} other {# characters}}","workspace.claims.alg":"Signing algorithm","workspace.claims.typ":"Token type","workspace.claims.kid":"Key ID","workspace.claims.iss":"Issuer","workspace.claims.sub":"Subject","workspace.claims.aud":"Audience","workspace.claims.exp":"Expires at (Unix seconds)","workspace.claims.nbf":"Not valid before (Unix seconds)","workspace.claims.iat":"Issued at (Unix seconds)","workspace.claims.jti":"Token ID"},"toolId":"devtools.bearer-token-parser","app":"devtools","category":"jwt-api-tools","keywords":["bearer","token","authorization header","jwt","decode","oauth"],"name":"Bearer Token Parser","description":"Extract a Bearer token and decode it when it is a JWT.","layout":"stacked","resultView":{"default":"preview"},"input":{"kind":"fields","label":"Authorization header or raw token","fields":[{"channel":"text","label":"Authorization header or raw token","placeholder":"Bearer eyJhbGciOiJub25lIn0.eyJzdWIiOiIxMjMifQ.","required":true,"multiline":true}]},"settings":{"fields":{"inputFormat":{"kind":"select","label":"Input format","help":"Detect either form, or require a Bearer header or raw token.","default":"auto","choices":[{"label":"Auto-detect","value":"auto"},{"label":"Authorization header","value":"header"},{"label":"Raw token","value":"raw"}]},"decodeJwtParts":{"kind":"toggle","label":"Decode JWT parts","help":"Decode three-part JWT headers and payloads as JSON.","default":true},"maskRawToken":{"kind":"toggle","label":"Mask raw token","help":"Replace the token itself with bullets in visible output.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Parse token"},"capabilities":{"copy":true},"workbenchMark":{"text":"BEAR"},"labels":{"empty":"Enter an Authorization header or raw bearer token to parse it.","ready":"Parsed bearer token details are ready.","running":"Parsing bearer token…"},"content":{"howToUse":["Paste either a whole Authorization header or just the token — the Bearer prefix is stripped for you, case-insensitively.","Parse. If the token is a three-part JWT, you get its decoded header and payload as JSON alongside the token itself.","If it is an opaque token, you get the token and its length, which is usually enough to tell one credential format from another."],"limitations":["The signature is decoded but never verified. A decoded payload proves nothing about authenticity — treat every claim as unverified.","Only the JWS compact form is understood. Encrypted (JWE) and non-three-part tokens fall back to the opaque summary.","The token is a live credential. Anything you paste here is shown back to you in full, so do not screenshot or share the result."],"faq":[{"q":"Does this validate the signature?","a":"No. Decoding a JWT is just Base64URL — it requires no key. Verification must happen server-side with the issuer's key."},{"q":"Is my token sent anywhere?","a":"No. Parsing happens entirely in this browser tab, and the token is not persisted between runs."},{"q":"Why does my token come back as opaque?","a":"Because it does not have exactly three dot-separated parts. Opaque access tokens from OAuth providers are random strings with no readable structure."}],"examples":[{"label":"Bearer header with a JWT","text":"Bearer eyJhbGciOiJub25lIn0.eyJzdWIiOiIxMjMifQ."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.bearer-token-parser' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"execution.errors.invalid-binary":"Binary input must contain eight-bit bytes separated by spaces.","execution.recovery.invalid-binary":"Group the bits into bytes of exactly eight 0s and 1s, separated by whitespace.","execution.errors.invalid-utf8":"Binary input does not contain valid UTF-8 text.","execution.recovery.invalid-utf8":"Check that every byte of each multi-byte character is present and in order."},"toolId":"devtools.binary-to-text","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["binary","decode","bits","bytes","ascii","utf-8","convert"],"name":"Binary to Text","description":"Decode eight-bit binary bytes as UTF-8.","layout":"stacked","input":{"kind":"text","label":"Binary input","placeholder":"01001000 01101001"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Decode binary"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"B>T"},"labels":{"empty":"Paste whitespace-separated eight-bit binary bytes to decode.","ready":"Decoded UTF-8 text is ready.","running":"Decoding binary bytes…"},"content":{"howToUse":["Paste the bytes as groups of exactly eight 0s and 1s, separated by whitespace: `01001000 01101001`.","Any whitespace works as a separator, so bytes split across several lines decode fine.","Decode to get the UTF-8 text those bytes represent. Text to Binary is the inverse."],"limitations":["Every group must be exactly eight bits. Nibbles, 16-bit words, and unseparated bit streams are rejected rather than guessed at.","The separator must be whitespace — commas, hyphens, and `0b` prefixes are not accepted.","The bytes are decoded strictly as UTF-8. An invalid byte sequence is rejected instead of producing replacement characters, so this will not decode Latin-1 or arbitrary binary.","A multi-byte character spans several groups: `👋` is four bytes and so four groups, in order."],"faq":[{"q":"My input has no spaces between the bytes. Can I still decode it?","a":"Not directly — the input must be whitespace-separated. Insert a space every eight characters first."},{"q":"Why does it say the input is not valid UTF-8?","a":"The groups parsed as bytes, but those bytes are not a legal UTF-8 sequence. A high byte such as `11100011` on its own, or an incomplete multi-byte character, will do it."},{"q":"Does it handle big-endian versus little-endian?","a":"Byte order does not apply: each group is one byte and the bytes are decoded in the order given."}],"examples":[{"label":"Two ASCII bytes","text":"01001000 01101001"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.binary-to-text' AND spec IS NULL;
