UPDATE managed_tools SET spec = $spec${"messages":{"codeRun.source.required":"Write some code to run.","codeRun.source.encoding":"Source code is not valid UTF-8 text.","codeRun.source.nul":"Source code contains a NUL character.","codeRun.source.too-large":"Source code is larger than {max}.","codeRun.stdin.encoding":"Input is not valid UTF-8 text.","codeRun.stdin.nul":"Input contains a NUL character.","codeRun.stdin.too-large":"Input is larger than {max}.","codeRun.ok":"Your program ran successfully in {duration} and printed {lines, plural, =0 {nothing} one {# line} other {# lines}}.","codeRun.okDetail":"It exited with code 0.","codeRun.compileError":"Compilation failed.","codeRun.compileErrorAt":"Compilation failed at line {line}: {message}","codeRun.compileErrorDetail":"Fix the error in the compiler output below, then run again.","codeRun.runtimeError":"Your program stopped with an error (exit code {code}).","codeRun.runtimeErrorDetail":"Check the error output below for the cause.","codeRun.killed":"Your program was stopped by the signal {signal}.","codeRun.killedDetail":"{signal, select, SIGKILL {SIGKILL usually means the memory or process limit was reached.} SIGSEGV {SIGSEGV means the program touched memory it does not own, for example an invalid pointer or unbounded recursion.} SIGABRT {SIGABRT means the program aborted itself, often after a failed assertion or an unhandled error.} SIGFPE {SIGFPE means an illegal arithmetic operation, such as dividing an integer by zero.} SIGXCPU {SIGXCPU means the CPU time limit was reached.} SIGXFSZ {SIGXFSZ means the program tried to write a file larger than allowed.} other {The operating system ended the program with this signal.}}","codeRun.timeLimitRun":"Stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitCompile":"Compilation was stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitDetail":"Look for an endless loop or work that can be made smaller, then run again.","codeRun.outputLimit":"Your program printed more than the allowed amount of {stream, select, stderr {error output} other {output}}.","codeRun.outputLimitDetail":"The output below is cut off. Print less, then run again.","codeRun.unavailable":"Code execution is not available right now.","codeRun.unavailableDetail":"{reason, select, notConfigured {Running code is switched off on this server.} runtimeMissing {This language version is not installed on the execution server.} other {The execution server did not respond.}} Your code is kept. Try again in a minute.","codeRun.busy":"The execution server is busy.","codeRun.busyDetail":"Your code is kept. Try again in {seconds} seconds.","codeRun.fact.time":"Run time","codeRun.fact.cpu":"CPU time","codeRun.fact.memory":"Memory","codeRun.fact.exit":"Exit code","codeRun.fact.signal":"Signal","codeRun.fact.language":"Language","codeRun.section.stdout":"Standard output","codeRun.section.stderr":"Error output","codeRun.section.compiler":"Compiler output","codeRunner.editor":"{language} source code","codeRunner.stdin":"Standard input (stdin)","codeRunner.stdinHelp":"Type anything your program reads before you press Run. Input cannot be typed while the program is running.","codeRunner.stdinPlaceholder":"Optional. For example: Ada","codeRunner.run":"Run","codeRunner.cancel":"Cancel","codeRunner.runTooltip":"Run your program ({shortcut})","codeRunner.cancelTooltip":"Stop this run. Your code stays as it is.","codeRunner.running":"Running your program…","codeRunner.cancelled":"Run cancelled. Your code is unchanged.","codeRunner.reset":"Reset to starter","codeRunner.resetTitle":"Reset to the starter program?","codeRunner.resetBody":"Your current code is replaced by the starter program and your saved draft is removed.","codeRunner.resetConfirm":"Reset","codeRunner.resetKeep":"Keep my code","codeRunner.upload":"Upload file","codeRunner.uploadFailed":"{name} could not be read as text.","codeRunner.uploadTooLarge":"{name} is larger than {max} KiB. Choose a smaller file.","codeRunner.download":"Download source","codeRunner.version":"{language} version","codeRunner.versionTooltip":"Choose which version runs your code. Each run uses exactly that version.","codeRunner.draftNote":"Your code is saved in this browser only, until you run it.","codeRunner.resultPlaceholder":"Press Run to see what your program prints, or why it stopped."},"toolId":"devtools.cpp-compiler","slug":"cpp-compiler","app":"devtools","category":"compilers","keywords":["c++","cpp","c++ compiler","online c++","run c++","g++"],"name":"C++ Compiler","description":"Write and run C++ (GCC) 12.2 code in your browser. Add input, press Run, and read the output or the exact error. Nothing to install.","input":{"kind":"text","label":"C++ code","showLineNumbers":true,"maxLength":65536,"acceptFiles":{"accept":".cpp,text/plain","maxBytes":65536},"secondary":{"label":"Standard input (stdin)","placeholder":"Optional. For example: Ada"}},"settings":{"fields":{"version":{"kind":"select","label":"Version","help":"Each run uses exactly this version.","default":"c++20","choices":[{"value":"c++20","label":"C++20 (GCC 12.2)"},{"value":"c++23","label":"C++23 partial (GCC 12.2)"},{"value":"c++17","label":"C++17 (GCC 12.2)"}]}}},"resultStats":"status-only","trigger":{"mode":"manual","actionLabel":"Run"},"capabilities":{"cancel":true,"copy":true,"download":true,"network":true},"workbenchMark":{"text":"C++","tone":"contrast"},"labels":{"result":"Result","empty":"Press Run to see what your program prints, or why it stopped.","ready":"Your program finished. The result explains what happened.","running":"Running your program…"},"content":{"seoTitle":"Online C++ Compiler — Run C++ (GCC) 12.2 Code","howToUse":["The editor starts with a small C++ program that reads a name from standard input and greets it, so you can press Run straight away.","Write or paste your C++ code. Anything your program reads from the keyboard goes in the Standard input box before you run it.","Press Run or Ctrl/Cmd+Enter. The result starts with one sentence saying what happened, followed by the output, error output and exit code.","If something goes wrong the message names the cause, including the line of a compile error. Fix your code and run again. Your code is kept in this browser while you work."],"limitations":["You can run C++20 (GCC 12.2), C++23 partial (GCC 12.2), C++17 (GCC 12.2). Pick one in the version menu above the editor; each run uses that exact release.","Each run is stopped after 5 seconds of running time (3 seconds of CPU time); compiling may take up to 15 seconds, and is limited to 256 MiB of memory and 64 KiB of output.","Source code and input are each limited to 64 KiB. Command-line arguments are not supported.","There is no network access, no way to install packages and no files that last between runs.","Input cannot be typed while the program runs. Put everything it will read in the Standard input box first.","If many people run code at once, the server may ask you to wait a few seconds. Your code is kept when that happens."],"faq":[{"q":"Is my code sent to a server, and is it saved?","a":"Yes, your code and input are sent to Canopy's execution server so it can run the program. It runs once in an isolated sandbox and is not stored. A draft stays in your own browser so a refresh does not lose your work."},{"q":"Which C++ versions can I use?","a":"C++20 (GCC 12.2), C++23 partial (GCC 12.2), C++17 (GCC 12.2). C++20 (GCC 12.2) is selected first; change it in the version menu above the editor. Each choice is an exact release (GCC 12.2.0), so results stay the same until the page is updated."},{"q":"Which C++ standard is available?","a":"The code is compiled with GCC's g++. The newest language standards may not be fully supported by this older compiler version."},{"q":"Why was my program stopped?","a":"Programs that run longer than the time limit, use too much memory or print too much are stopped to keep the service fair. The result tells you which limit was reached."}],"examples":[{"label":"Hello with input","text":"#include <iostream>\n#include <string>\n\nint main() {\n    std::string name;\n    std::getline(std::cin, name);\n    if (name.empty()) name = \"world\";\n    std::cout << \"Hello, \" << name << \"!\" << std::endl;\n    return 0;\n}\n","secondary":"Ada"}],"relatedToolIds":["devtools.csharp-compiler","devtools.go-compiler","devtools.rust-compiler"]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.cpp-compiler' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedDate.invalid":"{endpoint, select, start {Start date} end {End date} other {Date}} is not a valid date or timestamp.","sharedDate.required":"{endpoint, select, start {Start date} end {End date} other {Date}} is required.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","cron.range":"{start} through {end}","cron.hour.every":"every hour","cron.hour.one":"the {time} hour","cron.hour.many":"the hours {hours}","cron.timing.everyMinute":"Every minute","cron.timing.everyMinuteDuring":"Every minute during {hours}","cron.timing.hourStep":"Every {count, plural, one {hour} other {# hours}}, starting at {time}","cron.timing.at":"At {times}","cron.timing.minuteStep":"Every {count, plural, one {minute} other {# minutes}}","cron.timing.minuteStepDuring":"Every {count, plural, one {minute} other {# minutes}} during {hours}","cron.timing.hourStart":"Every hour, on the hour","cron.timing.minutesPast":"At {minutes} {unitCount, plural, one {minute} other {minutes}} past {hours}","cron.day.every":"every day of the month","cron.day.step":"day 1 and every {count, plural, one {day} other {# days}} after that within each month","cron.day.values":"{count, plural, one {day} other {days}} {days} of the month","cron.weekday.every":"every day of the week","cron.month.every":"every month","cron.calendar.everyDay":"every day","cron.calendar.days":"on {days}","cron.calendar.either":"on {days} or on {weekdays}","cron.calendar.both":"on {weekdays}, but only on {days}","cron.description":"{timing}, {calendar}.","cron.descriptionMonths":"{timing}, {calendar}, in {months}.","cron.note.alternatives":"The day of the month and day of the week are alternatives: either one can match.","cron.note.both":"Both the day-of-month rule and weekday rule must match for this schedule.","cron.note.minuteRestart":"The minute count restarts each hour, so this is not a continuous {count}-minute interval.","cron.note.hourRestart":"The hour count restarts at midnight, so this is not a continuous {count}-hour interval.","cron.note.dayRestart":"The day count restarts on day 1 of each month.","cron.note.missingDates":"Dates that do not exist in a month are skipped.","cron.note.timezone":"Times use the timezone configured in your scheduler. The expression itself does not include a timezone.","cron.field.minute":"Minute","cron.field.hour":"Hour","cron.field.day":"Day of month","cron.field.month":"Month","cron.field.weekday":"Day of week","cron.field.everyMinute":"Every minute.","cron.field.hourStart":"At the start of the hour.","cron.field.minutesPast":"{minutes} {unitCount, plural, one {minute} other {minutes}} past the hour.","cron.field.everyHour":"Every hour.","cron.field.during":"During {hours}.","cron.field.description":"{description}.","cron.error.fields":"Cron expression must contain minute, hour, day, month, and weekday fields.","cron.error.fiveFields":"Cron expression must contain five fields.","cron.error.range":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} must be between {min} and {max}.","cron.error.step":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} step is outside the supported range.","cron.error.syntax":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} contains unsupported syntax.","cron.error.ascending":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} range must be ascending.","cron.error.noRuns":"No matching runs were found in the next two years.","cron.error.required":"Cron expression is required.","cron.error.enterValue":"Enter a value and try again.","cron.validSchedule":"Valid schedule","cron.expression":"Cron expression","cron.fieldMeanings":"What each part means","cron.timingNotes":"Timing notes","cron.column.part":"Part","cron.column.value":"Value","cron.column.meaning":"Meaning","workspace.edit_cron_schedule_7fdbcb":"Edit cron schedule","workspace.in_the_timezone_f954eb":"In the timezone configured on your cron host.","workspace.syntax_help_d0ddb5":"Syntax help","workspace.in_the_minute_830478":"In the Minute field — other fields still apply","workspace.enterField":"Enter {field}, or * for every value.","workspace.fieldSyntax":"{field} contains unsupported syntax. Use *, */step, numbers, ascending ranges, or comma-separated lists.","workspace.completeFields":"Complete the highlighted fields to see your schedule.","workspace.everyMinute":"Every minute.","workspace.everyMinutes":"Every {count, plural, one {minute} other {# minutes}}.","workspace.weekdayTime":"At {time}, Monday through Friday.","workspace.dailyTime":"At {time}, every day.","workspace.weekdayRange":"0–7 · Sun = 0 or 7","workspace.syntax.0":"Every minute","workspace.syntax.1":"At minutes 1 and 15","workspace.syntax.2":"At minutes 1 through 5","workspace.syntax.3":"At minutes 0, 15, 30 and 45","workspace.settings":"SETTINGS"},"toolId":"devtools.cron-builder","sharing":{"version":1},"slug":"cron-builder","app":"devtools","category":"date-time-tools","keywords":["cron","crontab","schedule","expression","builder","job","timer"],"name":"Cron Expression Builder","description":"Build a standard five-field cron expression.","input":{"kind":"none"},"settings":{"fields":{"minute":{"kind":"text","label":"Minute","help":"0-59, or * for every minute.","default":"0","maxLength":64,"pane":"main"},"hour":{"kind":"text","label":"Hour","help":"0-23, or * for every hour.","default":"9","maxLength":64,"pane":"main"},"dayOfMonth":{"kind":"text","label":"Day of month","help":"1-31, or * for every day.","default":"*","pane":"main"},"month":{"kind":"text","label":"Month","help":"1-12, or * for every month.","default":"*","pane":"main"},"dayOfWeek":{"kind":"text","label":"Day of week","help":"0-7 with both 0 and 7 meaning Sunday. 1-5 is Monday to Friday.","default":"1-5","pane":"main"},"timezone":{"kind":"select","label":"Timezone","help":"Documentation only — a cron expression carries no timezone. It records which clock you intended.","default":"utc","choices":[{"label":"UTC","value":"utc"},{"label":"Local time","value":"local"}],"pane":"main"},"commandLabel":{"kind":"text","label":"Command label (optional)","help":"Appended as a Label line so the expression arrives in a ticket with its purpose attached.","default":"","pane":"main"}}},"trigger":{"mode":"live","debounceMs":160},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"CRN+"},"labels":{"empty":"Adjust the schedule fields to build a cron expression.","ready":"Cron expression is ready.","running":"Building cron expression…"},"content":{"howToUse":["Enter the minute and hour, then set day of month, month, and day of week. Each field accepts a number, a range (1-5), a list (1,15), a step (*/15), or * for every value.","Read the plain-English description under the expression before you use it — it is generated from the fields you actually typed, which is how you catch a misplaced value.","Watch out for the classic trap: setting both day of month and day of week means the job runs when either matches, not both. Leave one as * unless you want that.","Add a command label if the expression is going into a ticket or a runbook, then copy the result into your crontab or scheduler."],"limitations":["Only the standard five-field format is produced. Six-field dialects with a seconds column, and the Quartz-style ? and L specifiers, are not supported.","Named values are not accepted — use 1-5 rather than MON-FRI, and 1 rather than JAN.","The timezone setting is documentation only. A cron expression carries no timezone; the schedule runs in whatever zone the executing machine is configured for.","The description explains the fields but does not compute upcoming run times."],"faq":[{"q":"Why does my job run more often than expected?","a":"Almost always the day-of-month and day-of-week interaction: when both are set to something other than *, cron runs the job when either matches. Set one of them to *."},{"q":"How do I run something every fifteen minutes?","a":"Put */15 in the minute field and * in the hour field."},{"q":"Is midnight 0 or 24?","a":"0. The hour field runs 0-23, so midnight is hour 0 and 11pm is hour 23."},{"q":"Which timezone does the schedule use?","a":"The one the machine running cron is set to, which is often UTC on a server and local time on a laptop. Confirm it on the host rather than assuming."}],"examples":[{"label":"Every 15 minutes","text":"","settings":{"minute":"*/15","hour":"*","dayOfMonth":"*","month":"*","dayOfWeek":"*","timezone":"utc","commandLabel":"Health check"}}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.cron-builder' AND spec IS NULL;
