note.hourRestart":"The hour count restarts at midnight, so this is not a continuous {count}-hour interval.","cron.note.dayRestart":"The day count restarts on day 1 of each month.","cron.note.missingDates":"Dates that do not exist in a month are skipped.","cron.note.timezone":"Times use the timezone configured in your scheduler. The expression itself does not include a timezone.","cron.field.minute":"Minute","cron.field.hour":"Hour","cron.field.day":"Day of month","cron.field.month":"Month","cron.field.weekday":"Day of week","cron.field.everyMinute":"Every minute.","cron.field.hourStart":"At the start of the hour.","cron.field.minutesPast":"{minutes} {unitCount, plural, one {minute} other {minutes}} past the hour.","cron.field.everyHour":"Every hour.","cron.field.during":"During {hours}.","cron.field.description":"{description}.","cron.error.fields":"Cron expression must contain minute, hour, day, month, and weekday fields.","cron.error.fiveFields":"Cron expression must contain five fields.","cron.error.range":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} must be between {min} and {max}.","cron.error.step":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} step is outside the supported range.","cron.error.syntax":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} contains unsupported syntax.","cron.error.ascending":"{field, select, minute {Minute} hour {Hour} day {Day of month} month {Month} weekday {Weekday} other {Field}} range must be ascending.","cron.error.noRuns":"No matching runs were found in the next two years.","cron.error.required":"Cron expression is required.","cron.error.enterValue":"Enter a value and try again.","cron.validSchedule":"Valid schedule","cron.expression":"Cron expression","cron.fieldMeanings":"What each part means","cron.timingNotes":"Timing notes","cron.column.part":"Part","cron.column.value":"Value","cron.column.meaning":"Meaning","workspace.copy_cron_expression_a3078a":"Copy cron expression"},"toolId":"devtools.cron-parser","sharing":{"version":1},"app":"devtools","slug":"cron-parser","category":"date-time-tools","keywords":["cron","crontab","schedule","parse","explain","validate"],"name":"Cron Expression Parser","description":"Validate and explain a five-field cron expression.","layout":"side-by-side","input":{"kind":"fields","label":"Cron Expression","fields":[{"channel":"text","label":"Cron expression","placeholder":"*/15 * * * *","required":true,"multiline":false}]},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Parse cron"},"capabilities":{"copy":true},"workbenchMark":{"text":"CRN?"},"labels":{"result":"Schedule explained","empty":"Enter a five-field cron expression to parse it.","ready":"Cron schedule is ready.","running":"Parsing cron expression…"},"content":{"howToUse":["Paste the five-field expression: minute, hour, day of month, month, weekday.","Parse to see when the task will run in plain language. The field breakdown explains what each part of the expression means.","An out-of-range or unsupported field names the field that failed, so you know which of the five to fix."],"limitations":["Five fields only. A leading seconds field (Quartz, some job runners) or a trailing year field is rejected.","Supported syntax is *, */step, single numbers, ranges, and comma-separated lists. Named months and weekdays (JAN, MON), step-on-range (1-30/2), and the L, W, #, and ? specifiers are not accepted.","Weekday accepts 0–7 with both 0 and 7 meaning Sunday.","When both day-of-month and weekday are restricted, the task runs when either matches. The explanation calls out this rule.","No next-run times are computed here, and no timezone is applied."],"faq":[{"q":"Why was my expression rejected?","a":"Either it did not have exactly five whitespace-separated fields, or a field used syntax outside *, */step, numbers, ranges, and lists."},{"q":"Can I use MON-FRI?","a":"Not here. Use the numeric equivalent 1-5."}],"examples":[{"label":"Weekdays at 09:00","text":"0 9 * * 1-5"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.cron-parser' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.decodingImage":"Decoding image","progress.encodingImage":"Encoding image","progress.imageComplete":"Image complete","errors.invalidCropPoints":"Choose 3–12 distinct crop points inside the image without crossing the edges.","errors.cropPointCount":"Choose between 3 and 12 points.","errors.cropSelectionTooSmall":"This selection is too small for that many points. Choose fewer points.","readiness.heicUnsupported":"HEIC crop previews are not supported. Convert the image to JPEG or PNG first.","readiness.chooseCrop":"Add an image and choose a valid crop selection before processing.","readiness.validArea":"Enter a valid crop area before processing.","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.validateImageSelection.noFiles":"Choose at least one image.","media.validateImageSelection.tooManyFiles":"Choose no more than {limit, number} images.","media.validateImageSelection.invalidSize":"A selected file has an invalid size.","media.validateImageSelection.fileTooLarge":"Each image must be 25 MiB or smaller.","media.validateImageSelection.totalTooLarge":"The selected images must total 100 MiB or less.","media.validateDecodedImageDimensions.invalidDimensions":"The image dimensions are invalid.","media.validateDecodedImageDimensions.tooManyPixels":"The decoded image must be 100 megapixels or less.","media.image.unsupportedType":"Choose a supported image file.","media.image.imageSequence":"Multi-image HEIC sequences are not supported.","errors.canvasUnavailable":"Unable to create the crop. Please try again.","errors.noFiles":"Choose an image to crop.","workspace.drag_handles_to_74546a":"Drag handles to shape the crop · Drag inside to move it","workspace.arrow_keys_move_fa6c88":"Arrow keys move 1 px · Shift moves 10 px · Drag the corner to resize","workspace.freeform_point_count_727c6d":"Freeform point count","workspace.3_12_points_75dcdf":"3–12 points.","workspace.each_point_moves_734bd4":"Each point moves freely. Edges cannot cross or leave the image.","workspace.selected_point_dd18ca":" · selected point ","workspace.width_301994":"Width","workspace.height_bfe2ec":"Height","workspace.selection_bounds_ecb6b4":" · selection bounds","workspace.select_a_point_859887":"Select a point to edit its X and Y. Width and height show the selection’s bounding box.","workspace.jpeg_fills_the_1dac4a":"JPEG fills the area outside your selection with white. Choose PNG or WebP to keep it transparent.","workspace.pixels_outside_the_a58b49":"Pixels outside the selection are transparent. This crops the shape; it does not straighten perspective.","workspace.reset_crop_994fee":"Reset crop","workspace.replace_the_image_4293b3":" Replace the image to try again.","workspace.loading_image_1a0c32":"Loading image…","workspace.cropPreview":"Crop preview","workspace.fewerPoints":"This selection is too small for that many points. Choose fewer points.","workspace.pointCount":"Choose between 3 and 12 points.","workspace.wholePixel":"Enter a whole-number pixel position.","workspace.pointOverlap":"Points cannot overlap or cross the opposite edge.","workspace.decodeFailed":"This image could not be decoded.","workspace.tooLarge":"Choose an image under 100 megapixels.","workspace.selectedPointAxis":"{axis} · selected point {number}","workspace.selectionWidth":"Width · selection bounds","workspace.selectionHeight":"Height · selection bounds","workspace.imageRecovery":"{error} Replace the image to continue.","workspace.sourceSelection":"Source image with freeform crop selection","workspace.cropSelection":"Crop selection","workspace.moveSelection":"Move entire crop selection","workspace.cropPoint":"Crop point {number}","workspace.pointInstructions":"Point {number} selected · Arrow keys move 1 px · Shift moves 10 px · Esc cancels a drag"},"toolId":"media.crop-image","app":"media","category":"image-editing","keywords":["crop","image","trim","aspect ratio","jpg","png","webp","cut"],"name":"Crop Image","description":"Drag independent points to crop an image, or use a rectangular crop.","optionsPanel":{"collapsible":false,"layout":"grid"},"layout":"stacked","input":{"kind":"files","label":"Source image","accept":"image/jpeg,image/png,image/webp","multiple":false,"engine":"image","maxBytes":26214400,"maxTotalBytes":104857600},"settings":{"fields":{"cropMode":{"kind":"select","label":"Crop mode","default":"freeform","choices":[{"label":"Freeform points","value":"freeform"},{"label":"Rectangle","value":"rectangle"}]},"cropPointCount":{"kind":"number","label":"Freeform point count","default":4,"min":3,"max":12,"step":1},"cropPoints":{"kind":"text","label":"Crop points","default":"","maxLength":2048},"cropAspect":{"kind":"select","span":"full","label":"Aspect ratio","help":"Locks the drag handles in the preview. Typing a width or height directly releases the lock.","default":"free","choices":[{"label":"Free","value":"free"},{"label":"1:1","value":"1:1"},{"label":"4:3","value":"4:3"},{"label":"16:9","value":"16:9"}]},"cropX":{"kind":"number","label":"X","help":"Distance from the left edge of the image, in pixels.","default":0,"min":0,"suffix":"px"},"cropY":{"kind":"number","label":"Y","help":"Distance from the top edge of the image, in pixels.","default":0,"min":0,"suffix":"px"},"cropWidth":{"kind":"number","label":"Width","default":0,"min":0,"suffix":"px"},"cropHeight":{"kind":"number","label":"Height","default":0,"min":0,"suffix":"px"},"outputFormat":{"kind":"select","span":"full","label":"Output format","help":"Original keeps the source format. Choose PNG when the image has transparency you need to keep.","default":"png","choices":[{"label":"Original format","value":"original"},{"label":"JPEG","value":"jpeg"},{"label":"PNG","value":"png"},{"label":"WebP","value":"webp"}]},"quality":{"kind":"slider","span":"full","label":"Quality","help":"Applies to JPEG and WebP output. PNG is lossless and ignores it.","default":80,"min":30,"max":100,"suffix":"%"}}},"trigger":{"mode":"manual","actionLabel":"Crop image"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"ICUT"},"labels":{"empty":"Add an image to crop.","ready":"Your cropped image is ready to download.","running":"Cropping image…"},"content":{"howToUse":["Add a single JPG, PNG, or WebP. It is decoded in your browser — the image is never uploaded.","In Freeform points mode, choose 3–12 points and drag each independently, or select a point and type its X and Y. Drag inside the selection to move it. Width and height show the selection bounds.","Choose Rectangle mode to use an aspect ratio of 1:1, 4:3, or 16:9. Typing a width or height directly switches the ratio back to Free.","Choose an output format and quality, then run the crop and download the result."],"limitations":["One image per run. Crop a batch by repeating the tool, or resize them together with a different tool.","HEIC is not accepted here, because the preview cannot be rendered for it. Convert to JPG or PNG first.","Freeform points stay inside the image and edges cannot cross. Output is the selection’s bounding rectangle with transparent pixels outside the polygon; this does not correct perspective.","Choosing JPEG flattens transparency onto white. Keep PNG or WebP if the source has an alpha channel.","Images must be 25 MiB or smaller and under 100 megapixels."],"faq":[{"q":"Where is the origin for X and Y?","a":"The top-left corner of the image, which is the usual convention for raster images — unlike PDFs, where it is the bottom-left."},{"q":"Why can I not add a HEIC file?","a":"The crop UI needs a live preview and browsers cannot render HEIC directly. Convert it to JPG or PNG first, then crop."},{"q":"Does cropping re-encode the image?","a":"Yes. The image is decoded, cropped, and re-encoded, so a JPEG source loses a little quality even at 100%. Choose PNG output if you need that avoided."},{"q":"Why did the aspect ratio reset to Free?","a":"Typing a width or height directly is an explicit override, so the lock is released rather than silently fighting your input."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.crop-image' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.croppingPdfPage":"Cropping PDF page","errors.cropPages":"Choose pages from 1 to {count, number}.","errors.cropDimensions":"Enter non-negative Left and Bottom values and positive Width and Height.","errors.cropBeyondPage":"The crop extends beyond page {page, number}. Reduce its position or size, or change the selected pages.","errors.cropPagesTooSmall":"The selected pages are too small to crop.","readiness.wholeNumbers":"Enter whole-number points for Left, Bottom, Width, and Height.","readiness.positiveDimensions":"Width and Height must be greater than zero.","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.noFiles":"Choose a PDF to crop.","errors.invalidCrop":"The crop box must stay within every selected page.","workspace.apply_crop_to_968ae0":"Apply crop to","workspace.all_pages_903542":"All pages","workspace.odd_pages_e31c32":"Odd pages","workspace.even_pages_bd5d2d":"Even pages","workspace.custom_pages_ffe911":"Custom pages","workspace.page_range_6578bb":"Page range","workspace.crop_box_pdf_4d9949":"Crop box · PDF points","workspace.use_whole_number_cc79b4":"Use whole-number points. Bottom is measured upward from the page edge. 72 pt = 1 inch.","workspace.crop_pdf_dc4bdb":"Crop PDF","workspace.drag_to_move_22b33b":"Drag to move. Drag an edge or corner to resize. Arrow keys move by 1 pt; Shift moves by 10 pt.","workspace.edit_crop_d614bb":"Edit crop","workspace.crop_another_pdf_2a6923":"Crop another PDF","workspace.pagesSelected":"{selected} of {count, plural, one {# page selected} other {# pages selected}}","workspace.pagesSelectedSummary":"{selected} of {count, plural, one {# page selected} other {# pages selected}}. {unchanged} unchanged.","workspace.pagesCroppedSummary":"{selected} of {count, plural, one {# page cropped} other {# pages cropped}}. {unchanged} unchanged.","workspace.dimensions.cropX":"Left","workspace.dimensions.cropY":"Bottom","workspace.dimensions.cropWidth":"Width","workspace.dimensions.cropHeight":"Height","workspace.cropSettings":"Crop settings"},"toolId":"media.crop-pdf","app":"media","category":"pdf-organization","keywords":["pdf","crop","crop box","trim","margins","pages","resize page","points"],"name":"Crop PDF","description":"Change the visible crop box on selected pages.","layout":"stacked","input":{"kind":"files","label":"PDF document","accept":"application/pdf","multiple":false,"engine":"pdf","maxBytes":52428800,"maxTotalBytes":52428800,"inspect":true},"settings":{"fields":{"pages":{"kind":"pages","label":"Pages","help":"Use all, odd, even, or ranges such as 1-3,5.","default":"all"},"cropX":{"kind":"number","label":"Left","help":"Distance from the left edge of the page to the left edge of the crop box.","default":0,"min":0,"suffix":"pt"},"cropY":{"kind":"number","label":"Bottom","help":"PDF coordinates start at the bottom-left corner, so this is measured upwards.","default":0,"min":0,"suffix":"pt"},"cropWidth":{"kind":"number","label":"Width","help":"Seeded from the narrowest selected page when previews load.","default":0,"min":0,"suffix":"pt"},"cropHeight":{"kind":"number","label":"Height","help":"Seeded from the shortest selected page when previews load.","default":0,"min":0,"suffix":"pt"}}},"trigger":{"mode":"manual","actionLabel":"Crop PDF"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"PCUT"},"labels":{"empty":"Add a PDF to set its visible crop area.","ready":"Crop area is ready to apply.","running":"Cropping PDF…"},"content":{"howToUse":["Add a single PDF. Page previews are rendered in your browser so you can see what you are cropping — the document is never uploaded.","Choose which pages to crop. The same crop box is applied to every page you select, so crop mixed-size pages in separate passes.","Set Left, Bottom, Width, and Height in PDF points (72 points = 1 inch). PDF coordinates start at the bottom-left corner, so Bottom counts upwards, not downwards.","Run the crop and download. Width and Height are pre-filled from the smallest selected page, so the default box is always valid."],"limitations":["Cropping only sets the crop box. The content outside it is hidden, not deleted — it is still present in the file and can be recovered by resetting the box.","One crop box is applied to every selected page. If the box would fall outside any of them the run is rejected rather than silently clamped.","Everything is measured in PDF points, not pixels or millimetres, and the origin is the bottom-left corner.","Structural jobs are capped at 500 pages, and the PDF must be 50 MiB or smaller.","Encrypted or password-protected PDFs are rejected, and cropping invalidates an existing digital signature."],"faq":[{"q":"Is the cropped-away content actually removed?","a":"No. A crop box changes what a viewer displays and prints; the underlying page objects are untouched. Use it for presentation, never to redact sensitive content."},{"q":"Why is Bottom measured from the bottom?","a":"That is the PDF coordinate system: the origin sits at the bottom-left of the page and y grows upwards. Every PDF tool works this way."},{"q":"Why was my crop box rejected?","a":"It extended past the edge of at least one selected page. Either shrink the box or select only the pages it fits, since one box has to satisfy them all."},{"q":"How do I convert millimetres to points?","a":"Multiply by 72 and divide by 25.4 — a 10 mm margin is about 28.35 points."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.crop-pdf' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"codeRun.source.required":"Write some code to run.","codeRun.source.encoding":"Source code is not valid UTF-8 text.","codeRun.source.nul":"Source code contains a NUL character.","codeRun.source.too-large":"Source code is larger than {max}.","codeRun.stdin.encoding":"Input is not valid UTF-8 text.","codeRun.stdin.nul":"Input contains a NUL character.","codeRun.stdin.too-large":"Input is larger than {max}.","codeRun.ok":"Your program ran successfully in {duration} and printed {lines, plural, =0 {nothing} one {# line} other {# lines}}.","codeRun.okDetail":"It exited with code 0.","codeRun.compileError":"Compilation failed.","codeRun.compileErrorAt":"Compilation failed at line {line}: {message}","codeRun.compileErrorDetail":"Fix the error in the compiler output below, then run again.","codeRun.runtimeError":"Your program stopped with an error (exit code {code}).","codeRun.runtimeErrorDetail":"Check the error output below for the cause.","codeRun.killed":"Your program was stopped by the signal {signal}.","codeRun.killedDetail":"{signal, select, SIGKILL {SIGKILL usually means the memory or process limit was reached.} SIGSEGV {SIGSEGV means the program touched memory it does not own, for example an invalid pointer or unbounded recursion.} SIGABRT {SIGABRT means the program aborted itself, often after a failed assertion or an unhandled error.} SIGFPE {SIGFPE means an illegal arithmetic operation, such as dividing an integer by zero.} SIGXCPU {SIGXCPU means the CPU time limit was reached.} SIGXFSZ {SIGXFSZ means the program tried to write a file larger than allowed.} other {The operating system ended the program with this signal.}}","codeRun.timeLimitRun":"Stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitCompile":"Compilation was stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitDetail":"Look for an endless loop or work that can be made smaller, then run again.","codeRun.outputLimit":"Your program printed more than the allowed amount of {stream, select, stderr {error output} other {output}}.","codeRun.outputLimitDetail":"The output below is cut off. Print less, then run again.","codeRun.unavailable":"Code execution is not available right now.","codeRun.unavailableDetail":"{reason, select, notConfigured {Running code is switched off on this server.} runtimeMissing {This language version is not installed on the execution server.} other {The execution server did not respond.}} Your code is kept. Try again in a minute.","codeRun.busy":"The execution server is busy.","codeRun.busyDetail":"Your code is kept. Try again in {seconds} seconds.","codeRun.fact.time":"Run time","codeRun.fact.cpu":"CPU time","codeRun.fact.memory":"Memory","codeRun.fact.exit":"Exit code","codeRun.fact.signal":"Signal","codeRun.fact.language":"Language","codeRun.section.stdout":"Standard output","codeRun.section.stderr":"Error output","codeRun.section.compiler":"Compiler output","codeRunner.editor":"{language} source code","codeRunner.stdin":"Standard input (stdin)","codeRunner.stdinHelp":"Type anything your program reads before you press Run. Input cannot be typed while the program is running.","codeRunner.stdinPlaceholder":"Optional. For example: Ada","codeRunner.run":"Run","codeRunner.cancel":"Cancel","codeRunner.runTooltip":"Run your program ({shortcut})","codeRunner.cancelTooltip":"Stop this run. Your code stays as it is.","codeRunner.running":"Running your program…","codeRunner.cancelled":"Run cancelled. Your code is unchanged.","codeRunner.reset":"Reset to starter","codeRunner.resetTitle":"Reset to the starter program?","codeRunner.resetBody":"Your current code is replaced by the starter program and your saved draft is removed.","codeRunner.resetConfirm":"Reset","codeRunner.resetKeep":"Keep my code","codeRunner.upload":"Upload file","codeRunner.uploadFailed":"{name} could not be read as text.","codeRunner.uploadTooLarge":"{name} is larger than {max} KiB. Choose a smaller file.","codeRunner.download":"Download source","codeRunner.version":"{language} version","codeRunner.versionTooltip":"Choose which version runs your code. Each run uses exactly that version.","codeRunner.draftNote":"Your code is saved in this browser only, until you run it.","codeRunner.resultPlaceholder":"Press Run to see what your program prints, or why it stopped."},"toolId":"devtools.csharp-compiler","slug":"csharp-compiler","app":"devtools","category":"compilers","keywords":["c#","csharp","c# compiler","online c#","run c#",".net","dotnet"],"name":"C# Compiler","description":"Write and run C# (.NET) 10 code in your browser. Add input, press Run, and read the output or the exact error. Nothing to install.","input":{"kind":"text","label":"C# code","showLineNumbers":true,"maxLength":65536,"acceptFiles":{"accept":".cs,text/plain","maxBytes":65536},"secondary":{"label":"Standard input (stdin)","placeholder":"Optional. For example: Ada"}},"settings":{"fields":{"version":{"kind":"select","label":"Version","help":"Each run uses exactly this version.","default":"14","choices":[{"value":"14","label":"C# 14 (.NET 10 LTS)"},{"value":"12","label":"C# 12 (.NET 8 LTS)"}]}}},"resultStats":"status-only","trigger":{"mode":"manual","actionLabel":"Run"},"capabilities":{"cancel":true,"copy":true,"download":true,"network":true},"workbenchMark":{"text":"C#","tone":"contrast"},"labels":{"result":"Result","empty":"Press Run to see what your program prints, or why it stopped.","ready":"Your program finished. The result explains what happened.","running":"Running your program…"},"content":{"seoTitle":"Online C# Compiler — Run C# (.NET) 10 Code","howToUse":["The editor starts with a small C# program that reads a name from standard input and greets it, so you can press Run straight away.","Write or paste your C# code. Anything your program reads from the keyboard goes in the Standard input box before you run it.","Press Run or Ctrl/Cmd+Enter. The result starts with one sentence saying what happened, followed by the output, error output and exit code.","If something goes wrong the message names the cause, including the line of a compile error. Fix your code and run again. Your code is kept in this browser while you work."],"limitations":["You can run C# 14 (.NET 10 LTS), C# 12 (.NET 8 LTS). Pick one in the version menu above the editor; each run uses that exact release.","Each run is stopped after 5 seconds of running time (3 seconds of CPU time); compiling may take up to 15 seconds, and is limited to 256 MiB of memory and 64 KiB of output.","Source code and input are each limited to 64 KiB. Command-line arguments are not supported.","There is no network access, no way to install packages and no files that last between runs.","Input cannot be typed while the program runs. Put everything it will read in the Standard input box first.","If many people run code at once, the server may ask you to wait a few seconds. Your code is kept when that happens."],"faq":[{"q":"Is my code sent to a server, and is it saved?","a":"Yes, your code and input are sent to Canopy's execution server so it can run the program. It runs once in an isolated sandbox and is not stored. A draft stays in your own browser so a refresh does not lose your work."},{"q":"Which C# versions can I use?","a":"C# 14 (.NET 10 LTS), C# 12 (.NET 8 LTS). C# 14 (.NET 10 LTS) is selected first; change it in the version menu above the editor. Each choice is an exact release (.NET 10.0.403, .NET 8.0.427), so results stay the same until the page is updated."},{"q":"Can I use NuGet packages?","a":"No. Only the .NET base class libraries are available, because the sandbox has no network access and packages cannot be installed."},{"q":"Why was my program stopped?","a":"Programs that run longer than the time limit, use too much memory or print too much are stopped to keep the service fair. The result tells you which limit was reached."}],"examples":[{"label":"Hello with input","text":"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string name = (Console.ReadLine() ?? \"\").Trim();\n        if (name.Length == 0) name = \"world\";\n        Console.WriteLine(\"Hello, \" + name + \"!\");\n    }\n}\n","secondary":"Ada"}],"relatedToolIds":["devtools.go-compiler","devtools.rust-compiler","devtools.php-compiler"]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csharp-compiler' AND spec IS NULL;
