layers_291360":"Advanced CSS layers","workspace.additional_layers_3940c3":"Additional layers","workspace.one_shadow_per_987f6b":"One shadow per line. Use two to four pixel lengths, optional inset, and HEX or comma-separated rgb()/rgba().","workspace.use_first_enabled_318bdf":"Use first enabled layer opacity for extra rgba() layers","workspace.include_webkit_prefix_f1ba8a":"Include WebKit prefix","workspace.drag_handles_or_a9f0bc":"Drag handles or press Space, use arrow keys, and press Space again to reorder layers.","workspace.shadowLayers":"Shadow layers","workspace.shadowLayer":"Shadow layer {number}","workspace.reorderLayer":"Reorder shadow layer {number}","workspace.enableLayer":"Enable shadow layer {number}","workspace.editLayer":"Edit shadow layer {number}","workspace.removeLayer":"Remove shadow layer {number}","workspace.horizontalOffset":"Horizontal offset value","workspace.verticalOffset":"Vertical offset value","workspace.lengths.blur":"Blur","workspace.lengths.spread":"Spread","workspace.presets.Soft":"Soft","workspace.presets.Layered":"Layered","workspace.presets.Inset":"Inset","workspace.presets.Hard":"Hard","workspace.layerCount":"Layers {count}/12","workspace.layerName":"Layer {number}{inset, select, yes { (inset)} other {}}"},"toolId":"devtools.css-box-shadow","sharing":{"version":1},"slug":"css-box-shadow","app":"devtools","category":"color-design-tools","keywords":["box-shadow","css","shadow","elevation","inset","blur","spread","generator"],"name":"CSS Box Shadow Generator","description":"Generate a CSS box-shadow declaration.","outputLanguage":"css","input":{"kind":"fields","label":"Shadow Color","fields":[{"channel":"text","label":"HEX color","placeholder":"#00000080","required":true,"multiline":false}]},"settings":{"fields":{"layers":{"kind":"textarea","label":"Visual shadow layers","default":"","help":"Visual layer editor data."},"previewBackground":{"kind":"color","label":"Preview background","default":"#f1f5f9","allowTransparent":true},"previewObject":{"kind":"color","label":"Object color","default":"#ffffff","allowTransparent":true},"x":{"kind":"number","label":"X offset","help":"Horizontal distance in pixels. Positive moves the shadow right.","default":0,"min":-100,"max":100,"suffix":"px","pane":"main"},"y":{"kind":"number","label":"Y offset","help":"Vertical distance in pixels. Positive moves the shadow down.","default":12,"min":-100,"max":100,"suffix":"px","pane":"main"},"blur":{"kind":"number","label":"Blur","help":"Larger values give a softer, more diffuse edge.","default":30,"min":0,"max":200,"suffix":"px","pane":"main"},"spread":{"kind":"number","label":"Spread","help":"Grows or shrinks the shadow before blurring. Negative values pull it in under the element.","default":-8,"min":-100,"max":100,"suffix":"px","pane":"main"},"inset":{"kind":"toggle","label":"Inset","help":"Draws the shadow inside the element instead of behind it.","default":false},"additionalLayers":{"kind":"textarea","label":"Additional shadow layers","help":"Add one shadow per line using 0/px lengths and an optional HEX or rgb() color.","default":"","rows":4,"pane":"main","span":"full"},"linkOpacity":{"kind":"toggle","label":"Link opacity","help":"Apply the input HEX alpha to rgba() colors in additional layers.","default":false},"showBrowserPrefixes":{"kind":"toggle","label":"Show browser prefixes","help":"Include a -webkit-box-shadow declaration before the standard one.","default":false}}},"trigger":{"mode":"live","debounceMs":120},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"SHDW"},"labels":{"empty":"Enter a HEX shadow color to build a CSS box-shadow declaration.","ready":"CSS box-shadow declaration is ready.","running":"Building box shadow…"},"content":{"howToUse":["Enter the shadow colour as a hex value. `#RRGGBBAA` gives you a translucent shadow, which is almost always what you want — a fully opaque shadow reads as a hard outline.","Adjust the offsets, blur, and spread; add one extra shadow layer per line when a single elevation is not enough.","A believable elevation usually means a small Y offset, a blur two to three times that offset, and a slightly negative spread. Copy the declaration when it looks right."],"limitations":["Additional layers accept two to four 0/px lengths, optional inset, and an optional HEX or comma-separated rgb()/rgba() colour.","Lengths are pixels only — no rem, em, or percentage units.","Visual layers accept HEX, supported CSS names, rgb(), and hsl(). Advanced text layers accept HEX or comma-separated rgb()/rgba().","Use up to 12 visual layers and up to 20 advanced text layers.","This produces `box-shadow`, not `filter: drop-shadow()` — the two differ on transparent PNGs and non-rectangular shapes."],"faq":[{"q":"What is the difference between blur and spread?","a":"Spread resizes the shadow's shape before it is blurred; blur softens its edge. A negative spread with a large blur is the usual recipe for a soft, grounded elevation."},{"q":"How do I stack two shadows?","a":"Keep the generated first layer, then add the second complete shadow value on a new line under Additional shadow layers."},{"q":"Why does inset look like nothing happened?","a":"An inset shadow draws inside the padding box, so it is hidden if the element has no background or if the offsets are too small to clear the edge. Increase the offset or blur."},{"q":"Can I use a CSS variable for the colour?","a":"Not as input — it has to be a hex value so it can be validated. Swap the literal for `var(--shadow-color)` in the generated declaration afterwards."}],"examples":[{"label":"Slate elevation","text":"#0f172a","settings":{"layers":"","additionalLayers":"","x":0,"y":12,"blur":30,"spread":-8,"inset":false}}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.css-box-shadow' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCode.string":"Source contains an unfinished string.","sharedCode.comment":"Source contains an unfinished comment.","sharedCode.unterminated":"Source contains an unfinished string, regex, or comment.","sharedCode.syntax":"Source contains invalid JavaScript syntax.","sharedCode.close":"Close the open string or block comment and try again.","sharedCode.correct":"Correct the JavaScript syntax and try again.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again."},"toolId":"devtools.css-formatter","app":"devtools","category":"web-markup-tools","keywords":["css","format","beautify","prettify","indent","stylesheet","unminify"],"name":"CSS Formatter","description":"Apply readable indentation to CSS.","layout":"side-by-side","outputLanguage":"css","input":{"kind":"text","language":"css","label":"CSS input","placeholder":".card{color:#2563eb;padding:1rem;}"},"settings":{"fields":{"indentWidth":{"kind":"select","label":"Indent width","help":"Choose two spaces, four spaces, or tabs for each nesting level.","default":"2","choices":[{"label":"2 spaces","value":"2"},{"label":"4 spaces","value":"4"},{"label":"Tabs","value":"tab"}]},"printWidth":{"kind":"select","label":"Print width","help":"Wrap long declaration values at spaces, or keep today's unwrapped output.","default":"unlimited","choices":[{"label":"No wrapping","value":"unlimited"},{"label":"80 columns","value":"80"},{"label":"100 columns","value":"100"},{"label":"120 columns","value":"120"}]},"propertyOrder":{"kind":"select","label":"Property order","help":"Keep declaration order or alphabetize properties within each block.","default":"preserve","choices":[{"label":"Preserve source","value":"preserve"},{"label":"Alphabetical","value":"alphabetical"}]}}},"trigger":{"mode":"manual","actionLabel":"Format CSS"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"CSS+"},"labels":{"empty":"Paste CSS to format its indentation.","ready":"Formatted CSS is ready.","running":"Formatting CSS…"},"content":{"howToUse":["Paste minified or badly indented CSS. Blocks are broken onto their own lines using the selected indentation.","Nested at-rules such as `@media` and `@supports` indent their contents, so a compressed stylesheet becomes readable enough to diff.","Format, then copy the result back into your editor."],"limitations":["Comments are stripped, not reflowed. If you need them, format a copy.","This is a brace-and-semicolon formatter, not a CSS parser. It does not validate properties, add missing semicolons, or normalise colours and units.","Whitespace inside a declaration is collapsed to single spaces, so `color:#111` stays without a space after the colon — the input's spacing inside a value is preserved rather than canonicalised.","Print-width wrapping only breaks at spaces. Quoted values and lines without a safe break stay unwrapped.","An unterminated string is rejected with 'Source contains an unfinished string.' — quotes are tracked so that braces inside a string are not treated as blocks."],"faq":[{"q":"Where did my comments go?","a":"They are removed before formatting. That is deliberate — a comment can sit anywhere, including mid-declaration, and reflowing one safely needs a full parser."},{"q":"Can I choose four-space indentation?","a":"Yes. Choose two spaces, four spaces, or tabs under Formatting settings."},{"q":"Will it fix broken CSS?","a":"No. It reindents whatever you give it. Unbalanced braces produce unbalanced output rather than an error."}],"examples":[{"label":"Minified rules","text":"body{color:#111;background:#fff}a:hover{text-decoration:underline}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.css-formatter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCode.string":"Source contains an unfinished string.","sharedCode.comment":"Source contains an unfinished comment.","sharedCode.unterminated":"Source contains an unfinished string, regex, or comment.","sharedCode.syntax":"Source contains invalid JavaScript syntax.","sharedCode.close":"Close the open string or block comment and try again.","sharedCode.correct":"Correct the JavaScript syntax and try again.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again."},"toolId":"devtools.css-minifier","app":"devtools","category":"web-markup-tools","keywords":["css","minify","compress","whitespace","comments","stylesheet","optimize"],"name":"CSS Minifier","description":"Remove CSS comments and redundant whitespace.","layout":"side-by-side","outputLanguage":"css","input":{"kind":"text","language":"css","label":"CSS input","placeholder":"/* Theme */\n.card { color: #2563eb; }"},"settings":{"fields":{"browserCompatibility":{"kind":"select","label":"Browser compatibility","help":"Lightweight scanner — review output. Keep HEX alpha or convert it to rgba().","default":"modern","choices":[{"label":"Modern browsers","value":"modern"},{"label":"Legacy rgba() colors","value":"legacy"}]},"mergeRules":{"kind":"toggle","label":"Merge rules","help":"Combine adjacent selectors when their declaration blocks are identical.","default":false},"normalizeColors":{"kind":"toggle","label":"Normalize colors","help":"Shorten reducible six- and eight-digit HEX colors in property values.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Minify CSS"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"CSS-"},"labels":{"empty":"Paste CSS to remove comments and unnecessary whitespace.","ready":"Minified CSS is ready to review.","running":"Minifying CSS…"},"content":{"howToUse":["Paste the stylesheet. Comments and redundant spacing are removed. Quoted strings and required spacing around + inside CSS functions are preserved.","Minify, then copy the result into a `<style>` block or a `.css` file.","Test the minified stylesheet in a browser before shipping it — see the limitations for the constructs this pass gets wrong.","For a production build pipeline, use cssnano or Lightning CSS. This is for a quick one-off shrink."],"limitations":["This is a regex pass, not a CSS parser. Rule merging only combines adjacent flat rules with identical bodies, and colour normalization only shortens reducible HEX values.","Quoted strings are preserved, but unquoted `url()` data containing comment markers or structural delimiters is not fully parsed. Quote complex data URIs before minifying.","Preserved `/*! ... */` licence comments are stripped along with everything else.","The final `;` before a `}` is removed, which is safe, but no other structural change is attempted.","There is no source map output."],"faq":[{"q":"Will this break my stylesheet?","a":"Quoted strings and CSS math spacing are preserved. Complex unquoted `url()` data remains a limitation; diff the output and test in a browser."},{"q":"Does it preserve licence comments?","a":"No. `/*! ... */` is removed like any other comment, so re-add any required attribution by hand."},{"q":"How much smaller will it get?","a":"Whitespace and comments only — typically 10-30% on a hand-written stylesheet, and much less on one that was already compact."}],"examples":[{"label":"Commented rule","text":"/* theme */\nbody { color: #111; background: #fff; }"},{"label":"Nested selectors","text":".card > .title,\n.card + .title {\n  margin: 0;\n}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.css-minifier' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"css.unit":"Choose a supported CSS unit.","css.precision":"Precision must be a whole number from 0 to 12.","css.numberRequired":"Enter a number, optionally followed by a supported CSS unit.","css.finiteNumber":"The value is too large; enter a finite number.","css.overflow":"The converted value is too large. Reduce the value or its reference size.","css.valueRequired":"Enter a CSS value to convert.","css.positiveReference":"{reference, select, root {Root font size} parent {Parent font size} element {Element font size} percentage {Percentage reference length} width {Viewport width} height {Viewport height} other {Reference}} must be a finite, positive number.","css.failed":"Could not convert this value.","css.converted":"{converted, number} converted · {corrections, number} need correction","css.columns.line":"Line","css.columns.input":"Input","css.columns.result":"Result","css.columns.formula":"Formula","workspace.convert_css_values_50a491":"Convert CSS values","workspace.from_218197":"From","workspace.swap_units_8104cc":"Swap units","workspace.to_f4b06e":"To","workspace.values_53b09e":"Values","workspace.one_value_per_dc46f4":"One value per line. A unit suffix overrides From for that value.","workspace.em_reference_bef2dc":"em reference","workspace.element_spacing_and_c30723":"Element (spacing and sizes)","workspace.parent_font_size_c13498":"Parent (font-size)","workspace.percentage_reference_14b5c0":"Percentage reference","workspace.parent_font_size_d6ad58":"Parent font size","workspace.explicit_reference_length_f7beb3":"Explicit reference length","workspace.decimal_places_004a34":"Decimal places","workspace.include_calculation_a40841":"Include calculation","workspace.percentages_depend_on_683f68":"Percentages depend on the CSS property. Viewport units use the dimensions you supply. Negative values may not be allowed by your target property.","workspace.converted_values_b10d04":"Converted values","workspace.conversionContext":"Conversion context","workspace.rootFontSize":"Root font size","workspace.remReference":"rem is relative to the root element.","workspace.elementFontSize":"Element font size","workspace.elementReference":"Use the element’s computed font size for em lengths.","workspace.referenceLength":"100% reference length","workspace.actualReference":"Supply the actual reference for the CSS property, such as the containing block width.","workspace.parentFontSize":"Parent font size","workspace.parentReference":"Reference for font-size in em or percent.","workspace.viewportWidth":"Viewport width","workspace.viewportHeight":"Viewport height"},"toolId":"devtools.css-unit-converter","sharing":{"version":1},"app":"devtools","category":"color-design-tools","keywords":["css","px","rem","em","pt","percent","viewport","unit","convert"],"name":"CSS Unit Converter","description":"Convert CSS lengths with explicit font, percentage and viewport references.","input":{"kind":"fields","label":"CSS values","fields":[{"channel":"text","label":"Values","placeholder":"16px\n2rem\n50%","required":true,"multiline":true}]},"settings":{"fields":{"from":{"kind":"select","label":"From","default":"px","choices":[{"label":"px","value":"px"},{"label":"rem","value":"rem"},{"label":"em","value":"em"},{"label":"pt","value":"pt"},{"label":"%","value":"%"},{"label":"vw","value":"vw"},{"label":"vh","value":"vh"},{"label":"vmin","value":"vmin"},{"label":"vmax","value":"vmax"}]},"to":{"kind":"select","label":"To","default":"rem","choices":[{"label":"px","value":"px"},{"label":"rem","value":"rem"},{"label":"em","value":"em"},{"label":"pt","value":"pt"},{"label":"%","value":"%"},{"label":"vw","value":"vw"},{"label":"vh","value":"vh"},{"label":"vmin","value":"vmin"},{"label":"vmax","value":"vmax"}]},"base":{"kind":"number","label":"Root font size","help":"rem uses the computed font size of the root element.","default":16,"min":0.01,"max":10000,"suffix":"px"},"elementFontSize":{"kind":"number","label":"Element font size","default":16,"min":0.01,"max":10000,"suffix":"px"},"parentFontSize":{"kind":"number","label":"Parent font size","default":16,"min":0.01,"max":10000,"suffix":"px"},"emContext":{"kind":"select","label":"em reference","default":"element","choices":[{"label":"Element (spacing and sizes)","value":"element"},{"label":"Parent (font-size)","value":"parent"}]},"percentageReference":{"kind":"select","label":"Percentage reference","default":"parent-font","choices":[{"label":"Parent font size","value":"parent-font"},{"label":"Explicit reference length","value":"length"}]},"percentageBase":{"kind":"number","label":"Reference length","help":"The pixel length represented by 100%, such as the containing block width.","default":100,"min":0.01,"max":100000,"suffix":"px"},"viewportWidth":{"kind":"number","label":"Viewport width","default":1366,"min":1,"max":100000,"suffix":"px"},"viewportHeight":{"kind":"number","label":"Viewport height","default":768,"min":1,"max":100000,"suffix":"px"},"precision":{"kind":"number","label":"Decimal places","default":6,"min":0,"max":12,"step":1},"roundResults":{"kind":"toggle","label":"Use four decimal places","help":"Compatibility setting for saved conversions; changing precision turns it off.","default":false},"includeFormula":{"kind":"toggle","label":"Include formula","default":false}}},"trigger":{"mode":"live"},"capabilities":{"copy":true},"workbenchMark":{"text":"UNIT"},"labels":{"empty":"Enter a CSS value to convert.","ready":"Converted CSS values are ready.","running":"Converting CSS units…"},"content":{"howToUse":["Enter a number or paste a value with its unit. Use one value per line for a batch; a suffix overrides the From unit for that line.","Choose the target unit and the relevant font, percentage or viewport references. rem uses the root font; em uses the element font, except when converting font-size itself, which uses the parent.","Copy the result. Set decimal precision or include the calculation; invalid batch rows are reported without discarding valid conversions."],"limitations":["Percentages depend on the CSS property. Choose parent font size for font-size, or supply the actual reference length for a size; this tool cannot infer page layout.","Viewport units use the dimensions supplied here. Dynamic and small viewport variants, ch/ex, expressions such as calc(), and CSS variables are not evaluated.","Negative numbers are converted mathematically; whether a negative value is valid depends on the CSS property where you use it."],"faq":[{"q":"Why do rem and em give different results?","a":"rem always uses the root element's font size. em uses the element's own font size for lengths, or the parent's font size when setting font-size."},{"q":"What does 100% mean?","a":"It means the selected reference: the parent font size, or an explicit pixel length. The correct reference depends on the CSS property."}],"examples":[{"label":"32px in rem","text":"32"},{"label":"Mixed units","text":"16px\n2rem\n12pt"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.css-unit-converter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again.","csv.errors.columnRequired":"Enter at least one column name or number.","csv.errors.columnSelection":"Enter a name or number for every selected column, separated by commas.","csv.recovery.columnSelection":"Wrap header names containing commas in double quotes, for example: \"last,name\",2.","csv.errors.columnNumberMissing":"Column number {column} is out of range.","csv.errors.columnNameMissing":"Column {column} was not found.","csv.recovery.columnRange":"Use an exact header name, or a one-based column number from 1 to {count}."},"toolId":"devtools.csv-column-extractor","sharing":{"version":1},"app":"devtools","category":"csv-data-tools","keywords":["csv","column","extract","select","field","cut"],"name":"CSV Column Extractor","description":"Extract CSV columns by name or one-based number.","outputLanguage":"csv","previewLayout":"table","resultStats":"status-only","layout":"side-by-side","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\nAda,Admin\nLin,Editor"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]},"column":{"kind":"text","label":"Column","pane":"input","help":"Header names or one-based numbers, separated by commas. Press Enter to extract.","default":"name"}}},"trigger":{"mode":"manual","actionLabel":"Extract columns"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"COL"},"labels":{"empty":"Paste delimited data with a header row to extract columns.","ready":"Extracted columns are ready.","running":"Extracting CSV columns…"},"content":{"howToUse":["Paste delimited data whose first row is a header.","Enter header names (exact, case-sensitive matches) or one-based positions, separated by commas, such as firstName,lastName or 2,3.","Press Enter in the Column field or choose Extract columns. View the CSV as Raw or Table, then copy it or download extracted-columns.csv."],"limitations":["Separate selections with commas even when the input uses semicolons, tabs, or pipes. The output uses the selected data delimiter.","Repeated selections produce repeated columns in the requested order.","The header row is included in the output; delete the first line if you only want data.","A value that would be ambiguous on its own — one containing the delimiter, a quote, or a newline — is re-quoted using CSV rules.","Table previews show up to 1,000 data rows within row, cell, and 2 MiB text limits. Rows exceeding the remaining text budget are omitted; oversized headers use Raw view only. Large files also use a bounded raw preview; download the complete CSV for all selected rows."],"faq":[{"q":"Can I extract by position instead of name?","a":"Yes. Numbers are one-based column positions, so 1 is the first column. You can mix positions and header names, such as 2,lastName."},{"q":"What if a header contains a comma?","a":"An exact full-header match takes precedence. To combine a comma-containing header with others, quote it: \"last,name\",2. If firstName,lastName is itself a header but you want the two separate fields, enter \"firstName\",\"lastName\"."},{"q":"How do I drop the header?","a":"Remove the first line of the result. The tool always emits the header so the output stays self-describing."}],"examples":[{"label":"Extract a named column","text":"name,age\nAda,36\nLin,29"},{"label":"Select firstName,lastName","text":"id,firstName,lastName\n1001,Aarav,Sharma\n1002,Priya,Mehta","settings":{"column":"firstName,lastName"}}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-column-extractor' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again.","csv.errors.sameDelimiter":"Choose different source and target delimiters.","csv.recovery.sameDelimiter":"Pick a target delimiter that differs from the source, or use the CSV Formatter to normalise quoting in place."},"toolId":"devtools.csv-delimiter-converter","sharing":{"version":1},"app":"devtools","category":"csv-data-tools","keywords":["csv","tsv","delimiter","separator","semicolon","pipe","tab","convert"],"name":"CSV Delimiter Converter","description":"Change delimiters without corrupting quoted values.","outputLanguage":"csv","previewLayout":"table","input":{"kind":"text","language":"csv","label":"Delimited input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\nAda,Admin\nLin,Editor"},"settings":{"fields":{"from":{"kind":"select","label":"From","help":"The delimiter your input uses today.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]},"to":{"kind":"select","label":"To","help":"The delimiter you want in the output.","default":";","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"manual","actionLabel":"Convert delimiter"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"SEP"},"labels":{"empty":"Paste delimited rows to convert their separator.","ready":"Converted delimited data is ready.","running":"Converting delimiters…"},"content":{"howToUse":["Paste the rows exactly as exported. Do not hand-edit the quoting first — the whole point is that quoting is handled for you.","Set 'From' to the delimiter the input uses and 'To' to the one you need. They must differ.","Convert. Fields that contain the new delimiter, a quote, or a newline are re-quoted automatically, so nothing is corrupted on the way through."],"limitations":["Only comma, semicolon, tab, and pipe are supported, in either direction.","Every row must have the same number of fields; a ragged row is rejected rather than padded.","Line endings are normalised to `\\n` in the output regardless of the input's CRLF or CR.","This changes the delimiter only. Encoding, BOM, quoting style beyond what re-serialisation requires, and column order are untouched.","Editable text is capped at 2,000,000 characters. CSV and TSV files up to 100 MiB run in read-only streaming mode."],"faq":[{"q":"Why not just find-and-replace the delimiter?","a":"Because a comma inside a quoted field (`\"Smith, Ada\"`) is data, not a separator. A blind replace corrupts it. This tool parses the rows first and re-quotes on the way out."},{"q":"Which delimiter should I target for European Excel?","a":"Semicolon. Locales that use a comma as the decimal separator default to `;` for CSV, which is the usual reason to run this conversion."},{"q":"Can I convert from a delimiter to itself?","a":"No — that is rejected. If you want to normalise quoting without changing the separator, use the CSV Formatter."}],"examples":[{"label":"Comma to semicolon","text":"name,age\nAda,36"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-delimiter-converter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again."},"toolId":"devtools.csv-duplicate-remover","app":"devtools","slug":"csv-duplicate-remover","category":"csv-data-tools","keywords":["csv","duplicate","dedupe","unique","rows","distinct","clean"],"name":"CSV Duplicate Row Remover","description":"Remove repeated CSV data rows.","outputLanguage":"csv","previewLayout":"table","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","placeholder":"name,role\nAda,Admin\nAda,Admin"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","help":"Used for both reading and writing — the output keeps the same delimiter.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"manual","actionLabel":"Remove duplicates"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"ROW-"},"labels":{"empty":"Paste CSV with a header row to remove duplicate rows.","ready":"Deduplicated CSV is ready.","running":"Removing duplicate rows…"},"content":{"howToUse":["Paste the CSV. The first row is always kept as the header and is never treated as a duplicate.","Set the delimiter to match your file, then remove duplicates.","A row is a duplicate only when every field matches an earlier row exactly. The first occurrence is kept and the order of the surviving rows is unchanged.","If duplicates survive, check for stray whitespace or differing case — run the CSV Formatter first to trim cells, then dedupe."],"limitations":["Matching is exact and case-sensitive across the whole row. `Ada` and ` ada ` are different rows.","You cannot dedupe on a subset of columns — the comparison always uses every field.","Every row must have the same field count as the header; a ragged file is rejected.","Blank rows are dropped as part of parsing."],"faq":[{"q":"Which copy of a duplicate is kept?","a":"The first one, in the order it appears. Later copies are removed."},{"q":"Can I dedupe by a single key column?","a":"Not here — the whole row is the key. Extract the columns you care about first if you need key-based deduplication."},{"q":"Is the header row ever removed?","a":"No. It is split off before deduplication and always written back first."}],"examples":[{"label":"Repeated row","text":"name,age\nAda,36\nLin,29\nAda,36"},{"label":"No duplicates","text":"id,value\n1,a\n2,b"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-duplicate-remover' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again.","csv.matchedRows":"Matched rows","csv.scannedRows":"Scanned rows","csv.completeFilteredFile":"Complete filtered file","csv.errors.filterRequired":"Filter text is required.","csv.recovery.filterRequired":"Enter the text a row must contain to be kept.","csv.errors.filterColumnMissing":"Filter column was not found.","csv.recovery.filterColumn":"Use a header name from the first row, or a 1-based column number."},"toolId":"devtools.csv-filter","app":"devtools","category":"csv-data-tools","keywords":["csv","filter","rows","search","column","delimiter","spreadsheet"],"name":"CSV Filter","description":"Keep rows containing text, optionally in one column.","layout":"side-by-side","outputLanguage":"csv","previewLayout":"table","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\nAda,Admin\nLin,Editor"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","help":"Must match the file you pasted, or every row parses as one column.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]},"query":{"kind":"text","pane":"input","label":"Contains text","help":"Case-insensitive substring match. Required — an empty filter is rejected rather than returning every row.","default":"Admin"},"column":{"kind":"text","pane":"input","label":"In column (optional)","help":"A header name or a 1-based column number. Leave blank to search every column.","default":""}}},"trigger":{"mode":"manual","actionLabel":"Filter rows"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"FILT"},"labels":{"empty":"Paste CSV with a header row to filter its rows.","ready":"Filtered CSV is ready.","running":"Filtering CSV rows…"},"content":{"howToUse":["Paste the CSV including its header row — the header is always kept, so the output stays loadable by the same tools that read the input.","Pick the delimiter that matches the file. Comma is the default; European exports are usually semicolon-separated.","Type the text to match. Matching is case-insensitive and matches anywhere inside a cell, not just at the start.","Optionally restrict the search to one column by entering its header name or its 1-based position, then filter and copy or download the result."],"limitations":["Every row must have the same number of fields as the header. A ragged file is rejected rather than silently misaligned.","Matching is a plain substring test — there is no regular-expression, numeric-comparison, or date-range mode.","Only one filter term is supported per run. Chain runs to combine conditions.","CSV and TSV files up to 100 MiB are filtered row by row in a worker; only a bounded preview is kept in the page."],"faq":[{"q":"Is the header row ever removed?","a":"No. The header is always emitted first, even when no data row matches."},{"q":"Can I filter on a column by position?","a":"Yes. Enter a number and it is read as a 1-based column index; anything else is matched against the header names."},{"q":"Are quoted values with embedded delimiters handled?","a":"Yes. Quoting is parsed properly on the way in and re-applied on the way out, so a value containing the delimiter survives the round trip."},{"q":"Why is an empty filter rejected?","a":"An empty filter matches everything, which is a no-op that usually means the field was left blank by mistake."}],"examples":[{"label":"Roles table","text":"name,role\nAda,Admin\nLin,Editor"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-filter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again."},"toolId":"devtools.csv-formatter","app":"devtools","category":"csv-data-tools","keywords":["csv","format","normalize","quoting","trim","clean","tidy"],"name":"CSV Formatter","description":"Normalize CSV quoting and row structure.","outputLanguage":"csv","previewLayout":"table","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\n Ada ,Admin\nLin,Editor"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","help":"Used for both reading and writing — the output uses the same delimiter as the input.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"manual","actionLabel":"Format CSV"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"CSV+"},"labels":{"empty":"Paste CSV to normalize its quoting, spacing, and rows.","ready":"Formatted CSV is ready.","running":"Formatting CSV…"},"content":{"howToUse":["Paste the CSV you want tidied. Set the delimiter first — it is used to read the input and to write the output.","Format. Leading and trailing whitespace is stripped from every cell, and quoting is re-applied only where it is actually needed.","Compare the result with the original before replacing a source file — trimming is not always what you want for fixed-width or padded exports.","Line endings are normalized to `\\n`."],"limitations":["Every row must have the same field count as the first row; a ragged file is rejected rather than padded.","Whitespace inside a cell is preserved; only the leading and trailing whitespace of each cell is removed. That means a deliberately padded value loses its padding.","Blank rows are dropped, and a UTF-8 BOM is not stripped.","The delimiter is not changed — this normalizes quoting and spacing, it does not convert between formats."],"faq":[{"q":"Why did quotes disappear from some fields?","a":"Quoting is re-applied only where the value actually needs it: when it contains the delimiter, a double quote, or a line break. Unnecessary quotes are dropped."},{"q":"Will this change my numbers or dates?","a":"No. Every cell is treated as text and is written back byte-for-byte apart from the trim."},{"q":"Does it fix a ragged file?","a":"No. Rows with the wrong field count are reported as an error so you can find the real problem."}],"examples":[{"label":"Padded and quoted","text":"name,note\n Ada ,\"Hello, world\""},{"label":"Redundant quotes","text":"\"id\",\"value\"\n\"1\",\"ok\""}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-formatter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again.","csv.errors.sortColumnMissing":"Sort column was not found.","csv.recovery.sortColumn":"Use the exact header text, or the one-based column number."},"toolId":"devtools.csv-sorter","app":"devtools","category":"csv-data-tools","keywords":["csv","sort","order","column","ascending","descending"],"name":"CSV Sorter","description":"Sort CSV rows by a named or numbered column.","layout":"side-by-side","outputLanguage":"csv","previewLayout":"table","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","placeholder":"name,role\nLin,Editor\nAda,Admin"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]},"column":{"kind":"text","label":"Sort by column","help":"A header name, or a one-based column number.","default":"1"},"order":{"kind":"select","label":"Order","default":"asc","choices":[{"label":"Ascending","value":"asc"},{"label":"Descending","value":"desc"}]}}},"trigger":{"mode":"manual","actionLabel":"Sort rows"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"SORT"},"labels":{"empty":"Paste CSV with a header row to sort its rows.","ready":"Sorted CSV is ready.","running":"Sorting CSV rows…"},"content":{"howToUse":["Paste delimited data whose first row is a header. The header is never sorted — it stays on top.","Name the sort column either by its header text (an exact, case-sensitive match) or by its one-based position.","Choose ascending or descending, then sort. Comparison is natural: item2 sorts before item10, and case and accents are ignored."],"limitations":["The first row is always treated as a header. Headerless data loses its first row from the sort.","Only one sort key is supported; there is no secondary tiebreak, though the sort is stable so the original order survives among equal keys.","Numbers are compared by natural-language rules, not numerically — mixed formats such as 1e3 or 1,000 will not order the way arithmetic would."],"faq":[{"q":"Why was my column not found?","a":"Header matching is exact and case-sensitive, and a stray leading space counts. Use the one-based column number if the header text is awkward."},{"q":"Does sorting change my data?","a":"Only the row order. Field values, quoting, and the delimiter are re-serialised exactly as parsed."}],"examples":[{"label":"Sort by first column","text":"name,age\nLin,29\nAda,36"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-sorter' AND spec IS NULL;
