nguage":"markdown","previewLayout":"table","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\nAda,Admin\nLin,Editor"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","help":"The character that separates fields in your input.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"manual","actionLabel":"Convert to Markdown"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"C>M"},"labels":{"empty":"Paste CSV with a header row to build a Markdown table.","ready":"Markdown table is ready.","running":"Building Markdown table…"},"content":{"howToUse":["Paste your rows, including the header row — the first row becomes the table header.","Set the delimiter to match your data. Exporting from a spreadsheet as tab-separated and choosing Tab avoids most quoting problems.","Convert and paste the result straight into a README, a pull request description, or any GitHub-flavoured Markdown document."],"limitations":["Every row must have the same number of fields as the header row; a ragged row is rejected rather than padded.","The first row is always treated as the header. There is no headerless mode.","Alignment is not configurable — the separator row is always `---`.","Pipes and backslashes inside cells are escaped, and embedded newlines become `<br>`, which renders on GitHub but not in every Markdown flavour.","Quoted fields are parsed per RFC 4180, so a comma inside `\"a,b\"` stays in one cell."],"faq":[{"q":"My data has commas inside a field. Will it break?","a":"Not if the field is quoted (`\"Smith, Ada\"`). Quoted fields are parsed properly. Unquoted commas are genuinely field separators and will split the cell."},{"q":"Why does it say every row must have the same number of fields?","a":"A row with more or fewer fields than the header would silently misalign the table. Fix the ragged row, or add the missing empty fields, and run again."},{"q":"Can I control column alignment?","a":"Not from this tool. Edit the `---` separator row afterwards to `:---`, `:---:`, or `---:`."}],"examples":[{"label":"Two columns","text":"name,age\nAda,36"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-to-markdown-table' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again.","csv.completeHtmlTable":"Complete HTML table"},"toolId":"devtools.csv-to-table","app":"devtools","category":"csv-data-tools","keywords":["csv","html","table","convert","markup","thead","accessible"],"name":"CSV to Table","description":"Convert CSV to an accessible HTML table.","previewLayout":"table","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\nAda,Admin"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","help":"Pick the character that separates fields in your source data.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"manual","actionLabel":"Build table"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"TBL"},"labels":{"empty":"Paste CSV rows to generate HTML table markup.","ready":"HTML table markup is ready.","running":"Generating HTML table…"},"content":{"howToUse":["Paste the CSV. The first row becomes the `<thead>` row, and every remaining row becomes a `<tbody>` row.","Set the delimiter to match your export before building.","Build, then copy the markup into your page. It is a plain semantic `<table>` with no classes, inline styles, or wrapper elements, so your own CSS applies unchanged.","Every cell is HTML-escaped on the way out, so pasting the result into a page cannot introduce markup that came from the data."],"limitations":["All rows must have the same field count as the header; a ragged file is rejected.","No `scope`, `caption`, `colgroup`, or `id`/`headers` attributes are emitted. For a complex table with merged or multi-level headers you will need to add those by hand.","There is no styling and no column-type detection — numbers stay left-aligned text.","Blank rows are dropped."],"faq":[{"q":"What makes the output accessible?","a":"The header row is emitted as `<th>` inside `<thead>`, which is what screen readers use to announce each cell's column. Add a `<caption>` yourself for a fuller description."},{"q":"Can data in the CSV inject HTML?","a":"No. `&`, `<`, `>`, `\"`, and `'` are escaped in every header and cell."},{"q":"How is this different from CSV Viewer?","a":"The markup is identical. CSV Viewer previews live as you type; this tool is aimed at producing markup you copy into a page."}],"examples":[{"label":"Small table","text":"name,role\nAda,Admin"},{"label":"Tab-separated","text":"id\tvalue\n1\ttrue"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-to-table' AND spec IS NULL;
