ble","layout":"side-by-side","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,note\nAda,Hello"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Convert to TSV"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"C>T"},"labels":{"empty":"Paste comma-separated rows to convert them to TSV.","ready":"Tab-separated text is ready.","running":"Converting CSV to TSV…"},"content":{"howToUse":["Paste comma-separated rows, quotes and all. Quoted fields containing commas are parsed correctly and unquoted on the way out.","Convert. Fields are re-joined with tab characters, and only fields that still need quoting keep their quotes.","Paste the TSV straight into a spreadsheet — tab-separated text pastes into cells without an import dialog."],"limitations":["The input delimiter is fixed at a comma. Semicolon- or pipe-delimited data needs a delimiter converter first.","Every row must have the same number of fields; a ragged row is rejected rather than padded.","A field containing a literal tab or newline is re-quoted, which some naive TSV readers do not handle."],"faq":[{"q":"What happens to a value like \"Hello, world\"?","a":"The comma was only significant to CSV, so the quotes are dropped and the value becomes a plain tab-delimited field."},{"q":"Is the header row treated specially?","a":"No. Row one is converted like every other row, which is what you want when pasting into a spreadsheet."}],"examples":[{"label":"Quoted field","text":"name,note\nAda,\"Hello, world\""}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-to-tsv' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again.","csv.valid":"Valid CSV","csv.validDetail":"{columns, plural, one {# column} other {# columns}} · {rows, plural, one {# data row} other {# data rows}}","csv.errors.emptyHeader":"Every CSV column needs a header.","csv.errors.duplicateHeader":"CSV headers must be unique."},"toolId":"devtools.csv-validator","app":"devtools","category":"csv-data-tools","keywords":["csv","validate","headers","quoting","rows","lint"],"name":"CSV Validator","description":"Validate CSV quoting, headers, and row widths.","layout":"side-by-side","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,age\nAda,36"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"manual","actionLabel":"Validate CSV"},"capabilities":{"copy":true},"workbenchMark":{"text":"CSV?"},"labels":{"empty":"Paste CSV rows to validate their headers and field counts.","ready":"CSV structure is valid.","running":"Validating CSV structure…"},"content":{"howToUse":["Paste the CSV and pick the delimiter it actually uses — a semicolon file checked as comma-separated will look like one giant column.","Validate. The check covers quoting, a non-empty unique header row, and a consistent field count on every row.","A pass reports the column count and the number of data rows, which is a quick sanity check against what you expected to export."],"limitations":["Only structure is validated. Column types, value ranges, and required fields are not checked.","The first row is always treated as the header. A headerless file will report its first data row as headers.","Header uniqueness is compared after trimming, so \"name\" and \"name \" count as a duplicate."],"faq":[{"q":"What counts as an invalid row?","a":"Any row whose field count differs from the header row, or an unterminated quoted field."},{"q":"Does it check for a trailing newline?","a":"No. A trailing newline is normal and does not create an extra empty row."}],"examples":[{"label":"Two columns","text":"name,age\nAda,36"}]}}$spec$::json, updated_at = now()
