UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again."},"toolId":"devtools.csv-viewer","app":"devtools","category":"csv-data-tools","keywords":["csv","viewer","table","tsv","delimited","preview","spreadsheet"],"name":"CSV Viewer","description":"Render delimited data as an HTML table.","input":{"kind":"text","language":"csv","label":"CSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name,role\nAda,Admin\nLin,Editor"},"settings":{"fields":{"delimiter":{"kind":"select","label":"Delimiter","help":"Pick the character that separates fields. Semicolon is common in European exports; tab means the file is really TSV.","default":",","choices":[{"label":"Comma","value":","},{"label":"Semicolon","value":";"},{"label":"Tab","value":"\t"},{"label":"Pipe","value":"|"}]}}},"trigger":{"mode":"live","debounceMs":200},"capabilities":{"copy":true},"optionsPanel":{"defaultCollapsed":true},"workbenchMark":{"text":"VIEW"},"labels":{"empty":"Paste delimited rows to preview them as a table.","ready":"CSV table preview is ready.","running":"Rendering table preview…"},"content":{"howToUse":["Paste the delimited text. The first row is treated as the header and becomes the table's `<th>` cells.","Set the delimiter to match your data. Getting it wrong is the usual reason a file appears as one giant column.","The preview updates as you type. Every cell is HTML-escaped, so a value containing `<script>` shows as text and never executes.","Quoted fields containing the delimiter, quotes, or newlines are parsed correctly — leave the quoting as your exporter wrote it."],"limitations":["Every row must have the same number of fields as the first row. A ragged file is rejected rather than padded.","Files up to 100 MiB are validated completely in a worker while the table stays bounded to the first 1,000 data rows.","There is no sorting, filtering, or column typing — this is a faithful preview, not a spreadsheet.","Blank rows are dropped, and a UTF-8 BOM on the first header cell is not stripped here."],"faq":[{"q":"Why is everything in one column?","a":"The delimiter does not match the file. Switch between comma, semicolon, tab, and pipe until the columns split."},{"q":"Is my data uploaded?","a":"No. Parsing and rendering both happen in this browser tab."},{"q":"Can a malicious CSV inject HTML into the preview?","a":"No. Every header and cell is escaped before it is placed in the markup."}],"examples":[{"label":"Two data rows","text":"name,role\nAda,Admin\nLin,Editor"},{"label":"Quoted field","text":"name,note\nAda,\"Hello, world\""}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.csv-viewer' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCurl.quote":"cURL command contains an unfinished quote or escape.","sharedCurl.start":"Command must start with curl.","sharedCurl.header":"Every cURL header needs a name and value.","sharedCurl.absolute":"cURL command needs an absolute http or https URL.","sharedCurl.protocol":"cURL URL must use http or https.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","curl.flagsNotConverted":"Some cURL flags were not converted","curl.unsupportedFlags":"Unsupported cURL flags were ignored: {flags}.","workspace.unable_to_convert_54606f":"Unable to convert","workspace.output_language_bf3bcc":"Output language","workspace.javascript_b27ad0":"JavaScript","workspace.typescript_ed0504":"TypeScript","workspace.module_format_ba8e98":"Module format","workspace.no_import_18a0da":"No import","workspace.es_module_import_9044c4":"ES module import","workspace.commonjs_require_190f0a":"CommonJS require","workspace.request_style_71ed43":"Request style","workspace.loadExample":"Load example","workspace.aliases":"Aliases"},"toolId":"devtools.curl-to-axios","app":"devtools","category":"jwt-api-tools","keywords":["curl","axios","convert","http request","javascript","api client","code generator"],"name":"cURL to Axios","description":"Convert common cURL requests to Axios and surface flags that cannot be represented.","layout":"stacked","optionsPanel":{"title":"OUTPUT & RUNTIME","note":"Forms, cookie jars, proxies, redirects, certificates, uploads, and unsupported shell syntax are not converted."},"input":{"kind":"text","language":"bash","label":"cURL command","placeholder":"curl https://api.example.com/users"},"settings":{"fields":{"moduleFormat":{"kind":"select","label":"Module format","help":"Add an Axios import when the snippet should stand on its own.","default":"none","choices":[{"label":"No import","value":"none"},{"label":"ESM import","value":"esm"},{"label":"CommonJS require","value":"commonjs"}]},"requestStyle":{"kind":"select","label":"Request style","help":"Choose a config call, explicit axios.request, or a method alias such as axios.get.","default":"config","choices":[{"label":"axios(config)","value":"config"},{"label":"axios.request(config)","value":"request"},{"label":"Method alias","value":"alias"}]},"outputLanguage":{"kind":"select","label":"Output language","help":"TypeScript adds an Axios response type so generated data must be narrowed before use.","default":"javascript","choices":[{"label":"JavaScript","value":"javascript"},{"label":"TypeScript","value":"typescript"}]}}},"trigger":{"mode":"live","debounceMs":150},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"AXIO"},"labels":{"empty":"Paste a cURL command to generate Axios code.","ready":"Axios request code is ready.","running":"Generating Axios code…"},"content":{"howToUse":["Paste the whole command, starting with `curl`. Quoting is parsed the way a shell would, so headers such as `-H 'Authorization: Bearer …'` come across intact.","Choose the module format, request-call style, and JavaScript or TypeScript output. The result updates as you edit.","Check the result before running it: strip any credential that came along in a header, and confirm the method matches what you intended."],"limitations":["A subset of flags is understood: `-X/--request`, `-H/--header`, `-d/--data/--data-raw/--data-binary`, and `-u/--user`. Anything else — `-F`, `--form`, `-b`, `--cookie`, `-k`, `--compressed`, `-o`, proxy and TLS flags — is ignored and reported in a warning, not translated.","As with curl, supplying a body promotes an unspecified method from GET to POST.","A JSON body is parsed and embedded as an object; anything that is not valid JSON is passed through as a string. No `Content-Type` header is inferred either way.","`-u user:pass` becomes a Base64 `Authorization: Basic` header, so the credential ends up in plain sight in the generated code. Replace it with an environment variable before committing.","The URL must be absolute http or https. Repeated `-d` flags do not concatenate the way curl does — only the last one is used."],"faq":[{"q":"Why is my `--form` upload missing?","a":"Multipart flags are not supported. Build a `FormData` object by hand and pass it as `data`."},{"q":"Do I need to set Content-Type for a JSON body?","a":"Axios sets `application/json` automatically when `data` is a plain object, which is what a parsed JSON body becomes here. Add the header explicitly if you send a string."},{"q":"Is my command sent anywhere?","a":"No. Parsing and code generation happen entirely in this browser tab, and no request is made."}],"examples":[{"label":"GET with a bearer token","text":"curl https://api.example.com/users -H 'Authorization: Bearer token'"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.curl-to-axios' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCurl.quote":"cURL command contains an unfinished quote or escape.","sharedCurl.start":"Command must start with curl.","sharedCurl.header":"Every cURL header needs a name and value.","sharedCurl.absolute":"cURL command needs an absolute http or https URL.","sharedCurl.protocol":"cURL URL must use http or https.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","workspace.output_language_bf3bcc":"Output language","workspace.javascript_b27ad0":"JavaScript","workspace.typescript_ed0504":"TypeScript"},"toolId":"devtools.curl-to-fetch","app":"devtools","category":"jwt-api-tools","keywords":["curl","fetch","javascript","http","convert","api","request"],"name":"cURL to Fetch","description":"Convert a common cURL request to browser fetch code.","layout":"stacked","outputLanguage":"javascript","input":{"kind":"text","language":"bash","label":"cURL command","placeholder":"curl https://api.example.com/items -H 'Content-Type: application/json' -d '{\"name\":\"SmartTools\"}'"},"settings":{"fields":{"outputLanguage":{"kind":"select","label":"Output language","help":"TypeScript keeps parsed JSON typed as unknown until you validate its shape.","default":"javascript","choices":[{"label":"JavaScript","value":"javascript"},{"label":"TypeScript","value":"typescript"}]},"responseHandling":{"kind":"select","label":"Response handling","help":"Parse successful JSON responses or keep the raw response.","default":"throw-json","choices":[{"label":"Throw on error + parse JSON","value":"throw-json"},{"label":"Keep raw response","value":"raw"}]},"executionStyle":{"kind":"select","label":"Execution style","help":"Use top-level await or wrap the request in an async function.","default":"top-level-await","choices":[{"label":"Top-level await","value":"top-level-await"},{"label":"Async function","value":"async-function"}]}}},"trigger":{"mode":"manual","actionLabel":"Convert to fetch"},"capabilities":{"copy":true},"workbenchMark":{"text":"FET"},"labels":{"empty":"Paste a cURL command to generate Fetch code.","ready":"Fetch request code is ready.","running":"Generating Fetch code…"},"content":{"howToUse":["Paste a curl command — the 'Copy as cURL' output from your browser's network panel works well.","Convert. Choose a status check with JSON parsing or keep the raw response, using top-level await or an async wrapper.","Read the generated code before running it. If the original command carried a credential in a header or via `-u`, that credential is now sitting in your source — move it to an environment variable.","JSON handling assumes a JSON response. Keep the raw response when you need text, blobs, streaming, or custom error policy."],"limitations":["A practical subset of curl is supported: `-X`/`--request`, `-H`/`--header`, `-d`/`--data`/`--data-raw`/`--data-binary`, and `-u`/`--user`. Every other flag is ignored silently — including `-F` (multipart), `--compressed`, `-k`, `-o`, and cookie flags.","The URL must be absolute and http or https. A relative path or another scheme is rejected.","`-u user:pass` becomes a Base64 `Authorization: Basic` header, which is encoding, not encryption — the credential is plainly readable in the generated code.","Multiple `-d` flags are not concatenated the way curl concatenates them; only the last one survives.","`credentials`, `mode`, and `redirect` are not set, so fetch's defaults apply. Cross-origin behaviour may differ from curl's."],"faq":[{"q":"Why did my `-F` upload disappear?","a":"Multipart form flags are not supported. Build a `FormData` object by hand and pass it as the body."},{"q":"Why did the method become POST when I never asked for it?","a":"That is curl's own rule: supplying a body with `-d` implies POST unless `-X` says otherwise. The conversion keeps that behaviour."},{"q":"Is it safe to paste a command containing my API key?","a":"The conversion runs entirely in this browser tab and nothing is uploaded. The key does end up in the generated snippet, so do not commit that snippet as-is."}],"examples":[{"label":"POST with a JSON body","text":"curl -X POST https://api.example.com/users -H 'Content-Type: application/json' -d '{\"name\":\"Ada\"}'"},{"label":"Simple GET","text":"curl https://api.example.com/health"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.curl-to-fetch' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedDate.invalid":"{endpoint, select, start {Start date} end {End date} other {Date}} is not a valid date or timestamp.","sharedDate.required":"{endpoint, select, start {Start date} end {End date} other {Date}} is required.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","execution.errors.time-invalid":"{endpoint, select, start {Start time} end {End time} other {Time}} must use 24-hour HH:MM or HH:MM:SS format.","execution.recovery.time-invalid":"Enter {endpoint, select, start {start time} end {end time} other {time}} from 00:00 through 23:59:59.","execution.exactDuration":"{days} days ({hours} hours)","execution.duration":"{days} days"},"toolId":"devtools.date-difference","app":"devtools","slug":"date-difference","category":"date-time-tools","keywords":["date difference","elapsed","duration","days between","timestamp","hours"],"name":"Date Difference Calculator","description":"Calculate elapsed time between two dates.","layout":"side-by-side","input":{"kind":"fields","label":"Start and end dates","fields":[{"channel":"text","label":"Start date","placeholder":"2026-01-01T00:00:00Z","required":true},{"channel":"secondary","label":"End date","placeholder":"2026-01-03T00:00:00Z","required":true}]},"settings":{"fields":{"startTime":{"kind":"text","label":"Start time","help":"Optionally set the start time in 24-hour format.","default":"","placeholder":"09:00","maxLength":8,"pane":"input"},"endTime":{"kind":"text","label":"End time","help":"Optionally set the end time in 24-hour format.","default":"","placeholder":"17:30","maxLength":8,"pane":"input"},"timezone":{"kind":"select","label":"Timezone","help":"Preserve entered offsets or reinterpret the clock time as local or UTC.","default":"as-entered","choices":[{"label":"As entered","value":"as-entered"},{"label":"Browser local time","value":"local"},{"label":"UTC","value":"utc"}],"pane":"input","span":"full"},"exactDuration":{"kind":"toggle","label":"Exact duration","help":"Include the total hours with the elapsed days.","default":true}}},"trigger":{"mode":"live"},"capabilities":{"copy":true},"workbenchMark":{"text":"DAYS"},"labels":{"empty":"Enter start and end dates to calculate the elapsed time.","ready":"Date difference is ready.","running":"Calculating date difference…"},"content":{"howToUse":["Enter the start date and the end date. ISO 8601 is the safest format — include the Z or an offset so the answer does not depend on your machine's time zone.","A bare number is read as a timestamp: values under 1e11 are treated as Unix seconds, larger ones as milliseconds.","The result updates as you type and shows days rounded to three decimals, with hours when Exact duration is enabled."],"limitations":["An end date before the start date yields a negative result rather than an error, which is usually what you want but is easy to misread.","Days are fixed 24-hour periods. Across a daylight-saving transition the calendar-day count and this figure disagree by an hour.","Leap seconds do not exist in JavaScript time, so they are not counted.","A date string without a time zone is interpreted by the browser, which is not always UTC. Prefer explicit offsets."],"faq":[{"q":"Why do I get 2 days and not 2?","a":"Both figures are trimmed of trailing zeros, so a whole number is printed as a whole number. A partial gap shows up to three decimal places."},{"q":"Which formats are accepted?","a":"Anything the browser's Date parser understands, plus bare Unix seconds and milliseconds. ISO 8601 with an explicit offset is the only form that is unambiguous everywhere."}],"examples":[{"label":"Two days apart","text":"2026-01-01T00:00:00Z","secondary":"2026-01-03T00:00:00Z"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.date-difference' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.deletingPdfPage":"Deleting PDF page","readiness.choosePages":"Choose at least one page to delete.","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.noFiles":"Choose a PDF to delete pages from.","errors.emptyDocument":"At least one PDF page must remain.","workspace.selected_pages_are_84d337":"Selected pages are removed. At least one page must remain.","workspace.pages_to_delete_570cdf":"Pages to delete"},"toolId":"media.delete-pdf-pages","app":"media","category":"pdf-organization","keywords":["pdf","delete pages","remove pages","drop pages","trim","pages","organize","cleanup"],"name":"Delete PDF Pages","description":"Remove selected pages while keeping a valid PDF.","input":{"kind":"files","label":"PDF document","accept":"application/pdf","multiple":false,"engine":"pdf","maxBytes":52428800,"maxTotalBytes":52428800,"inspect":true},"settings":{"fields":{"pages":{"kind":"text","label":"Pages to delete","help":"Ranges such as 1-3,5, or odd / even. Empty means nothing is deleted, which is the starting state.","default":"","placeholder":"e.g. 1-3,5"}}},"trigger":{"mode":"manual","actionLabel":"Delete pages"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"PG-"},"labels":{"empty":"Add a PDF to remove pages.","ready":"Page selection is ready.","running":"Deleting pages…"},"content":{"howToUse":["Add a single PDF. Page thumbnails are rendered in your browser so you can see exactly what you are removing — nothing is uploaded.","Select the pages to delete in the preview, or type them as ranges such as 1-3,5. Nothing is selected until you choose, so a mis-click cannot silently drop a page.","Check the selection. Deletion is applied to the copy you download; the file you added is never modified.","Delete and download. At least one page must remain, so a selection covering the whole document is rejected."],"limitations":["At least one page must survive. A PDF with no pages is not a valid document, so an all-pages selection is refused.","Deleting a page does not shrink the file proportionally: shared resources such as fonts and embedded images may still be referenced by the pages that remain.","Bookmarks and internal links that pointed at a deleted page are left dangling.","Structural jobs are capped at 500 pages, and the PDF must be 50 MiB or smaller.","Encrypted or password-protected PDFs are rejected, and deleting pages invalidates an existing digital signature."],"faq":[{"q":"Why did nothing get deleted?","a":"The selection was empty, which is the deliberate starting state for a destructive tool. Pick the pages in the preview or type a range first."},{"q":"Can I delete every page?","a":"No. A PDF must contain at least one page, so that run is rejected rather than producing a file no reader will open."},{"q":"Why is the output barely smaller?","a":"Fonts, images, and other resources are often shared between pages, so removing a page frees only what nothing else references. Run Compress PDF afterwards if size matters."},{"q":"Is the original file changed?","a":"Never. Everything happens on a copy in your browser and you download the result; the file you selected is untouched."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.delete-pdf-pages' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","execution.errors.diagram-invalid":"Mermaid diagram is invalid: {diagnostic}","execution.errors.render-failed":"Mermaid diagram is invalid: render failed","execution.recovery.diagram-invalid":"Check the first line declares a diagram type, and quote labels that contain brackets or punctuation.","execution.errors.diagram-too-large":"Mermaid diagram code is too large.","execution.recovery.diagram-too-large":"Split the diagram into smaller ones — anything this size is unreadable anyway.","execution.errors.dom-required":"Mermaid diagram rendering requires a browser.","execution.recovery.dom-required":"Open this tool in a browser tab; Mermaid measures rendered text to lay out the diagram.","workspace.copy_svg_fde90b":"Copy SVG"},"toolId":"devtools.diagram-generator","app":"devtools","category":"diagram-tools","keywords":["mermaid","diagram","flowchart","sequence diagram","svg","graph","documentation"],"name":"Diagram Generator","description":"Render Mermaid diagram code in the browser.","layout":"side-by-side","input":{"kind":"text","label":"Mermaid diagram code","language":"mermaid","placeholder":"flowchart LR\n  A[Input] --> B[Transform] --> C[Output]","maxLength":200000},"settings":{"fields":{}},"trigger":{"mode":"live","debounceMs":160},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"DIAG"},"labels":{"empty":"Enter Mermaid source to render a diagram.","ready":"Diagram preview is ready.","running":"Rendering diagram…"},"content":{"howToUse":["Start with a diagram type on the first line — `flowchart LR`, `sequenceDiagram`, `classDiagram`, `erDiagram`, `gantt` — because Mermaid decides everything else from it.","Write the body underneath. The diagram re-renders as you pause typing, so a syntax error shows up on the line you just wrote rather than after a long edit.","For flowcharts, set direction in the source: `flowchart LR` runs left to right; `flowchart TD` runs top to bottom.","Open Download and choose SVG for a diagram that stays sharp at any size, or PNG for an image with a white background."],"limitations":["Rendering requires a browser — Mermaid measures text to lay the diagram out, so there is no server-side render and no static export outside a tab.","Diagram source is capped at 200,000 characters. A diagram anywhere near that size is unreadable long before it is rejected.","Mermaid runs in its strict security mode: raw HTML in node labels and click handlers are not executed.","Themes, custom fonts, and CSS overrides are not exposed. The SVG carries its own inline styles, which you can edit after downloading it."],"faq":[{"q":"Is my diagram source uploaded?","a":"No. Mermaid runs in this browser tab and the source never leaves your machine."},{"q":"Why does my diagram fail with a parse error?","a":"Usually the first line: the diagram type and direction must come first. After that, the most common causes are unescaped punctuation in a label and inconsistent indentation in a sequence diagram."},{"q":"How do I get a PNG instead of an SVG?","a":"Open the download menu above the preview and choose diagram.png. The image is created in your browser only when you select PNG. Choose diagram.svg if you need a scalable vector file."},{"q":"Can I use a label containing brackets or quotes?","a":"Yes, but wrap it in double quotes — `A[\"a [bracketed] label\"]` — otherwise Mermaid reads the bracket as syntax."}],"examples":[{"label":"Flowchart","text":"flowchart LR\n  A[Input] --> B[Transform] --> C[Output]"},{"label":"Sequence diagram","text":"sequenceDiagram\n  Client->>API: POST /orders\n  API-->>Client: 201 Created"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.diagram-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","sharedUrl.domainRequired":"Domain is required.","sharedUrl.domain":"Enter a valid domain name.","sharedUrl.absolute":"Enter an absolute http or https URL.","dns.type":"Type","dns.name":"Name","dns.value":"Value","dns.ttlSeconds":"TTL (seconds)","dns.lookupStatus":"Lookup status","dns.columnStatus":"Status","dns.columnDetails":"Details","dns.status.notFound":"Domain not found","dns.status.failed":"Resolver failed","dns.status.invalid":"Invalid response","dns.status.incomplete":"Incomplete response","dns.status.returned":"Records returned","dns.status.none":"No records","dns.details.notFound":"The resolver reports that this name does not exist (DNS status 3, NXDOMAIN). Check the spelling.","dns.details.failed":"The resolver {status, select, 2 {could not complete the lookup} 5 {refused the lookup} other {returned an error}} (DNS status {status}). Try again; this does not mean the domain has no records.","dns.details.invalid":"The resolver response could not be read reliably. Try again or inspect the raw response.","dns.details.truncated":"The resolver truncated its response; {count, number} readable answers are shown. Try again or inspect the raw response.","dns.details.skipped":"{count, number} readable answers are shown; invalid answer entries were skipped. Try again or inspect the raw response.","dns.details.returned":"{count, plural, one {# answer returned.} other {# answers returned.}} Aliases may appear under their actual record type.","dns.details.none":"The resolver returned no {type} answers. This alone does not indicate a problem with the domain.","dns.verdict.notFound":"Domain not found: {domain}","dns.verdict.notFoundDetail":"The public resolver could not find this name. Check the domain spelling and try again.","dns.verdict.failed":"DNS lookup failed for {domain}","dns.verdict.warning":"DNS lookup warning for {domain}","dns.verdict.warningDetail":"{count, plural, one {# DNS record returned.} other {# DNS records returned.}} Some lookups were unsuccessful or incomplete; see the affected rows before relying on these results.","dns.verdict.found":"{count, plural, one {# DNS record found} other {# DNS records found}} for {domain}","dns.verdict.foundDetail":"Queried {types}. Repeated answers are shown once.","dns.verdict.none":"No DNS records found for {domain}","dns.verdict.noneDetail":"The resolver returned no answers for {types}. Try another record type or verify the domain name.","dns.errors.recordType":"DNS record types may only include A, AAAA, MX, TXT, NS, and CNAME.","dns.recovery.recordType":"Select one or more of those six record types.","dns.errors.unreachable":"DNS Checker could not reach the public DNS service.","dns.recovery.network":"Check your network connection and try again.","dns.errors.lookup":"DNS lookup failed ({status}).","dns.recovery.lookup":"The public resolver rejected the query. Try again in a moment.","dns.errors.response":"DNS service returned an invalid response.","workspace.dns_records_00ce58":"DNS records","workspace.type_baaddf":"Type","workspace.explanation_16ee46":"Explanation","workspace.record_value_f7b42a":"Record value","workspace.cache_time_72f91b":"Cache time","workspace.copy_value_c019c0":"Copy value","workspace.empty_value_19ad22":"Empty value","workspace.for_98502e":"For ","workspace.this_domain_declares_30129b":"This domain declares that it does not accept email.","workspace.the_first_number_5715af":"The first number is priority; lower numbers are preferred.","workspace.not_supplied_8b427d":"Not supplied","workspace.showing_part_of_3b2915":"Showing part of the records. Download the complete output for all answers.","workspace.a_missing_record_20741a":"A missing record type does not by itself indicate a problem with the domain.","workspace.ttl_is_the_3d47e3":"TTL is the resolver’s remaining cache time in seconds, not the age of the record.","workspace.record_types_2e5209":"Record types","workspace.all_record_types_da2d85":"All record types","workspace.select_record_types_d54710":"Select record types","workspace.choose_record_types_7a9946":"Choose record types","workspace.choose_one_or_0d5d48":"Choose one or more types. Press Enter in Domain name to check.","workspace.resultRecords":"DNS result records","workspace.lookupComplete":"DNS lookup complete","workspace.dnsRecord":"DNS record","workspace.records.A":"IPv4 address","workspace.records.AAAA":"IPv6 address","workspace.records.MX":"Mail server","workspace.records.TXT":"Text and email verification","workspace.records.NS":"Nameserver","workspace.records.CNAME":"Domain alias","workspace.noRecords":"No {type} records found","workspace.status.Other record type returned":"Other record type returned","workspace.status.Domain not found":"Domain not found","workspace.status.Resolver failed":"Resolver failed","workspace.status.Invalid response":"Invalid response","workspace.status.Incomplete response":"Incomplete response","workspace.forName":"For {name}","workspace.copyRecord":"Copy {type} record value","workspace.selectType":"Select at least one record type.","workspace.chooseTypes":"Choose record types from the list.","workspace.invalidDomain":"Enter a valid domain name.","workspace.domainRequired":"Domain is required."},"toolId":"devtools.dns-checker","slug":"dns-checker","app":"devtools","category":"seo-domain-tools","keywords":["dns","mx","txt","spf","nameserver","cname","lookup","dig"],"name":"DNS & Email Records Checker","description":"Query public DNS-over-HTTPS records.","layout":"side-by-side","resultView":{"default":"preview","previewLabel":"Preview"},"input":{"kind":"fields","label":"Domain","fields":[{"channel":"text","label":"Domain name","placeholder":"example.com","required":true,"multiline":false,"maxLength":253}]},"settings":{"fields":{"types":{"kind":"text","label":"Record types","help":"Select one or more record types to look up.","default":"A,AAAA,MX,TXT,NS,CNAME","pane":"input"},"recordView":{"kind":"select","label":"Raw output format","help":"Choose what Raw, Copy, and Download contain. Preview always shows readable records.","default":"records","choices":[{"label":"Records (tab-separated)","value":"records"},{"label":"Resolver response (JSON)","value":"raw"}]},"recursive":{"kind":"toggle","label":"Use recursive lookup","help":"On by default. Turning it off asks the resolver to answer only from its own cache.","default":true},"includeTtl":{"kind":"toggle","label":"Include TTL","help":"Shows each record's remaining cache lifetime in seconds.","default":true},"checkDnssec":{"kind":"toggle","label":"Check DNSSEC","help":"Asks the resolver to validate signatures rather than returning unverified data.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Check DNS"},"capabilities":{"copy":true,"download":true,"network":true},"workbenchMark":{"text":"DNS"},"labels":{"result":"DNS records","empty":"Enter a public domain to look up its DNS records.","ready":"DNS lookup results are ready.","running":"Looking up public DNS records…"},"content":{"howToUse":["Enter a domain. A full URL works too — the hostname is extracted, lowercased, and a leading www. is dropped before the query.","Choose the record types you care about: A and AAAA for where the site points, MX and TXT for mail delivery and SPF/DKIM/DMARC, NS for delegation, CNAME for aliases.","Click Check DNS or press Enter in the domain field. Selected types are queried in parallel, and each answer returns its type, TTL, and value.","Read the Preview for labeled records and lookup status. Use Raw for exact output, and choose Resolver response (JSON) in settings to inspect the resolver's full response."],"limitations":["Queries go to a public DNS-over-HTTPS resolver, so you see what that resolver sees. Split-horizon DNS, internal zones, and freshly changed records may differ from your own view.","Only A, AAAA, MX, TXT, NS, and CNAME are permitted. Any other type is rejected rather than forwarded — the domain you type drives an outbound request, so the query surface is deliberately fixed.","TTL is the resolver's remaining cache time, not the value published in your zone file. A low TTL here often just means the record was queried recently.","Each lookup times out after ten seconds. A slow or unreachable resolver reports a failure rather than hanging.","The DNSSEC option asks the resolver to validate; it does not perform independent chain-of-trust verification in your browser."],"faq":[{"q":"Why do the results differ from `dig` on my machine?","a":"Your local resolver, your ISP, and the public resolver used here can all hold different cached copies. Right after a change, a difference between them is normal and resolves as TTLs expire."},{"q":"How do I check my SPF or DMARC record?","a":"Query TXT. SPF appears as a value starting with v=spf1 on the domain itself; DMARC lives on the _dmarc subdomain, so query that name directly."},{"q":"My MX lookup is empty — is mail broken?","a":"Not necessarily. Check the parent domain: mail for a subdomain is usually delivered via the parent's MX records."},{"q":"Does the domain I type get logged?","a":"The lookup is a request to a public DNS resolver, which sees the queried name like any DNS query does. Nothing is stored by this tool."}],"examples":[{"label":"Public domain","text":"example.com"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.dns-checker' AND spec IS NULL;
