UPDATE managed_tools SET spec = $spec${"toolId":"devtools.json-escape","sharing":{"version":1},"app":"devtools","category":"json-tools","keywords":["json","escape","string","quote","backslash","stringify","encode"],"name":"JSON Escape","description":"Escape a raw string for use inside JSON.","layout":"side-by-side","input":{"kind":"text","label":"Raw string","placeholder":"He said \"hello\".\nNext line."},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Escape"},"capabilities":{"copy":true},"workbenchMark":{"text":"J\\","tone":"contrast"},"labels":{"empty":"Paste the raw text you want to embed in JSON.","ready":"Escaped string is ready.","result":"Escaped text","running":"Escaping text for JSON…"},"content":{"howToUse":["Paste the raw text exactly as it is — including newlines, tabs, and quotes.","Escape. Quotes become `\\\"`, backslashes become `\\\\`, and newlines become `\\n`.","Copy the result and paste it between the quotes of a JSON string value. The surrounding quotes are not included, so you add them yourself."],"limitations":["The output is the escaped body only, without the wrapping double quotes.","Non-ASCII characters are left as literal UTF-8, not converted to `\\uXXXX` escapes. That is valid JSON, but some strict consumers prefer the escaped form.","This escapes for JSON only. It is not sufficient to make a string safe for HTML, SQL, or a shell."],"faq":[{"q":"Why are there no quotes around the result?","a":"So you can drop it straight into an existing string literal. Add `\"` on both sides if you need a complete JSON value."},{"q":"How do I reverse this?","a":"Use a JSON unescape tool, or wrap the text in quotes and run it through `JSON.parse`."},{"q":"Are emoji and accented characters handled?","a":"Yes — they pass through as UTF-8, which is valid inside a JSON string."}],"examples":[{"label":"Quotes and a newline","text":"He said \"hello\".\nNext line."},{"label":"Windows path","text":"C:\\Users\\ada\\notes.txt"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.json-escape' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"jsonExecution.repairMode":"Choose a valid JSON repair mode.","jsonExecution.invalid":"Input is not valid JSON. Check commas, quotes, and brackets.","jsonExecution.required":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is required.","jsonExecution.invalidInput":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is not valid JSON.","jsonExecution.inputSyntax":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is invalid near line {line, number}, column {column, number}.","jsonExecution.inputTooLarge":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} must be {limit, number} characters or fewer.","jsonExecution.empty":"Paste JSON or open a .json file to get started.","jsonExecution.tooLarge":"JSON must be {limit, number} characters or fewer.","jsonExecution.syntax":"JSON is invalid near line {line, number}, column {column, number}.","jsonExecution.encoding":"The file is not valid UTF-8 near line {line, number}, column {column, number}.","jsonExecution.recovery":"Check the reported line for a missing comma, quote, or bracket.","jsonExecution.processing":"Processing JSON","jsonExecution.status":"Status","jsonExecution.valid":"Valid JSON","jsonExecution.rootType":"Root type","jsonExecution.rootValue":"{type, select, array {Array} boolean {Boolean} null {Null} number {Number} object {Object} string {String} other {Unknown}}","jsonExecution.input":"Input","jsonExecution.output":"Output","jsonExecution.bytes":"{count, number} bytes","jsonExecution.completeFile":"Complete generated file","jsonExecution.download":"Download","json.exactNumbers":"Exact numbers preserved","json.exactNumbersDetail":"Shown as code because a tree view would change some numeric values. Copy and download keep the original numbers."},"toolId":"devtools.json-formatter","sharing":{"version":1},"app":"devtools","category":"json-tools","keywords":["json","format","beautify","pretty print","indent","minify","validate"],"name":"JSON Formatter","description":"Beautify and format JSON with a chosen indentation.","input":{"kind":"text","language":"json","label":"JSON input","acceptFiles":{"accept":".json,application/json,text/json","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"{\"name\":\"CodeUtilityKit\",\"version\":2}","maxLength":2000000},"settings":{"fields":{"operation":{"kind":"select","label":"Operation","help":"Format, minify, or only validate the JSON.","default":"format","choices":[{"label":"Format","value":"format"},{"label":"Minify","value":"minify"},{"label":"Validate","value":"validate"}]},"indentation":{"kind":"select","label":"Indentation","help":"Controls indentation in formatted output.","default":"2","visibleWhen":{"key":"operation","equals":"format"},"choices":[{"label":"2 spaces","value":"2"},{"label":"4 spaces","value":"4"},{"label":"Tab","value":"tab"}]}}},"trigger":{"mode":"live","debounceMs":120},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"J{}","tone":"contrast"},"labels":{"empty":"Paste JSON to format it.","ready":"Formatted JSON is ready.","running":"Formatting JSON…"},"content":{"howToUse":["Paste minified or badly indented JSON on the left. It reformats as you pause typing, so there is no button to hunt for.","Pick the indentation your project uses. Two spaces is the common default; tabs matter if a linter enforces them.","If the input will not parse, read the reported line and column — that is where the parser gave up, which is usually one character after the real mistake.","Copy or download the formatted JSON once it looks right."],"limitations":["Editable text is capped at 2,000,000 characters. JSON files up to 100 MiB are processed in read-only large-file mode.","Parsing is strict JSON. Comments, trailing commas, and single-quoted strings are rejected — use the JSON Viewer's repair pass to recover from those first.","Number lexemes are preserved exactly while formatting or minifying, including integers beyond 2^53 and high-precision decimals.","Formatting rewrites whitespace only. Key order is preserved as parsed, and no keys are sorted, added, or removed."],"faq":[{"q":"Is my JSON uploaded anywhere?","a":"No. Formatting runs entirely in this browser tab; the document never leaves your machine."},{"q":"Why does the reported error column look one character off?","a":"The parser reports where it could no longer continue, which is typically just past the actual problem — a missing comma or an unclosed bracket earlier on the line."},{"q":"Does formatting change my data?","a":"Only whitespace changes. Numbers are preserved exactly, including large integers and long decimals. When a tree preview would change a number, the result is shown as exact JSON code instead."},{"q":"Can I go the other way and minify?","a":"Yes — the workspace exposes a minify action alongside formatting, using the same parsed value."}],"examples":[{"label":"Minified object","text":"{\"name\":\"CodeUtilityKit\",\"version\":2,\"active\":true}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.json-formatter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","jsonExecution.repairMode":"Choose a valid JSON repair mode.","jsonExecution.invalid":"Input is not valid JSON. Check commas, quotes, and brackets.","jsonExecution.required":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is required.","jsonExecution.invalidInput":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is not valid JSON.","jsonExecution.inputSyntax":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is invalid near line {line, number}, column {column, number}.","jsonExecution.inputTooLarge":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} must be {limit, number} characters or fewer.","jsonExecution.empty":"Paste JSON or open a .json file to get started.","jsonExecution.tooLarge":"JSON must be {limit, number} characters or fewer.","jsonExecution.syntax":"JSON is invalid near line {line, number}, column {column, number}.","jsonExecution.encoding":"The file is not valid UTF-8 near line {line, number}, column {column, number}.","jsonExecution.recovery":"Check the reported line for a missing comma, quote, or bracket.","jsonExecution.processing":"Processing JSON","jsonExecution.status":"Status","jsonExecution.valid":"Valid JSON","jsonExecution.rootType":"Root type","jsonExecution.rootValue":"{type, select, array {Array} boolean {Boolean} null {Null} number {Number} object {Object} string {String} other {Unknown}}","jsonExecution.input":"Input","jsonExecution.output":"Output","jsonExecution.bytes":"{count, number} bytes","jsonExecution.completeFile":"Complete generated file","jsonExecution.download":"Download"},"toolId":"devtools.json-key-extractor","sharing":{"version":1},"app":"devtools","category":"json-tools","keywords":["json","keys","paths","extract","schema","flatten"],"name":"JSON Key Extractor","description":"List every object key path in JSON.","layout":"side-by-side","input":{"kind":"text","language":"json","label":"JSON input","placeholder":"{\"user\":{\"name\":\"Ada\",\"roles\":[\"admin\"]}}"},"settings":{"fields":{"repairMode":{"kind":"select","label":"Auto-fix broken JSON","help":"How to handle values the parser cannot recover: drop them, null them, or refuse the input outright.","default":"remove","choices":[{"label":"Remove broken parts","value":"remove"},{"label":"Set broken values to null","value":"null"},{"label":"Off (strict)","value":"off"}]}}},"trigger":{"mode":"manual","actionLabel":"Extract keys"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"J.K","tone":"contrast"},"labels":{"empty":"Paste JSON to list its key paths.","ready":"Key paths are ready.","running":"Extracting JSON key paths…"},"content":{"howToUse":["Paste a JSON document — an API response, a config file, or a sample record.","Extract. Every distinct object key path is listed once, in the order it was first encountered.","Array traversal is collapsed: an element path is written as parent[].child, so a thousand-item array still yields one line per field."],"limitations":["Only object keys are listed. Scalar values, array indices, and array lengths are not reported.","Paths are deduplicated across the whole document, so two array elements with different shapes produce the union of their keys with no indication of which element had which.","A key containing a dot or a bracket is emitted literally, which makes its path ambiguous to re-parse."],"faq":[{"q":"Why does the output use [] instead of an index?","a":"Because the point is the shape, not the data. Collapsing indices turns a large array into a single set of field paths you can scan."},{"q":"Can I use this to build a schema?","a":"It is a good starting point for one — it tells you every field name that exists — but it does not report types or optionality."}],"examples":[{"label":"Nested object with an array","text":"{\"user\":{\"name\":\"Ada\",\"roles\":[{\"name\":\"Admin\"}]}}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.json-key-extractor' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","jsonExecution.repairMode":"Choose a valid JSON repair mode.","jsonExecution.invalid":"Input is not valid JSON. Check commas, quotes, and brackets.","jsonExecution.required":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is required.","jsonExecution.invalidInput":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is not valid JSON.","jsonExecution.inputSyntax":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is invalid near line {line, number}, column {column, number}.","jsonExecution.inputTooLarge":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} must be {limit, number} characters or fewer.","jsonExecution.empty":"Paste JSON or open a .json file to get started.","jsonExecution.tooLarge":"JSON must be {limit, number} characters or fewer.","jsonExecution.syntax":"JSON is invalid near line {line, number}, column {column, number}.","jsonExecution.encoding":"The file is not valid UTF-8 near line {line, number}, column {column, number}.","jsonExecution.recovery":"Check the reported line for a missing comma, quote, or bracket.","jsonExecution.processing":"Processing JSON","jsonExecution.status":"Status","jsonExecution.valid":"Valid JSON","jsonExecution.rootType":"Root type","jsonExecution.rootValue":"{type, select, array {Array} boolean {Boolean} null {Null} number {Number} object {Object} string {String} other {Unknown}}","jsonExecution.input":"Input","jsonExecution.output":"Output","jsonExecution.bytes":"{count, number} bytes","jsonExecution.completeFile":"Complete generated file","jsonExecution.download":"Download"},"toolId":"devtools.json-minifier","sharing":{"version":1},"app":"devtools","category":"json-tools","keywords":["json","minify","compact","whitespace","compress","payload size"],"name":"JSON Minifier","description":"Remove insignificant whitespace from JSON.","outputLanguage":"json","input":{"kind":"text","language":"json","label":"JSON input","acceptFiles":{"accept":".json,application/json,text/json","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"{\n  \"name\": \"Ada\",\n  \"active\": true\n}"},"settings":{"fields":{"repairMode":{"kind":"select","label":"Auto-fix broken JSON","help":"How to handle properties whose value is missing or unparseable.","default":"remove","choices":[{"label":"Remove broken parts","value":"remove"},{"label":"Set broken values to null","value":"null"},{"label":"Off (strict)","value":"off"}]}}},"trigger":{"mode":"manual","actionLabel":"Minify"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"J-","tone":"contrast"},"labels":{"empty":"Paste JSON to strip its whitespace.","ready":"Minified JSON is ready.","running":"Minifying JSON…"},"content":{"howToUse":["Paste the formatted JSON you want to shrink. Everything runs in this browser tab; nothing is uploaded.","Leave auto-fix on 'Remove broken parts' to salvage a payload that was truncated mid-copy, or switch to 'Off (strict)' when you need the input rejected rather than repaired.","Run the tool and copy the single-line result into your config, fixture, or request body."],"limitations":["Minifying re-serialises through JSON.parse, so comments, trailing commas, and any other JSON5 syntax are lost rather than preserved.","Key order is preserved, but duplicate keys collapse to the last occurrence — that is JSON.parse behaviour, not a choice this tool makes.","Numbers are re-emitted in JavaScript's shortest round-trip form, so 1.50 becomes 1.5 and integers beyond 2^53 lose precision.","Editable text is capped at 2,000,000 characters. Strict JSON files up to 100 MiB can be minified in read-only large-file mode; repair remains available for editable input only."],"faq":[{"q":"How much smaller will my payload get?","a":"Only the whitespace is removed. Pretty-printed JSON typically shrinks 15–30%; already-compact JSON barely changes. Gzip on the wire matters far more."},{"q":"What does auto-fix actually repair?","a":"Properties whose value is missing or unparseable. 'Remove broken parts' drops them, 'Set broken values to null' keeps the key with a null value, and 'Off (strict)' fails on anything JSON.parse rejects."},{"q":"Is minified JSON still valid JSON?","a":"Yes. Whitespace between tokens is insignificant in JSON, so the minified form parses to exactly the same value."}],"examples":[{"label":"Pretty-printed object","text":"{\n  \"name\": \"Ada\",\n  \"active\": true\n}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.json-minifier' AND spec IS NULL;
