ols.json-validator","sharing":{"version":1},"app":"devtools","category":"json-tools","keywords":["json","validator","syntax","lint","parse","check"],"name":"JSON Validator","description":"Validate JSON syntax and report its root type.","layout":"side-by-side","input":{"kind":"text","language":"json","label":"JSON input","acceptFiles":{"accept":".json,application/json,text/json","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"{\"valid\":true}"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Validate"},"capabilities":{"copy":true},"workbenchMark":{"text":"JOK","tone":"contrast"},"labels":{"empty":"Provide JSON to validate its syntax.","ready":"JSON is valid.","running":"Validating JSON…"},"content":{"howToUse":["Paste the JSON you want to check. Nothing is uploaded — parsing happens in this browser tab.","Run the validator. Valid input reports the root type (object, array, string, number, boolean, or null).","Invalid input reports the parser's own message, which names the character position where parsing stopped.","Fix the first reported error and re-run: a single stray comma usually cascades into several later complaints."],"limitations":["This is a strict JSON.parse check. Comments, trailing commas, single quotes, and NaN/Infinity are all rejected — use the JSON formatter's repair mode if you need those tolerated.","Only syntax is checked. Validating a document against a JSON Schema is a separate tool.","Duplicate object keys are not reported; JSON.parse silently keeps the last one."],"faq":[{"q":"Why is my JSON rejected when my editor accepts it?","a":"Editors often accept JSON5 or JSONC. Strict JSON has no comments, no trailing commas, and requires double-quoted keys."},{"q":"What does 'root type' mean?","a":"The type of the outermost value. A JSON document does not have to be an object — a bare string or number is valid JSON too."}],"examples":[{"label":"Minimal object","text":"{\"valid\":true}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.json-validator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.json-viewer","app":"devtools","category":"json-tools","keywords":["json","viewer","tree","explore","inspect","repair","pretty print"],"name":"JSON Viewer","description":"Explore nested JSON in a searchable tree without uploading your data.","layout":"side-by-side","input":{"kind":"text","language":"json","label":"JSON input","acceptFiles":{"accept":".json,application/json,text/json","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"{\"name\":\"CodeUtilityKit\",\"version\":2}","maxLength":2000000},"settings":{"fields":{"largeFileOperation":{"kind":"select","label":"Large-file action","help":"Used by the large-file controls in the viewer workspace.","default":"validate","choices":[{"label":"Validate","value":"validate"},{"label":"Beautify","value":"format"},{"label":"Minify","value":"minify"}]},"repairMode":{"kind":"select","label":"Repair strategy","help":"Used only when Repair & clean is requested.","default":"remove","choices":[{"label":"Remove broken properties","value":"remove"},{"label":"Set broken values to null","value":"null"}]}}},"trigger":{"mode":"live","debounceMs":120},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"JV","tone":"contrast"},"labels":{"empty":"Paste JSON or load an example to begin.","ready":"Interactive tree ready · split view.","running":"Parsing JSON…"},"messages":{"jsonExecution.repairMode":"Choose a valid JSON repair mode.","jsonExecution.invalid":"Input is not valid JSON. Check commas, quotes, and brackets.","jsonExecution.required":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is required.","jsonExecution.invalidInput":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is not valid JSON.","jsonExecution.inputSyntax":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} is invalid near line {line, number}, column {column, number}.","jsonExecution.inputTooLarge":"{input, select, left {JSON A} right {JSON B} data {JSON data} schema {JSON schema} other {JSON input}} must be {limit, number} characters or fewer.","jsonExecution.empty":"Paste JSON or open a .json file to get started.","jsonExecution.tooLarge":"JSON must be {limit, number} characters or fewer.","jsonExecution.syntax":"JSON is invalid near line {line, number}, column {column, number}.","jsonExecution.encoding":"The file is not valid UTF-8 near line {line, number}, column {column, number}.","jsonExecution.recovery":"Check the reported line for a missing comma, quote, or bracket.","jsonExecution.processing":"Processing JSON","jsonExecution.status":"Status","jsonExecution.valid":"Valid JSON","jsonExecution.rootType":"Root type","jsonExecution.rootValue":"{type, select, array {Array} boolean {Boolean} null {Null} number {Number} object {Object} string {String} other {Unknown}}","jsonExecution.input":"Input","jsonExecution.output":"Output","jsonExecution.bytes":"{count, number} bytes","jsonExecution.completeFile":"Complete generated file","jsonExecution.download":"Download","execution.recovery.json":"Fix the reported line, or run Repair & clean to drop the broken parts.","errors.json-empty":"Paste JSON to inspect it.","errors.json-too-large":"JSON must be {limit, number} characters or fewer. Upload a file to use large-file mode.","errors.json-syntax":"JSON is invalid near line {line, number}, column {column, number}. Check for a missing comma, quote, or bracket.","errors.json-encoding":"The file is not valid UTF-8 near line {line, number}, column {column, number}. Save it as UTF-8 and upload it again.","dismiss":"Dismiss","goToErrorLabel":"Go to JSON error at line {line, number}, column {column, number}","goToError":"Go to line {line, number}, column {column, number}","copyPreviewLabel":"Copy JSON preview","copyInputLabel":"Copy JSON input","previewCopied":"JSON preview copied.","inputCopied":"JSON input copied.","copyInputFailed":"Copy failed. Select the input and copy it manually.","copyPreview":"Copy preview","copy":"Copy","largeFileMode":"Large-file mode","treeUnavailable":"JSON tree unavailable","parsing":"Parsing JSON…","treePlaceholder":"Interactive tree will appear here","treeDescription":"Paste JSON to inspect its structure.","copyValueFailed":"Copy failed. Select the value and copy it manually.","undo":"Undo","undone":"Last change undone.","precisionEditBlocked":"Edit blocked because it could change a high-precision number. Edit the source directly.","inputCleared":"Input cleared.","precisionRepairBlocked":"Repair blocked because it could change a high-precision number.","repairCancelled":"Repair cancelled. Input was not changed.","alreadyValid":"JSON was already valid; formatting was applied.","brokenExampleLoaded":"Broken example loaded. Choose a repair strategy, then run Repair & clean.","example":"Example","sampleLoaded":"Sample loaded.","precisionWarning":"High-precision number: previews may round it; copy and download preserve the exact source. Transform actions are blocked.","processingCompleteFile":"Processing the complete JSON file","readyToProcess":"Ready to process","processingDescription":"The file stays local while the worker reads it incrementally.","largeFileDescription":"Validate every byte, or generate a formatted or minified download without loading the full file into the editor.","inputTitle":"JSON input","beautifyLabel":"Beautify JSON code","minifyLabel":"Minify JSON code","brokenExample":"Broken example","repairStrategy":"Repair strategy","previewMeta":"Read-only · bounded preview","largeResultTitle":"Large JSON result","upload":"Upload","validate":"Validate","beautify":"Beautify","minify":"Minify","repair":"Repair & clean","repairHeading":"REPAIR","removeBroken":"Remove broken","setNull":"Set to null","clear":"Clear","errorBeyondPreview":"Error is beyond the loaded preview","validationFailed":"JSON validation failed","errorBeyondPreviewDescription":"The reported location is beyond the loaded preview.","fileUnreadable":"{name} could not be read.","inputBytes":"{count, plural, one {# byte} other {# bytes}}","valueCopied":"{label} copied.","repairConfirmation":"Repair will remove {count, plural, one {# broken path} other {# broken paths}} ({paths}). Continue?","repairCompleted":"JSON repaired with the “{strategy, select, null {Set broken values to null} other {Remove broken properties}}” strategy.","precisionTransformBlocked":"{mode, select, minify {Minify} other {Beautify}} blocked because it could change a high-precision number.","repairEmpty":"Paste JSON to repair it.","repairTooLarge":"JSON must be {limit, number} characters or fewer.","repairFailed":"JSON could not be repaired safely."},"content":{"howToUse":["Paste JSON on the left. It parses as you type, so a syntax error is reported with the line and column while you are still looking at it.","Explore the tree on the right — expand and collapse branches to find the shape of a payload without scrolling through a wall of text.","If the input will not parse, choose a repair strategy and run Repair & clean. Removing broken properties drops them; setting them to null keeps the key so the surrounding structure survives.","Copy or download the cleaned JSON once the tree looks right."],"limitations":["Editable text is capped at 2,000,000 characters. JSON files up to 100 MiB open in read-only large-file mode for complete validation, beautifying, or minifying with a bounded preview and downloadable output.","Parsing is strict JSON. Comments, trailing commas, and single-quoted strings are errors, though the repair pass can often recover from them.","The tree preview uses JavaScript numbers, so integers beyond 2^53 and high-precision decimals may look rounded. Transform actions are blocked for those values; whole-document copy and download preserve the exact source.","Repair is a best-effort structural fix, not a schema validator. Always compare the repaired output against the original before using it."],"faq":[{"q":"Is my JSON uploaded anywhere?","a":"No. Parsing, repair, and the tree all run in this browser tab. Nothing is sent to a server."},{"q":"Which repair strategy should I pick?","a":"Remove when a broken property is noise you can drop. Null when downstream code expects the key to exist and can handle a null."},{"q":"Why does the tree round my large number?","a":"The tree uses IEEE-754 doubles, but whole-document copy and download keep the exact source. Format, minify, and repair stay blocked when they could change the number."},{"q":"Does the tree preserve key order?","a":"Yes for ordinary string keys. Keys that look like array indices are reordered first, which is a JavaScript object rule rather than a choice made here."}],"examples":[{"label":"Nested object","text":"{\n  \"name\": \"CodeUtilityKit\",\n  \"version\": 2,\n  \"active\": true,\n  \"tags\": [\"json\", \"viewer\", \"free\"],\n  \"author\": {\n    \"name\": \"Dev\",\n    \"url\": \"https://codeutilitykit.com\"\n  }\n}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.json-viewer' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedJwt.parts":"JWT must contain three dot-separated parts.","sharedJwt.payload":"JWT header or payload is not valid Base64URL JSON.","claims.header":"header","claims.payload":"payload","claims.decoded":"Decoded {section}","claims.view":"{section} view","claims.copy":"Copy {section} JSON","claims.timestamp":"{timestamp} (UTC)","details.header_claims.alg":"Signing algorithm","details.header_claims.typ":"Token type","details.header_claims.cty":"Content type","details.header_claims.kid":"Key ID","details.header_claims.jku":"Key set URL","details.header_claims.jwk":"Public key","details.header_claims.x5u":"Certificate URL","details.header_claims.x5c":"Certificate chain","details.header_claims.x5t":"Certificate thumbprint","details.header_claims.x5t#S256":"SHA-256 certificate thumbprint","details.header_claims.crit":"Critical header parameters","details.payload_claims.iss":"Issuer","details.payload_claims.sub":"Subject","details.payload_claims.aud":"Audience","details.payload_claims.exp":"Expiration time","details.payload_claims.nbf":"Not valid before","details.payload_claims.iat":"Issued at","details.payload_claims.jti":"Token ID","workspace.json_db1a21":"JSON","workspace.claims_1c85c1":"Claims","workspace.custom_claim_4407f1":"Custom claim","workspace.no_claims_96fbdb":"No claims.","workspace.decoded_only_signature_0cb155":"Decoded only · Signature not verified","workspace.signature_f1a73e":"Signature","workspace.copy_signature_cac3d2":"Copy signature","workspace.unsigned_token_alg_17bafd":"Unsigned token (alg: none).","workspace.no_signature_provided_b37ec5":"No signature provided."},"toolId":"devtools.jwt-decoder","app":"devtools","category":"encoding-decoding","keywords":["jwt","json web token","decode","claims","header","payload","bearer"],"name":"JWT Decoder","description":"Decode JWT header and payload without verifying the signature.","outputLanguage":"json","resultView":{"default":"preview"},"input":{"kind":"text","label":"JWT token","language":"jwt","showLineNumbers":false,"placeholder":"eyJhbGciOiJub25lIn0.eyJzdWIiOiIxMjMifQ."},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Decode JWT"},"capabilities":{"copy":true},"workbenchMark":{"text":"JWT","tone":"contrast"},"labels":{"empty":"Provide a JWT to decode its header and claims.","ready":"Decoded JWT details are ready.","running":"Decoding JWT…"},"content":{"howToUse":["Paste the full token — all three dot-separated parts. The trailing dot of an unsigned token is required too.","Decode. You get the header, the payload, the raw signature segment, and a `timestamps` block that converts the numeric `iat`, `nbf`, and `exp` claims to ISO instants.","Read `alg` in the header first. `none` means the token is unsigned and carries no authenticity guarantee at all.","Decoding happens entirely in this browser tab — the token is never sent to a server. Even so, treat any token you paste as compromised and rotate it if it was a live credential."],"limitations":["The signature is decoded but never verified. This tool cannot tell you whether a token is authentic, only what it claims.","Expiry is shown as a converted timestamp, not evaluated. An expired token decodes exactly like a valid one.","Only compact-serialization JWS tokens are supported. Encrypted tokens (JWE, five parts) are rejected.","The header and payload must both be Base64URL-encoded JSON objects; a token carrying a non-object payload is rejected."],"faq":[{"q":"Does this verify the token?","a":"No. Verification needs the issuer's key and must happen server-side. Use this to read claims while debugging, never to make a trust decision."},{"q":"Is my token uploaded?","a":"No. Base64 decoding runs locally in this tab. The token is not logged or stored."},{"q":"Why is the signature field empty?","a":"The token is unsigned — `alg` is `none` — so the third segment after the final dot is empty."},{"q":"What is the `timestamps` block?","a":"A convenience view: any of `iat`, `nbf`, and `exp` that is a number is shown as an ISO 8601 instant so you do not have to convert epoch seconds by hand."}],"examples":[{"label":"Unsigned token","text":"eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0.eyJzdWIiOiIxMjMiLCJleHAiOjQxMDI0NDQ4MDB9."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.jwt-decoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","sharedJwt.parts":"JWT must contain three dot-separated parts.","sharedJwt.payload":"JWT header or payload is not valid Base64URL JSON.","execution.errors.numericDate":"JWT {claim} must be a finite NumericDate in seconds within the supported date range.","execution.recovery.numericDate":"Check the {claim} claim in the token input. Use a JSON number of seconds since 1970-01-01 UTC, not a date string.","summary.region":"JWT expiration summary","summary.notSpecified":"Not specified","summary.noRestriction":"No restriction specified","summary.localTime":"Local time · {timezone}","summary.checked":"Checked {time} using your device clock, with no clock-skew allowance. Run Check expiration again to refresh.","details.status.active.label":"Not expired","details.status.active.title":"Within its time window","details.status.active.description":"At the last check, the expiration time was in the future and any not-before restriction had passed.","details.status.expired.label":"Expired","details.status.expired.title":"Token has expired","details.status.expired.description":"The expiration time has passed. Obtain a new token through your application''s sign-in or refresh flow.","details.status.not-active.label":"Not active yet","details.status.not-active.title":"Not active yet","details.status.not-active.description":"The not-before time is still in the future. The token must not be accepted before that time.","details.status.expiring-soon.label":"Expiring soon","details.status.expiring-soon.title":"Expiration is near","details.status.expiring-soon.description":"At the last check, this token had five minutes or less remaining. Use your application''s refresh flow if needed.","details.status.no-expiration.label":"No exp claim","details.status.no-expiration.title":"No expiration specified","details.status.no-expiration.description":"This payload has no exp claim, so its expiration cannot be determined. This does not mean the token will remain accepted indefinitely.","workspace.expires_at_b613b9":"Expires at","workspace.not_valid_before_03d76d":"Not valid before","workspace.issued_at_f91a82":"Issued at","workspace.expiration_status_4108ab":"Expiration status","workspace.token_timestamps_1a99b0":"Token timestamps","workspace.utc_7e5f76":"UTC","workspace.signature_not_verified_9d24d5":"Signature not verified. Time claims alone do not establish that a token is valid or trusted.","workspace.decoded_payload_76534c":"Decoded payload","workspace.unverified_claims_749f74":"Unverified claims","workspace.copy_payload_json_d88b52":"Copy payload JSON"},"toolId":"devtools.jwt-expiration-checker","app":"devtools","category":"jwt-api-tools","keywords":["jwt","expiration","exp","nbf","iat","token","claims"],"name":"JWT Expiration Checker","description":"Inspect issued-at, not-before, and expiration claims.","resultView":{"default":"preview","previewLabel":"Summary"},"layout":"stacked","input":{"kind":"fields","label":"JWT token","fields":[{"channel":"text","label":"JWT token","placeholder":"eyJhbGciOiJub25lIn0.eyJleHAiOjQxMDI0NDQ4MDB9.","required":true,"secret":true,"multiline":true}]},"settings":{"fields":{"useLocalTime":{"kind":"toggle","label":"Use local time","help":"Show timestamps in your device's local time.","default":false},"decodePayload":{"kind":"toggle","label":"Decode payload","help":"Include the decoded, unverified claims payload.","default":false},"warnBeforeExpiry":{"kind":"toggle","label":"Warn before expiry","help":"Mark active tokens that expire within five minutes.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Check expiration"},"capabilities":{"copy":true},"workbenchMark":{"text":"JEX","tone":"contrast"},"labels":{"empty":"Paste a JWT to inspect its expiration and time claims.","ready":"JWT expiration check is ready.","running":"Checking JWT expiration…"},"content":{"howToUse":["Paste the whole token, all three dot-separated parts. It is masked because a JWT is a bearer credential — anyone holding it can act as you until it expires.","Choose Check expiration. The summary explains the time-based status and shows expiration, not-before, and issued-at dates. Raw keeps the original report ready to copy.","The verdict is computed against your device clock. A machine with a skewed clock will disagree with the server that issued the token."],"limitations":["The signature is not verified. This tool answers \"is it still within its validity window\", never \"is it genuine\" — a token with a forged payload reads the same as a real one.","Only exp, nbf, and iat are inspected. Scopes, audience, and issuer are ignored.","Time claims must be NumericDate numbers: seconds since the Unix epoch. Invalid types and dates outside the supported range are reported as errors.","Nothing is uploaded, but the token still lands in this tab's memory — do not paste a production token on a shared machine."],"faq":[{"q":"Does this verify the signature?","a":"No. Decoding is not verification. Always verify server-side with the issuer's key before trusting any claim."},{"q":"Why does it say Active when the server rejects the token?","a":"The validity window is only one reason a token is rejected. Signature, audience, issuer, scope, and revocation are all checked server-side and none of them are visible here."},{"q":"Does my token leave the browser?","a":"No. Decoding is local and the token is never uploaded or logged."}],"examples":[{"label":"Token expiring in 2100","text":"eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0.eyJzdWIiOiIxMjMiLCJleHAiOjQxMDI0NDQ4MDB9."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.jwt-expiration-checker' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"codeRun.source.required":"Write some code to run.","codeRun.source.encoding":"Source code is not valid UTF-8 text.","codeRun.source.nul":"Source code contains a NUL character.","codeRun.source.too-large":"Source code is larger than {max}.","codeRun.stdin.encoding":"Input is not valid UTF-8 text.","codeRun.stdin.nul":"Input contains a NUL character.","codeRun.stdin.too-large":"Input is larger than {max}.","codeRun.ok":"Your program ran successfully in {duration} and printed {lines, plural, =0 {nothing} one {# line} other {# lines}}.","codeRun.okDetail":"It exited with code 0.","codeRun.compileError":"Compilation failed.","codeRun.compileErrorAt":"Compilation failed at line {line}: {message}","codeRun.compileErrorDetail":"Fix the error in the compiler output below, then run again.","codeRun.runtimeError":"Your program stopped with an error (exit code {code}).","codeRun.runtimeErrorDetail":"Check the error output below for the cause.","codeRun.killed":"Your program was stopped by the signal {signal}.","codeRun.killedDetail":"{signal, select, SIGKILL {SIGKILL usually means the memory or process limit was reached.} SIGSEGV {SIGSEGV means the program touched memory it does not own, for example an invalid pointer or unbounded recursion.} SIGABRT {SIGABRT means the program aborted itself, often after a failed assertion or an unhandled error.} SIGFPE {SIGFPE means an illegal arithmetic operation, such as dividing an integer by zero.} SIGXCPU {SIGXCPU means the CPU time limit was reached.} SIGXFSZ {SIGXFSZ means the program tried to write a file larger than allowed.} other {The operating system ended the program with this signal.}}","codeRun.timeLimitRun":"Stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitCompile":"Compilation was stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitDetail":"Look for an endless loop or work that can be made smaller, then run again.","codeRun.outputLimit":"Your program printed more than the allowed amount of {stream, select, stderr {error output} other {output}}.","codeRun.outputLimitDetail":"The output below is cut off. Print less, then run again.","codeRun.unavailable":"Code execution is not available right now.","codeRun.unavailableDetail":"{reason, select, notConfigured {Running code is switched off on this server.} runtimeMissing {This language version is not installed on the execution server.} other {The execution server did not respond.}} Your code is kept. Try again in a minute.","codeRun.busy":"The execution server is busy.","codeRun.busyDetail":"Your code is kept. Try again in {seconds} seconds.","codeRun.fact.time":"Run time","codeRun.fact.cpu":"CPU time","codeRun.fact.memory":"Memory","codeRun.fact.exit":"Exit code","codeRun.fact.signal":"Signal","codeRun.fact.language":"Language","codeRun.section.stdout":"Standard output","codeRun.section.stderr":"Error output","codeRun.section.compiler":"Compiler output","codeRunner.editor":"{language} source code","codeRunner.stdin":"Standard input (stdin)","codeRunner.stdinHelp":"Type anything your program reads before you press Run. Input cannot be typed while the program is running.","codeRunner.stdinPlaceholder":"Optional. For example: Ada","codeRunner.run":"Run","codeRunner.cancel":"Cancel","codeRunner.runTooltip":"Run your program ({shortcut})","codeRunner.cancelTooltip":"Stop this run. Your code stays as it is.","codeRunner.running":"Running your program…","codeRunner.cancelled":"Run cancelled. Your code is unchanged.","codeRunner.reset":"Reset to starter","codeRunner.resetTitle":"Reset to the starter program?","codeRunner.resetBody":"Your current code is replaced by the starter program and your saved draft is removed.","codeRunner.resetConfirm":"Reset","codeRunner.resetKeep":"Keep my code","codeRunner.upload":"Upload file","codeRunner.uploadFailed":"{name} could not be read as text.","codeRunner.uploadTooLarge":"{name} is larger than {max} KiB. Choose a smaller file.","codeRunner.download":"Download source","codeRunner.version":"{language} version","codeRunner.versionTooltip":"Choose which version runs your code. Each run uses exactly that version.","codeRunner.draftNote":"Your code is saved in this browser only, until you run it.","codeRunner.resultPlaceholder":"Press Run to see what your program prints, or why it stopped."},"toolId":"devtools.kotlin-compiler","slug":"kotlin-compiler","app":"devtools","category":"compilers","keywords":["kotlin","kotlin compiler","online kotlin","run kotlin","kotlinc","kotlin playground"],"name":"Kotlin Compiler","description":"Write and run Kotlin 2.4 code in your browser. Add input, press Run, and read the output or the exact error. Nothing to install.","input":{"kind":"text","label":"Kotlin code","showLineNumbers":true,"maxLength":65536,"acceptFiles":{"accept":".kt,text/plain","maxBytes":65536},"secondary":{"label":"Standard input (stdin)","placeholder":"Optional. For example: Ada"}},"settings":{"fields":{"version":{"kind":"select","label":"Version","help":"Each run uses exactly this version.","default":"2.4","choices":[{"value":"2.4","label":"Kotlin 2.4"}]}}},"resultStats":"status-only","trigger":{"mode":"manual","actionLabel":"Run"},"capabilities":{"cancel":true,"copy":true,"download":true,"network":true},"workbenchMark":{"text":"KT","tone":"contrast"},"labels":{"result":"Result","empty":"Press Run to see what your program prints, or why it stopped.","ready":"Your program finished. The result explains what happened.","running":"Running your program…"},"content":{"seoTitle":"Online Kotlin Compiler — Run Kotlin 2.4 Code","howToUse":["The editor starts with a small Kotlin program that reads a name from standard input and greets it, so you can press Run straight away.","Write or paste your Kotlin code. Anything your program reads from the keyboard goes in the Standard input box before you run it.","Press Run or Ctrl/Cmd+Enter. The result starts with one sentence saying what happened, followed by the output, error output and exit code.","If something goes wrong the message names the cause, including the line of a compile error. Fix your code and run again. Your code is kept in this browser while you work."],"limitations":["This page runs Kotlin 2.4.21 exactly, so results stay the same until the page is updated.","Each run is stopped after 5 seconds of running time (3 seconds of CPU time); compiling may take up to 15 seconds, and is limited to 256 MiB of memory and 64 KiB of output.","Source code and input are each limited to 64 KiB. Command-line arguments are not supported.","There is no network access, no way to install packages and no files that last between runs.","Input cannot be typed while the program runs. Put everything it will read in the Standard input box first.","If many people run code at once, the server may ask you to wait a few seconds. Your code is kept when that happens."],"faq":[{"q":"Is my code sent to a server, and is it saved?","a":"Yes, your code and input are sent to Canopy's execution server so it can run the program. It runs once in an isolated sandbox and is not stored. A draft stays in your own browser so a refresh does not lose your work."},{"q":"Which Kotlin version does this use?","a":"Kotlin 2.4.21. The version is pinned, so results stay the same until the page is updated."},{"q":"Why is Kotlin slower to start than other languages?","a":"Kotlin is compiled on every run and starts the Java virtual machine, so the first seconds are spent preparing. Short programs still finish well inside the limit."},{"q":"Why was my program stopped?","a":"Programs that run longer than the time limit, use too much memory or print too much are stopped to keep the service fair. The result tells you which limit was reached."}],"examples":[{"label":"Hello with input","text":"fun main() {\n    val name = (readLine() ?: \"\").trim()\n    println(\"Hello, ${if (name.isEmpty()) \"world\" else name}!\")\n}\n","secondary":"Ada"}],"relatedToolIds":["devtools.bash-compiler","devtools.python-compiler","devtools.javascript-compiler"]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.kotlin-compiler' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.lorem-ipsum-generator","app":"devtools","category":"text-tools","keywords":["lorem ipsum","placeholder","dummy text","filler","mockup","paragraphs"],"name":"Lorem Ipsum Generator","description":"Generate placeholder paragraphs.","input":{"kind":"none"},"settings":{"fields":{"paragraphs":{"kind":"number","label":"Paragraphs","default":3,"min":1,"max":50,"pane":"main","span":"full"},"startWithLorem":{"kind":"toggle","label":"Start with \"Lorem ipsum\"","help":"Keep the classic opening at the start of the first paragraph.","default":true},"paragraphLength":{"kind":"select","label":"Paragraph length","help":"Choose a preset length, or Custom for your own sentence count.","default":"medium","choices":[{"label":"Short","value":"short"},{"label":"Medium","value":"medium"},{"label":"Long","value":"long"},{"label":"Custom","value":"custom"}]},"customSentences":{"kind":"number","label":"Sentences per paragraph","help":"Choose between 1 and 100 whole sentences per paragraph.","default":3,"min":1,"max":100,"step":1,"visibleWhen":{"key":"paragraphLength","equals":"custom"}},"includePunctuation":{"kind":"toggle","label":"Include punctuation","help":"Keep sentence punctuation in the generated text.","default":true}}},"trigger":{"mode":"manual","actionLabel":"Generate"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"LORE","tone":"accent"},"labels":{"empty":"Choose the number of paragraphs to generate.","ready":"Placeholder text is ready.","running":"Generating…"},"content":{"howToUse":["Pick how many paragraphs of filler you need, between 1 and 50.","Choose Short (2 sentences), Medium (3), Long (4), or Custom (1–100 sentences per paragraph).","Generate, then copy the text into your mockup, template, or CMS draft."],"limitations":["Custom length counts sentences, not words or characters. Each paragraph can contain up to 100 sentences.","The sentence pool is small and cycles, so long runs repeat. That is fine for layout, less so for testing text-diff or search behaviour.","The output is deterministic — the same settings always produce the same text."],"faq":[{"q":"Why does the classic \"Lorem ipsum dolor sit amet\" opening not appear in every paragraph?","a":"Paragraphs are offset through the sentence pool so the block reads as varied text rather than the same stanza repeated."},{"q":"Should I ship this to production?","a":"No. Placeholder Latin that survives to production is a classic launch bug — search for \"lorem\" before you release."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.lorem-ipsum-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","export.copyFailed":"Could not copy the HTML. Try again.","export.downloadFailed":"Could not download the HTML. Try again.","workspace.html_copied_f641d9":"HTML copied.","workspace.preparing_5d1fa3":"Preparing…","workspace.copy_e21f93":"Copy","workspace.download_d6eafe":"Download"},"toolId":"devtools.markdown-previewer","app":"devtools","category":"web-markup-tools","keywords":["markdown","preview","md","html","readme","render","commonmark"],"name":"Markdown Previewer","description":"Render Markdown for a sandboxed preview.","layout":"side-by-side","input":{"kind":"text","language":"markdown","label":"Markdown document","acceptFiles":{"accept":".md,.markdown,.txt,text/markdown,text/plain","maxBytes":2000000,"maxEditableBytes":2000000},"placeholder":"# Preview\n\n- Fast\n- Private"},"settings":{"fields":{"syncScroll":{"kind":"toggle","label":"Sync scroll","help":"Keep the editor and preview at the same relative position when scrolling either pane.","default":true},"previewMode":{"kind":"select","label":"Preview mode","help":"Switches between GitHub extensions and standard CommonMark parsing.","default":"gfm","choices":[{"label":"GitHub flavored","value":"gfm"},{"label":"CommonMark","value":"commonmark"}]},"syntaxHighlighting":{"kind":"toggle","label":"Syntax highlighting","help":"Colors nearby code using its language label or automatic detection. Very large blocks remain plain text to keep the preview responsive.","default":true},"safeLinks":{"kind":"toggle","label":"Safe links","help":"Adds new-tab and opener protection to exported HTML links. Website links in the preview always open in a separate tab.","default":false}}},"trigger":{"mode":"live","debounceMs":160},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"MDV","tone":"accent"},"labels":{"result":"Preview","empty":"Write Markdown or load an example to preview it.","ready":"Rendered preview is current.","running":"Rendering Markdown…"},"content":{"howToUse":["Paste or type Markdown on the left. The preview re-renders as you stop typing — there is no button to press.","Use it to check a README, a changelog entry, or a comment before you commit it, especially the parts that are easy to get wrong: nested lists, tables, and fenced code blocks.","Copy the generated HTML if you need to paste the rendered form into a CMS or an email template.","The preview uses the same body viewer as the SmartTools blog. Other sites may style the exported HTML differently."],"limitations":["GitHub-flavoured Markdown is the default; CommonMark mode disables extensions such as tables and strikethrough.","The preview blocks scripts and form submissions. Remote images load from their hosting sites and make network requests.","Use absolute image URLs. Relative links and image paths depend on where the document is published.","Syntax highlighting supports common languages. Add a language after the opening code fence for reliable colors, or use text to keep a block unhighlighted.","Large documents render sections and code colors as you scroll. Copy and download always include the complete document; very large code blocks keep their text without syntax colors."],"faq":[{"q":"Is my document uploaded anywhere?","a":"The Markdown is rendered locally and is not uploaded. Images referenced in the document are requested from their hosting sites."},{"q":"Is raw HTML inside my Markdown rendered?","a":"It is rendered as markup inside a sandbox that blocks scripts and form submissions. Remote images can load from their hosting sites."},{"q":"Why do my tables not look right?","a":"GitHub-flavoured tables need a header row and a separator row of dashes, and every row needs the same number of pipe-separated cells."},{"q":"Can I export the HTML?","a":"Yes. The rendered HTML is what the copy and download actions produce."}],"examples":[{"label":"Headings and a list","text":"# Preview\n\n- Fast\n- Private"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.markdown-previewer' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again."},"toolId":"devtools.markdown-to-html","app":"devtools","category":"web-markup-tools","keywords":["markdown","html","convert","md","render","commonmark","gfm"],"name":"Markdown to HTML","description":"Convert Markdown source to HTML.","layout":"side-by-side","resultView":{"default":"preview","previewLabel":"Preview"},"input":{"kind":"text","language":"markdown","label":"Markdown input","placeholder":"# Hello\n\n**Smart tools** stay focused."},"settings":{"fields":{"markdownFlavor":{"kind":"select","label":"Markdown flavor","help":"Use GitHub extensions or parse standard CommonMark.","default":"gfm","choices":[{"label":"GFM","value":"gfm"},{"label":"CommonMark","value":"commonmark"}]},"sanitizeHtml":{"kind":"toggle","label":"Sanitize HTML","help":"Remove raw HTML and unsafe link targets from the generated output.","default":false},"openLinksSafely":{"kind":"toggle","label":"Open links safely","help":"Open generated links in a new tab without opener access.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Convert to HTML"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"M>H","tone":"contrast"},"labels":{"empty":"Provide Markdown to convert to HTML.","ready":"Converted HTML is ready.","running":"Converting Markdown to HTML…"},"content":{"howToUse":["Paste your Markdown — a README, release notes, or a docs page.","Convert. Headings, emphasis, lists, links, tables, and fenced code blocks are all supported.","Copy the HTML fragment into your template. No wrapper document, stylesheet, or script is added."],"limitations":["The output is a fragment, not a full page — there is no doctype, head, or styling.","Sanitizing is off by default, so raw HTML passes through unchanged unless you enable Sanitize HTML.","Front matter is not stripped; a YAML block at the top is rendered as content.","Extensions such as footnotes, definition lists, and math are not enabled."],"faq":[{"q":"Is the HTML safe to render?","a":"Only with Sanitize HTML enabled. By default, raw HTML and unsafe link targets survive the conversion."},{"q":"Which flavour of Markdown is this?","a":"CommonMark with GitHub-flavoured extensions such as tables and strikethrough."}],"examples":[{"label":"Heading and bold text","text":"# Hello\n\n**Smart tools** stay focused."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.markdown-to-html' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.md5-generator","sharing":{"version":1},"app":"devtools","category":"hashing-crypto","keywords":["md5","hash","checksum","digest","legacy","fingerprint","etag"],"name":"MD5 Generator","description":"Generate a legacy MD5 digest for compatibility checks.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"hello world"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Generate MD5"},"capabilities":{"copy":true},"workbenchMark":{"text":"MD5","tone":"contrast"},"labels":{"empty":"Enter the text you want to hash with MD5.","ready":"MD5 digest is ready.","running":"Generating MD5 digest…"},"content":{"howToUse":["Paste the exact bytes you need a digest for. A trailing newline changes the result, so copy the value verbatim.","Generate, then compare the 32-character lowercase hex digest with the one you were given.","Use this for what MD5 is still good for: matching a checksum published by a legacy system, an ETag, or a cache key.","For anything where an attacker could choose the input — passwords, signatures, integrity of downloaded files — use SHA-256 or HMAC instead."],"limitations":["MD5 is cryptographically broken. Collisions can be produced on a laptop, so a matching digest does not prove two inputs are the same when an attacker controls either one.","It is a plain digest, not a password hash. Never store passwords with it — use bcrypt, scrypt, or Argon2.","Input is treated as UTF-8 text. Binary payloads and files cannot be hashed here.","Output is always lowercase hex; there is no Base64 or uppercase option."],"faq":[{"q":"Is MD5 safe to use?","a":"Not as a security primitive. It remains fine as a non-adversarial checksum — verifying an accidental corruption, matching a legacy fingerprint, or building a cache key."},{"q":"What should I use instead?","a":"SHA-256 for a general digest, HMAC-SHA256 when a shared secret is involved, and bcrypt or Argon2 for passwords."},{"q":"Why does my digest not match?","a":"Almost always a byte difference in the input — a trailing newline, CRLF versus LF line endings, or a different text encoding."}],"examples":[{"label":"Classic test vector","text":"abc"},{"label":"Short phrase","text":"hello world"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.md5-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.copyingPdfPages":"Copying PDF pages","progress.copyingPdfPage":"Copying PDF page","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.invalidOrder":"The selected PDF order is invalid."},"toolId":"media.merge-pdf","app":"media","category":"pdf-organization","keywords":["pdf","merge","combine","join","append","order","documents"],"name":"Merge PDF","description":"Merge PDF files in the order you choose.","input":{"kind":"files","label":"PDF documents","accept":"application/pdf","multiple":true,"engine":"pdf","maxFiles":20,"maxBytes":52428800,"maxTotalBytes":52428800},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Merge PDFs"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"P+P","tone":"accent"},"labels":{"empty":"Add PDFs in the order they should be merged.","ready":"PDF order is ready.","running":"Merging PDFs…"},"content":{"howToUse":["Add every PDF you want in the merged document. They are all parsed in your browser, so nothing leaves your machine.","Put the files in the order you want them. The merged document follows the list from top to bottom, and each file contributes all of its pages.","Watch the combined page count: the merge is capped at 500 pages, and it stops as soon as the running total crosses that.","Run the merge and download the single combined PDF. The originals are left untouched."],"limitations":["At most 20 PDFs per merge, each 50 MiB or smaller, and 50 MiB across the whole selection.","The merged result may not exceed 500 pages; the copy fails the moment the running page count passes that limit.","Encrypted or password-protected PDFs are rejected. Remove the password in your PDF reader first.","Pages are copied structurally, so bookmarks, form fields, and links that depend on document-level structure can be dropped or lose their targets."],"faq":[{"q":"How is the page order decided?","a":"It follows the file list, and each file contributes all of its pages in their original order. Reorder the list before running to change the result."},{"q":"Can I merge only some pages of a file?","a":"Not here — merge copies whole documents. Use Extract PDF Pages first to cut each file down, then merge the extracts."},{"q":"What is the output named?","a":"The first file in the list, with a -merged suffix. Put the document you consider primary at the top."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.merge-pdf' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","sharedUrl.domainRequired":"Domain is required.","sharedUrl.domain":"Enter a valid domain name.","sharedUrl.absolute":"Enter an absolute http or https URL.","workspace.generated_meta_tags_d04091":"Generated meta tags"},"toolId":"devtools.meta-tag-generator","sharing":{"version":1},"app":"devtools","category":"developer-generators","keywords":["meta tags","seo","open graph","og","canonical","description","head"],"name":"Meta Tag Generator","description":"Generate common search and social meta tags.","outputLanguage":"html","input":{"kind":"fields","label":"Page metadata","fields":[{"channel":"text","label":"Page title","placeholder":"Smart Tools for Developers","required":true},{"channel":"secondary","label":"Meta description","placeholder":"Fast, private utilities for everyday development work.","required":true,"multiline":true,"surface":"card"}]},"settings":{"fields":{"keywords":{"kind":"text","label":"Keywords","default":"developer tools, utilities","pane":"input"},"author":{"kind":"text","label":"Author","default":"SmartTools","pane":"input"},"canonical":{"kind":"text","label":"Canonical URL","help":"Must be an absolute http or https URL.","default":"https://example.com/tools","pane":"main"},"image":{"kind":"text","label":"Open Graph image URL","help":"Must be absolute. Social crawlers cannot resolve a relative path.","default":"https://example.com/og.png","pane":"input","span":"full"},"locale":{"kind":"select","label":"Content locale","help":"Add a locale tag when Open Graph is included.","default":"none","choices":[{"label":"Do not emit","value":"none"},{"label":"English (United States)","value":"en_US"},{"label":"English (United Kingdom)","value":"en_GB"},{"label":"French (France)","value":"fr_FR"},{"label":"German (Germany)","value":"de_DE"},{"label":"Spanish (Spain)","value":"es_ES"}],"pane":"main"},"robots":{"kind":"select","label":"Robots directive","help":"Set whether crawlers index the page and follow its links.","default":"none","choices":[{"label":"Do not emit","value":"none"},{"label":"Index, follow","value":"index_follow"},{"label":"No index, follow","value":"noindex_follow"},{"label":"Index, no follow","value":"index_nofollow"},{"label":"No index, no follow","value":"noindex_nofollow"}],"pane":"main"},"includeOpenGraph":{"kind":"toggle","label":"Include Open Graph","help":"Include title, description, URL, image, and locale tags.","default":true},"includeTwitterCard":{"kind":"toggle","label":"Include Twitter card","help":"Include a summary large image card for Twitter.","default":false},"addViewport":{"kind":"toggle","label":"Add viewport","help":"Include a responsive device-width viewport tag.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Generate meta tags"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"META","tone":"accent"},"labels":{"empty":"Provide a page title and meta description to generate the tags.","ready":"Meta tags are ready to copy or download.","running":"Generating the meta tags…"},"content":{"howToUse":["Enter the page title and meta description. Aim for roughly 60 characters of title and 155 of description before search results truncate them.","Fill in the canonical and Open Graph image URLs if you have them — both must be absolute, and both are validated before anything is emitted.","Generate, then paste the block inside your page's head. Every value is HTML-escaped, so an apostrophe or ampersand in the title cannot break out of its attribute."],"limitations":["Title and description are required; the other four fields are optional and their tags are omitted when left blank.","No Twitter card tags, no viewport, and no charset are emitted — those belong to your template, not to this block.","The keywords tag is ignored by every major search engine. It is generated for completeness only.","Length is not enforced. Nothing warns you that a 300-character description will be truncated in results.","Relative canonical and image URLs are rejected, because social crawlers cannot resolve them."],"faq":[{"q":"Do I still need the keywords tag?","a":"No. Google, Bing, and the rest have ignored it for over a decade. Leave it blank unless an internal search tool reads it."},{"q":"Why was my image URL rejected?","a":"It must be an absolute http or https URL. A path such as /og.png cannot be fetched by a crawler that has no page context."},{"q":"Where does this block go?","a":"Inside head, and only once per page. A second canonical or og:title tag makes the page ambiguous to crawlers."}],"examples":[{"label":"Product page","text":"Smart Tools","secondary":"Fast private utilities for everyday work."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.meta-tag-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text."},"toolId":"devtools.nanoid-generator","app":"devtools","slug":"nanoid-generator","category":"hashing-crypto","keywords":["nanoid","id","identifier","random","url safe","uuid alternative","primary key"],"name":"Nano ID Generator","description":"Generate URL-safe random identifiers.","input":{"kind":"none"},"settings":{"fields":{"count":{"kind":"number","label":"How many","help":"One identifier per line.","default":5,"min":1,"max":100},"size":{"kind":"number","label":"Size","help":"Characters per identifier. 21 gives roughly the same collision resistance as a UUID v4.","default":21,"min":1,"max":256,"suffix":"chars"}}},"trigger":{"mode":"manual","actionLabel":"Generate"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"NANO","tone":"accent"},"labels":{"empty":"Choose a count and size, then generate.","ready":"Identifiers are ready.","running":"Generating identifiers…"},"content":{"howToUse":["Set how many identifiers you need and how long each should be, then generate. You get one per line.","Leave the size at 21 unless you have a reason to change it — that is the Nano ID default and is comparable to a UUID v4 in collision resistance.","Shorten only when the ID is scoped to a small set (a short link within one account, say) and you have a uniqueness check behind it.","Every character comes from the platform's cryptographically secure random source, so these are safe to use as unguessable identifiers."],"limitations":["The alphabet is fixed: `A-Z`, `a-z`, `0-9`, `_`, and `-`. It cannot be narrowed to avoid look-alike characters such as `l`, `1`, `I`, `O`, and `0`.","Identifiers carry no timestamp and no ordering, so they do not sort chronologically and are not index-friendly the way ULIDs or UUID v7 are.","Uniqueness is probabilistic, not guaranteed. Short sizes collide much sooner than you would expect — keep a unique constraint in the database.","Generation is not deduplicated within a single run, so a very small size can produce a repeat in the same batch."],"faq":[{"q":"How long should an ID be?","a":"21 characters is the safe default. Below about 12 the collision probability becomes real for anything with meaningful volume."},{"q":"Is this random enough for security?","a":"Yes — it uses the Web Crypto random source with rejection sampling, so there is no modulo bias. Do not use it as a password or a signing key, though."},{"q":"Why `_` and `-` in the alphabet?","a":"They keep the IDs URL-safe without percent-encoding, which is the point of the Nano ID alphabet."},{"q":"How does this compare to a UUID?","a":"Shorter and URL-safe for equivalent entropy, but with no version, no variant bits, and no built-in timestamp."}],"examples":[]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.nanoid-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.open-graph-preview","app":"devtools","category":"developer-generators","keywords":["open graph","og tags","social card","preview","meta tags","twitter card","link preview"],"name":"Open Graph Preview","description":"Preview a website’s social sharing cards and inspect its Open Graph metadata.","input":{"kind":"fields","label":"Website URL","fields":[{"channel":"text","label":"Website URL","placeholder":"https://example.com","required":true,"maxLength":2048}]},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Scan URL"},"capabilities":{"network":true,"cancel":true,"copy":true,"download":true},"workbenchMark":{"text":"OG","tone":"accent"},"labels":{"result":"Social previews","empty":"Enter a public website URL to inspect its sharing metadata.","ready":"Social previews and metadata checks are ready.","running":"Fetching the page and its sharing image…"},"messages":{"checks.titleFound":"Open Graph title found","checks.usingTitle":"Using the page title","checks.noTitle":"No title found","checks.addTitle":"Add og:title to control the shared title explicitly.","checks.addAnyTitle":"Add og:title or a document title.","checks.descriptionFound":"Open Graph description found","checks.descriptionMissing":"Open Graph description missing","checks.usingDescription":"The preview uses the standard meta description.","checks.addDescription":"Add og:description to explain the shared page.","checks.imageFound":"Open Graph image found","checks.imageMissing":"Usable Open Graph image missing","checks.addImage":"Add an HTTP(S) og:image URL that social crawlers can access.","checks.urlFound":"Open Graph URL found","checks.urlMissing":"Open Graph URL missing or invalid","checks.usingUrl":"The preview uses the canonical URL or fetched page address.","checks.typeFound":"Open Graph type found","checks.typeMissing":"Open Graph type missing","checks.addType":"Add og:type, usually \"website\" or \"article\".","checks.cardFound":"X card type found","checks.cardMissing":"X card type missing or unsupported","checks.addCard":"Add twitter:card to choose a summary or large-image card.","checks.duplicateTags":"Duplicate {property} tags","checks.duplicateValues":"Found {count, number} values. This preview uses the first nonempty value; platforms may choose differently.","checks.dimensionsMissing":"Image dimensions not declared","checks.addDimensions":"Add og:image:width and og:image:height. Declared dimensions are not a measurement of the downloaded image.","checks.imageUnavailable":"Image preview unavailable","checks.imageTimedOut":"The image could not be downloaded within the preview time limit.","errors.publicUrl":"Enter a public website URL or domain.","errors.responseTooLarge":"The remote response is too large to preview.","errors.unsupportedEncoding":"The page uses an unsupported content encoding.","errors.addressUnresolved":"The website's address could not be resolved.","errors.privateAddress":"Only public websites can be inspected.","errors.tooManyRedirects":"The website redirects too many times.","errors.invalidRedirect":"The website returned an invalid redirect.","errors.httpRejected":"The website returned HTTP {status}. It may block automated previews.","errors.retryPublicPage":"Try another public page or retry later.","errors.notHtml":"This URL does not return an HTML page.","errors.unsupportedImage":"The preview image is not a supported raster image.","errors.timeout":"The website took too long to respond. Try again.","errors.unreachable":"The website could not be reached securely. Check its URL and try again.","errors.imageFormatMismatch":"The image response does not match its declared format.","workspace.metadataChecks":"Metadata checks","workspace.scannedUrl":"Scanned URL","workspace.redirectedFrom":"Redirected from","workspace.sharingImage":"Sharing image","workspace.websiteUrl":"Website URL","workspace.cancel":"Cancel","workspace.editUrl":"Edit URL","workspace.socialPreviews":"Social previews","workspace.previewPlatform":"Preview platform","workspace.htmlTags":"HTML tags","workspace.fetchedHtmlTags":"Fetched HTML tags","workspace.afterAScanCheckWhichMetadataIs":"After a scan, check which metadata is present and what needs attention.","workspace.metadataInspector":"Metadata inspector","workspace.socialImage":"Social sharing image","workspace.imageUnavailable":"Image preview unavailable","workspace.noImage":"No sharing image found","workspace.noTitle":"No title found","workspace.linkPreview":"{platform} link preview","workspace.passedCheck":"Passed","workspace.warningCheck":"Warning","workspace.errorCheck":"Error","workspace.imageSize":"Declared size: {width, number} × {height, number}","errors.invalid-url":"Enter a valid public website URL or domain, such as slack.com. Credentials and custom ports are not supported.","workspace.rescan":"Rescan","workspace.scan":"Scan URL","workspace.fetching":"Fetching the page and checking its social metadata…","workspace.startHelp":"Enter a public website URL above, then scan it to see how its links could appear.","workspace.failed":"Could not scan this page","workspace.scanning":"Scanning website","workspace.previewLink":"Preview a shared link","workspace.approximatePreview":"Approximate {platform} preview. Actual appearance may vary with platform caching and layout.","workspace.errorCount":"{count, plural, one {# error} other {# errors}}","workspace.warningCount":"{count, plural, one {# warning} other {# warnings}}","workspace.passedCount":"{count, number} passed"},"content":{"howToUse":["Enter a public website URL or domain such as slack.com, then select Scan URL. Domains without a protocol use HTTPS.","Switch between Facebook, X, LinkedIn, WhatsApp, and Discord to preview the fetched title, description, and image.","Review the metadata inspector for missing tags and image issues. The HTML tags tab lets you copy or download the metadata found on the page.","After updating your website, select Rescan to fetch it again."],"limitations":["Previews approximate each platform’s layout. Platforms may crop images differently or continue displaying cached metadata.","The scanner reads the HTML returned by the website without running JavaScript. Login-only pages and sites that block automated requests cannot be inspected.","Only public HTTP and HTTPS addresses on their standard ports are supported. Scans follow up to five redirects and limit page and image sizes.","Your submitted URL and any sharing image URLs are fetched by our server. The destination websites receive those requests; browser cookies and login credentials are not forwarded."],"faq":[{"q":"Do I need to enter a title or description?","a":"No. The scanner extracts existing Open Graph and Twitter tags from your page, with the HTML title and meta description as fallbacks."},{"q":"Does this tool generate new meta tags?","a":"It inspects tags already on your website. Use Meta Tag Generator to create tags for a new page."},{"q":"Why does a platform still show my old preview?","a":"Social platforms cache their own previews. Rescanning here checks the current page but does not clear another platform’s cache."},{"q":"Why is the sharing image unavailable?","a":"The image may be missing, blocked, too large, or an unsupported format. The inspector keeps the original image URL and explains fetch failures."}],"examples":[{"label":"Inspect Slack","text":"https://slack.com"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.open-graph-preview' AND spec IS NULL;
