UPDATE managed_tools SET spec = $spec${"toolId":"devtools.password-generator","app":"devtools","category":"text-tools","keywords":["password","generator","random","secure","passphrase","crypto"],"name":"Password Generator","description":"Generate passwords with cryptographically secure randomness.","input":{"kind":"none"},"settings":{"fields":{"length":{"kind":"number","label":"Password length","help":"8–128 characters","default":16,"min":8,"max":128},"count":{"kind":"number","label":"How many","help":"Generate 1–100 passwords","default":4,"min":1,"max":100},"upper":{"kind":"toggle","label":"Uppercase A–Z","help":"Include capital letters","default":true,"span":"full"},"lower":{"kind":"toggle","label":"Lowercase a–z","help":"Include lowercase letters","default":true,"span":"full"},"numbers":{"kind":"toggle","label":"Numbers 0–9","help":"Include numeric characters","default":true,"span":"full"},"symbols":{"kind":"toggle","label":"Symbols !@#$","help":"Include special characters","default":true,"span":"full"},"excludeAmbiguous":{"kind":"toggle","label":"Exclude ambiguous characters","help":"Avoid 0, O, I, and l","default":false,"span":"full"}}},"trigger":{"mode":"manual","actionLabel":"Generate passwords"},"optionsPanel":{"layout":"grid","note":"At least one character set must remain enabled.","title":"Password rules"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"PWD","tone":"contrast"},"labels":{"empty":"Choose a length and character set, then generate.","ready":"Passwords generated.","running":"Generating passwords…"},"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","workspace.characterSetRequired":"At least one character set must remain enabled.","workspace.generate":"Generate {count, plural, one {# password} other {# passwords}}"},"content":{"howToUse":["Set the length. Length buys far more strength than exotic characters: 16 random characters is already beyond brute force.","Toggle the character groups you need. Some systems reject symbols, so turn them off rather than fighting a rejected password.","Generate a batch, pick one, and store it in a password manager. Values are produced with the Web Crypto API in this tab and are never sent anywhere."],"limitations":["Nothing is remembered. Reloading the page loses every generated value, so save the one you keep before navigating away.","Each character is drawn independently, so a password is not guaranteed to contain every enabled group. Regenerate if a site demands one of each.","The symbol set is a conservative ASCII selection; sites requiring characters outside it will need a manual edit.","At least one character group must stay enabled."],"faq":[{"q":"Is this randomness good enough?","a":"Yes. It uses the platform CSPRNG through crypto.getRandomValues, with rejection sampling so no character is more likely than another."},{"q":"Does the password leave my browser?","a":"No. Generation is local and nothing is logged or transmitted."},{"q":"How long should a password be?","a":"16 characters for general use, 20 or more for anything protecting other credentials."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.password-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.encodingPage":"Encoding page","progress.pageComplete":"Page complete","progress.packagingImages":"Packaging images","progress.imagesReady":"Images ready","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.emptyRange":"Choose at least one PDF page."},"toolId":"media.pdf-to-jpg","app":"media","category":"pdf-conversion","keywords":["pdf","jpg","jpeg","convert","render","pages","dpi","export"],"name":"PDF to JPG","description":"Convert selected PDF pages to JPG images.","input":{"kind":"files","label":"Add a PDF to convert","dropzoneDescription":"PDF · 1 file · 100 MiB max · processed on this device","accept":"application/pdf,.pdf","multiple":false,"engine":"pdf","maxFiles":1,"maxBytes":104857600,"maxTotalBytes":104857600,"inspect":true},"settings":{"fields":{"pages":{"kind":"pages","label":"Pages","help":"Use all, or ranges such as 1-3,5,8.","default":"all"},"dpi":{"kind":"select","label":"Resolution","help":"150 DPI is fine for screen use. 300 DPI is print resolution and roughly quadruples the pixel count.","default":"150","choices":[{"label":"150 DPI","value":"150"},{"label":"300 DPI","value":"300"}]},"quality":{"kind":"slider","label":"Quality","help":"JPEG quality of each rendered page. Pages are always rendered on a white background.","default":80,"min":30,"max":100,"suffix":"%"}}},"trigger":{"mode":"manual","actionLabel":"Convert to JPG"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"P2JP","tone":"accent"},"labels":{"empty":"Drop one PDF, up to 100 MiB, to convert its pages to JPG.","ready":"PDF-to-JPG page settings are ready.","running":"Converting PDF pages to JPG…"},"content":{"howToUse":["Add a single PDF. It is parsed and rendered in your browser — the document is never uploaded.","Choose which pages to export. Leave it on all, or enter ranges such as 1-3,5,8 to pull out just the pages you need.","Pick a resolution: 150 DPI for screens, email, and previews; 300 DPI when the page will be printed or cropped into.","Set the JPEG quality, run the conversion, and download. One page gives you a single JPG; several pages are bundled into a ZIP."],"limitations":["Each page becomes a flat image. Text is no longer selectable or searchable, and vector artwork becomes pixels at the chosen DPI.","JPEG cannot store transparency, so every page is rendered on white. Use PDF to PNG if you need a transparent background.","Raster conversion is capped at 200 pages per run, and a single rendered page may not exceed 100 megapixels — a large page at 300 DPI can hit that.","Encrypted or password-protected PDFs are rejected; remove the password in your PDF reader first.","The PDF must be 100 MiB or smaller."],"faq":[{"q":"Why did I get a ZIP instead of images?","a":"Any run that produces more than one page is packaged as a ZIP so the download stays a single file. Convert one page at a time if you want a bare JPG."},{"q":"Which DPI should I choose?","a":"150 DPI matches typical screen use and keeps files small. Choose 300 DPI only when the output is destined for print or will be zoomed into, since file size and memory use rise sharply."},{"q":"Can I get the text back out afterwards?","a":"Not from the JPG. Rendering flattens the page, so keep the original PDF if you still need to select, search, or copy the text."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.pdf-to-jpg' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.encodingPage":"Encoding page","progress.pageComplete":"Page complete","progress.packagingImages":"Packaging images","progress.imagesReady":"Images ready","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.emptyRange":"Choose at least one PDF page."},"toolId":"media.pdf-to-png","app":"media","category":"pdf-conversion","keywords":["pdf","png","convert","render","pages","dpi","transparent","export"],"name":"PDF to PNG","description":"Convert selected PDF pages to PNG images.","input":{"kind":"files","label":"Add a PDF to convert","dropzoneDescription":"PDF · 1 file · 100 MiB max · processed on this device","accept":"application/pdf,.pdf","multiple":false,"engine":"pdf","maxFiles":1,"maxBytes":104857600,"maxTotalBytes":104857600,"inspect":true},"settings":{"fields":{"pages":{"kind":"pages","label":"Pages","help":"Use all, or ranges such as 1-3,5,8.","default":"all"},"dpi":{"kind":"select","label":"Resolution","help":"150 DPI is fine for screen use. 300 DPI is print resolution and roughly quadruples the pixel count.","default":"150","choices":[{"label":"150 DPI","value":"150"},{"label":"300 DPI","value":"300"}]},"background":{"kind":"select","label":"Background","help":"Transparent keeps the PNG alpha channel where the page has no content. White paints the page on solid white first.","default":"white","choices":[{"label":"White","value":"white"},{"label":"Transparent","value":"transparent"}]}}},"trigger":{"mode":"manual","actionLabel":"Convert to PNG"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"P2PN","tone":"accent"},"labels":{"empty":"Drop one PDF (.pdf, up to 100 MiB) to convert its pages to PNG.","ready":"The PDF and PNG export settings are ready.","running":"Converting PDF pages to PNG…"},"content":{"howToUse":["Add a single PDF. It is parsed and rendered in your browser — the document is never uploaded.","Choose which pages to export. Leave it on all, or enter ranges such as 1-3,5,8 to pull out just the pages you need.","Pick a resolution: 150 DPI for screens and previews, 300 DPI when the page will be printed or cropped into.","Choose white or a transparent background, then run the conversion. Preview and download each PNG, or download the ZIP when exporting several pages."],"limitations":["Each page becomes a flat image. Text is no longer selectable or searchable, and vector artwork becomes pixels at the chosen DPI.","PNG is lossless, so files are much larger than the equivalent JPG — a 300 DPI page can run to tens of megabytes. Use PDF to JPG when size matters more than fidelity.","Raster conversion is capped at 200 pages per run, and a single rendered page may not exceed 100 megapixels — a large page at 300 DPI can hit that.","Encrypted or password-protected PDFs are rejected; remove the password in your PDF reader first.","The PDF must be 100 MiB or smaller."],"faq":[{"q":"When should I use the transparent background?","a":"When you want to composite the page over something else — a slide, a mockup, a coloured layout. Areas the PDF leaves blank stay transparent instead of turning white."},{"q":"Why did I get a ZIP instead of images?","a":"Runs with more than one page include a ZIP for downloading all images together. You can also preview and download each PNG individually in the output gallery."},{"q":"PNG or JPG for my pages?","a":"PNG for pages of text, diagrams, and line art, where lossless output keeps edges crisp and transparency is available. JPG for photographic pages where a much smaller file is worth some compression artefacts."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.pdf-to-png' AND spec IS NULL;
