UPDATE managed_tools SET spec = $spec${"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text."},"toolId":"devtools.sha1-generator","sharing":{"version":1},"app":"devtools","category":"hashing-crypto","keywords":["sha1","sha-1","hash","digest","checksum","git","legacy"],"name":"SHA1 Generator","description":"Generate a legacy SHA-1 digest.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"abc"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Generate SHA-1"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"S1","tone":"accent"},"labels":{"empty":"Enter the text you want to hash with SHA-1.","ready":"SHA-1 digest is ready.","running":"Generating SHA-1 digest…"},"content":{"howToUse":["Paste the exact bytes you need hashed. A trailing newline changes the digest, so copy the value verbatim.","Generate to get the 40-character lowercase hex digest, computed locally with the Web Crypto API.","Use it to match an existing SHA-1 value — a Git object id, a legacy webhook signature, an old file manifest — not to protect anything new."],"limitations":["SHA-1 is cryptographically broken. Practical collisions have existed since 2017 (SHATTERED) and chosen-prefix collisions since 2020. Do not use it for signatures, certificates, or integrity against a motivated attacker.","For new work use SHA-256 or SHA-512; for passwords use a password hash such as bcrypt or Argon2, never a raw digest.","Input is treated as UTF-8 text. Files and non-UTF-8 binary cannot be hashed here, so this will not reproduce a file checksum.","Output is always lowercase hex. Providers that expect Base64 need it converted.","Empty input is hashed rather than rejected, and yields the well-known digest of the empty string."],"faq":[{"q":"Why does my digest not match the one I was given?","a":"Almost always a bytes mismatch: a trailing newline, CRLF versus LF line endings, or leading whitespace. Check those before suspecting the algorithm."},{"q":"Can I reverse a SHA-1 digest?","a":"No. It is a one-way function. Short or common inputs can be found in precomputed tables, which is a further reason not to hash secrets with it."},{"q":"Will this match `git hash-object`?","a":"No. Git prefixes the content with a header such as `blob <length>\\0` before hashing, so the digest of the raw content differs."}],"examples":[{"label":"Classic test vector","text":"abc"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.sha1-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text."},"toolId":"devtools.sha256-generator","sharing":{"version":1},"app":"devtools","category":"hashing-crypto","keywords":["sha256","hash","digest","checksum","sha-2","hex"],"name":"SHA256 Generator","description":"Generate a SHA-256 digest.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"abc"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Generate SHA-256"},"capabilities":{"copy":true},"workbenchMark":{"text":"S256","tone":"accent"},"labels":{"empty":"Enter the text you want to hash with SHA-256.","ready":"SHA-256 digest is ready.","running":"Generating SHA-256 digest…"},"content":{"howToUse":["Paste the exact text to hash. A trailing newline changes the digest, so copy the payload verbatim rather than retyping it.","Generate. The output is the lowercase hex SHA-256 digest of the UTF-8 bytes of your input, computed locally with the Web Crypto API.","Compare it with the expected value character by character, or paste both into the hash comparison tool."],"limitations":["Input is treated as UTF-8 text. Binary files cannot be hashed here — use the checksum tool for those.","SHA-256 is a fast hash. It is right for integrity checks and content addressing, and wrong for storing passwords, which need a slow KDF such as bcrypt, scrypt, or Argon2.","The digest is unkeyed, so anyone can recompute it. Use HMAC when the point is to prove the message came from you.","Output is always lowercase hex; providers expecting Base64 need it converted."],"faq":[{"q":"Does my text leave the browser?","a":"No. Hashing runs locally through crypto.subtle.digest and nothing is uploaded or logged."},{"q":"Why does my digest not match?","a":"Almost always a byte difference: a trailing newline, CRLF instead of LF, or a different text encoding."},{"q":"Can I hash a password with this?","a":"No. A fast hash is brute-forceable at billions of guesses per second. Use bcrypt, scrypt, or Argon2."}],"examples":[{"label":"Known test vector","text":"abc"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.sha256-generator' AND spec IS NULL;
