digest and nothing is uploaded or logged."},{"q":"Why does my digest not match?","a":"Almost always a byte difference: a trailing newline, CRLF instead of LF, or a different text encoding."},{"q":"Can I hash a password with this?","a":"No. A fast hash is brute-forceable at billions of guesses per second. Use bcrypt, scrypt, or Argon2."}],"examples":[{"label":"Known test vector","text":"abc"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.sha512-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","sharedUrl.domainRequired":"Domain is required.","sharedUrl.domain":"Enter a valid domain name.","sharedUrl.absolute":"Enter an absolute http or https URL.","errors.too-many-urls":"Sitemap cannot exceed 50,000 URLs.","recovery.too-many-urls":"Split the list across several sitemaps and publish a sitemap index."},"toolId":"devtools.sitemap-generator","sharing":{"version":1},"app":"devtools","category":"developer-generators","keywords":["sitemap","xml","seo","urlset","crawl","urls","generator"],"name":"Sitemap Generator","description":"Generate an XML sitemap from one URL per line.","layout":"stacked","outputLanguage":"xml","input":{"kind":"text","label":"URLs","placeholder":"https://example.com/\nhttps://example.com/about"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Generate sitemap"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"MAP"},"labels":{"empty":"Provide one absolute URL per line to generate a sitemap.","ready":"XML sitemap is ready.","running":"Generating XML sitemap…"},"content":{"howToUse":["Paste one absolute URL per line. Blank lines are ignored and exact duplicates are collapsed.","Generate. Every URL is validated as an absolute http or https address and normalised before it is written, and each loc value is XML-escaped.","Download sitemap.xml, put it at your site root, and reference it from robots.txt with a Sitemap: line."],"limitations":["One sitemap holds at most 50,000 URLs, per the sitemaps.org protocol. Larger sites need several files plus a sitemap index, which this tool does not build.","Only loc is emitted. lastmod, changefreq, and priority are omitted — lastmod is the only one crawlers still weigh, and a wrong value is worse than none.","Relative URLs and non-http(s) schemes are rejected rather than skipped.","URLs are normalised by the URL parser, so a missing trailing slash on a bare host becomes one and IDN hosts are punycoded.","The 50MB uncompressed size limit is not checked."],"faq":[{"q":"Where do I put the file?","a":"At your site root, then add a Sitemap: line to robots.txt. A sitemap can only list URLs at or below its own directory."},{"q":"Should I add lastmod?","a":"Only if it is accurate. Crawlers discount a lastmod that always says today, so an omitted value is better than a fabricated one."},{"q":"What about more than 50,000 URLs?","a":"Split them across several sitemaps and publish a sitemap index that points at each one."}],"examples":[{"label":"Two pages","text":"https://example.com/\nhttps://example.com/about"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.sitemap-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.slug-generator","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["slug","url","permalink","seo","kebab case","handle","sanitize"],"name":"Slug Generator","description":"Create lowercase URL-safe slugs.","layout":"side-by-side","input":{"kind":"text","label":"Titles to slugify","placeholder":"Hello, Smart Tools!\nCafé Menu 2026"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Generate slugs"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"SLG"},"labels":{"empty":"Enter one or more titles to create URL-safe slugs.","ready":"URL-safe slugs are ready.","running":"Generating slugs…"},"content":{"howToUse":["Paste a title, or one title per line to slugify a whole batch at once.","Generate. Each line becomes lowercase words joined with hyphens; punctuation is dropped and accents are stripped to their base letters.","Lines that contain no letters or digits produce nothing and are removed, so the output can have fewer lines than the input.","Check the result against your existing URLs before publishing — a slug is part of a permalink and changing it later costs you the link."],"limitations":["Accents are removed rather than transliterated: `café` becomes `cafe`. Non-Latin scripts are kept as-is, which is valid in a modern URL but will be percent-encoded by browsers.","There is no de-duplication or length cap. Two identical titles produce two identical slugs, and a long title produces a long slug.","camelCase is split at the case boundary, so `smartTools` becomes `smart-tools`.","Stop words (`a`, `the`, `of`) are kept. Remove them yourself if your convention drops them."],"faq":[{"q":"Can I slugify a whole list at once?","a":"Yes. One title per line in, one slug per line out."},{"q":"Why did a line disappear?","a":"It contained no letters or digits — a line of punctuation or a blank line has no slug, so it is dropped."},{"q":"Are numbers kept?","a":"Yes. `Top 10 Tools` becomes `top-10-tools`."}],"examples":[{"label":"Title with punctuation","text":"Hello, Smart Tools!"},{"label":"Several titles","text":"Café Menu 2026\nThe Best of Ada"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.slug-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"progress.decodingImage":"Decoding image","progress.encodingImage":"Encoding image","progress.imageComplete":"Image complete","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.validateImageSelection.noFiles":"Choose at least one image.","media.validateImageSelection.tooManyFiles":"Choose no more than {limit, number} images.","media.validateImageSelection.invalidSize":"A selected file has an invalid size.","media.validateImageSelection.fileTooLarge":"Each image must be 25 MiB or smaller.","media.validateImageSelection.totalTooLarge":"The selected images must total 100 MiB or less.","media.validateDecodedImageDimensions.invalidDimensions":"The image dimensions are invalid.","media.validateDecodedImageDimensions.tooManyPixels":"The decoded image must be 100 megapixels or less.","media.image.unsupportedType":"Choose a supported image file.","media.image.imageSequence":"Multi-image HEIC sequences are not supported."},"toolId":"media.social-media-image-resizer","app":"media","category":"image-editing","keywords":["social media","resize","instagram","story","reel","youtube","thumbnail","linkedin","facebook","aspect ratio"],"name":"Social Media Image Resizer","description":"Resize images to common social media dimensions.","optionsPanel":{"collapsible":false},"input":{"kind":"files","label":"Add images to resize","dropzoneDescription":"JPG, JPEG, PNG, WebP, HEIC, and HEIF · up to 50 files · 25 MB each · processed on this device","accept":"image/jpeg,image/jpg,.jpg,.jpeg,image/png,.png,image/webp,.webp,image/heic,image/heif,.heic,.heif","multiple":true,"engine":"image","maxFiles":50,"maxBytes":26214400,"maxTotalBytes":104857600},"settings":{"fields":{"preset":{"kind":"select","label":"Platform size","help":"Every image is fitted to this exact pixel size, whatever it started as.","default":"instagram-square","choices":[{"label":"Instagram square · 1080 × 1080","value":"instagram-square","aspectRatio":1},{"label":"Instagram portrait · 1080 × 1350","value":"instagram-portrait","aspectRatio":0.8},{"label":"Story / Reel · 1080 × 1920","value":"story-reel","aspectRatio":0.5625},{"label":"YouTube thumbnail · 1280 × 720","value":"youtube-thumbnail","aspectRatio":1.7777777777777777},{"label":"X landscape · 1600 × 900","value":"x-landscape","aspectRatio":1.7777777777777777},{"label":"LinkedIn landscape · 1200 × 627","value":"linkedin-landscape","aspectRatio":1.9138755980861244},{"label":"Facebook landscape · 1200 × 630","value":"facebook-landscape","aspectRatio":1.9047619047619047}]},"fit":{"kind":"select","label":"Fit","help":"Cover fills the frame and crops whatever does not fit. Contain keeps the whole image and pads the gaps with the background colour.","default":"cover","choices":[{"label":"Cover (crop to fill)","value":"cover"},{"label":"Contain (pad to fit)","value":"contain"}]},"background":{"kind":"color","label":"Background","help":"Fills the padding left by contain, and replaces transparency when the output is JPG.","default":"#ffffff"},"outputFormat":{"kind":"select","label":"Output format","help":"PNG is lossless and keeps flat colour crisp. JPG is smaller for photographs. WebP is smaller still where the platform accepts it.","default":"png","choices":[{"label":"PNG","value":"png"},{"label":"JPG","value":"jpeg"},{"label":"WebP","value":"webp"}]},"quality":{"kind":"slider","label":"Quality","help":"Applies to JPG and WebP output. PNG is lossless and ignores it.","default":80,"min":30,"max":100,"suffix":"%"}}},"trigger":{"mode":"manual","actionLabel":"Resize images"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"1:1","tone":"accent"},"labels":{"empty":"Drop up to 50 JPG, PNG, WebP, HEIC, or HEIF images (25 MiB each) to resize for social media.","ready":"Your resized images are ready to download.","running":"Resizing social media images…"},"content":{"howToUse":["Add your images. Everything is decoded, fitted, and re-encoded in your browser, so nothing is uploaded.","Pick the platform size you are publishing to. Each output is produced at exactly those pixel dimensions regardless of what the source image measured.","Choose cover when the subject is central and you can afford to lose the edges, or contain when nothing may be cropped — contain pads the leftover space with the background colour.","Set the background, output format, and quality, then run and download. Each file is named after its source with the chosen preset appended, so a batch stays easy to sort."],"limitations":["Cover crops from the centre. There is no way to choose the crop point, so an off-centre subject may lose its head — use contain if the framing is tight.","Small sources are enlarged to reach the target size and will look soft. Start from an image at least as large as the preset in both dimensions.","Contain always pads with a solid colour; transparent padding is not offered even when the output is PNG.","Platform requirements change. The presets cover the common sizes at the time of writing, not every placement each network supports.","Each image must be 25 MiB or smaller, up to 50 files per run, and no more than 100 megapixels once decoded."],"faq":[{"q":"Which fit should I use?","a":"Cover for photographs, because the frame is filled edge to edge. Contain for logos, screenshots, and anything with text near the border, where losing an edge would ruin it."},{"q":"Can I make one image for several platforms at once?","a":"Not in a single run — each run uses one preset. Run the same files again with a different preset; the preset name in each filename keeps the outputs apart."},{"q":"Why does my image look stretched or soft?","a":"It is never stretched: the aspect ratio is always preserved. Softness means the source was smaller than the target and had to be enlarged, so supply a larger original."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.social-media-image-resizer' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"media.split-pdf","app":"media","category":"pdf-organization","keywords":["pdf","split","divide","separate","pages","ranges","interval"],"name":"Split PDF","description":"Split a PDF by page, interval, or range.","layout":"stacked","optionsPanel":{"defaultCollapsed":false},"input":{"kind":"files","label":"Add a PDF to split","dropzoneDescription":"PDF · 1 file · 50 MiB max · processed on this device","accept":"application/pdf,.pdf","multiple":false,"engine":"pdf","maxFiles":1,"maxBytes":52428800,"maxTotalBytes":52428800,"inspect":true},"settings":{"fields":{"mode":{"kind":"select","label":"Split mode","help":"How the document is cut up: one file per page, fixed-size chunks, or explicit ranges.","default":"every-page","choices":[{"label":"Every page","value":"every-page"},{"label":"Every N pages","value":"interval"},{"label":"Custom ranges","value":"ranges"}]},"interval":{"kind":"number","label":"Pages per file","help":"Each output file takes this many pages; the last file keeps whatever is left over.","default":1,"min":1,"visibleWhen":{"key":"mode","equals":"interval"}},"ranges":{"kind":"text","label":"Ranges","help":"One output file per range, separated by semicolons — 1-3;4-6 gives two files. Inside a range use commas and hyphens, such as 1,3,5-9.","default":"1","placeholder":"1-3;4-6","visibleWhen":{"key":"mode","equals":"ranges"}},"bundleAsZip":{"kind":"toggle","label":"Bundle as ZIP","help":"Add a ZIP archive while keeping the individual PDF downloads.","default":true}}},"trigger":{"mode":"manual","actionLabel":"Split PDF"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"P|P","tone":"contrast"},"labels":{"empty":"Drop one PDF (up to 50 MiB) to split by page, interval, or range.","ready":"Your split PDFs are ready to download.","running":"Splitting PDF…"},"messages":{"progress.creatingSplitPdf":"Creating split PDF","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.noFiles":"Choose a PDF to split.","errors.emptyRange":"Choose at least one page range.","errors.invalidInterval":"Pages per file must be a positive whole number.","workspace.splitSettings":"Split settings","workspace.planTitle":"{count, plural, one {# PDF will be created} other {# PDFs will be created}}","workspace.plannedParts":"Planned PDF parts","workspace.part":"Part {part}: {count, plural, one {page} other {pages}} {pages}","workspace.invalidInterval":"Pages per file must be a positive whole number.","workspace.invalidRange":"Enter valid page groups using page numbers from 1 to {count, number}. Separate groups with semicolons."},"content":{"howToUse":["Add a single PDF. It is read in your browser and its page count is detected for you.","Choose Every page to burst the document into one file per page — handy for scanned batches where each sheet is its own record.","Choose Every N pages and set the count when the document has a regular structure, such as a two-page invoice repeated many times.","Choose Custom ranges and enter one range per output file separated by semicolons — 1-3;4-6 produces two PDFs — then run the split and download the parts."],"limitations":["The source document is capped at 500 pages; anything longer is rejected before splitting starts.","Ranges must stay inside the document and may not repeat a page within the same range; either mistake stops the run with an error.","Every-page mode on a long document produces one file per page, so a 300-page PDF becomes 300 outputs.","Encrypted or password-protected PDFs are rejected; remove the password first.","Pages are copied structurally, so links and form fields pointing at pages outside their own part end up dangling."],"faq":[{"q":"What separates one output file from the next in ranges mode?","a":"The semicolon. Commas and hyphens build up the pages inside a single output, so 1-3,7;8-9 gives one file with pages 1, 2, 3, 7 and a second with pages 8 and 9."},{"q":"Can a page appear in more than one output?","a":"Across separate ranges, yes — 1-5;3-8 is fine. Repeating a page inside a single range is an error."},{"q":"How are the output files named?","a":"The source filename with a -part-01, -part-02 suffix, numbered in the order the ranges were given."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.split-pdf' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sql.loading":"Loading SQL engine…","workspace.engine":"Database engine","workspace.plan.pgSummary":"PostgreSQL runs this query in {count, plural, one {# step} other {# steps}}. Indented steps feed the step above them.","sql.summary":"Ran {statements, plural, one {# statement} other {# statements}} in {ms, number} ms; {queries, plural, =0 {no query returned rows} one {# query returned {rows, plural, one {# row} other {# rows}}} other {# queries returned {rows, plural, one {# row} other {# rows}} in total}}.","sql.summaryWrites":"{rows, plural, one {# row was} other {# rows were}} changed by your statements.","sql.summaryOmitted":"{count, plural, one {# more query ran} other {# more queries ran}} but only the first 20 result tables are kept.","sql.stopped":"Stopped at line {line}: {message}","sql.stoppedDetail":"{statements, plural, =0 {No statement finished before the error.} one {# statement finished before the error.} other {# statements finished before the error.}} Fix the statement on that line and run again.","sql.noOutput":"No output. The script ran without returning any rows.","sql.noOutputChanged":"No output. The script ran and {count, plural, one {# row was} other {# rows were}} changed.","sql.noRows":"This query returned no rows.","errors.sql-too-large":"The SQL is larger than 64 KiB.","recovery.sqlTooLarge":"Remove some statements, or split the script into smaller runs.","errors.sql-timeout":"The script was stopped after running for 5 seconds.","recovery.sqlTimeout":"A query may be looping or scanning too much data. Add a LIMIT or a stopping condition, then run again. Your SQL is unchanged.","errors.sql-engine-load":"The SQL engine could not be loaded.","recovery.sqlEngineLoad":"Check your connection and press Run to try again. Your SQL is still in the editor and nothing was lost.","workspace.results":"SQL results","workspace.tables":"Result tables","workspace.table":"Result {n}, line {line}","workspace.showing":"Showing the first {shown, number} of {total, number} rows. The CSV download includes {csvRows}.","workspace.csvAll":"every row","workspace.csvPartial":"the first rows only (the CSV size limit was reached)","workspace.rowCount":"{count, plural, one {# row} other {# rows}}","workspace.downloadCsv":"Download CSV","workspace.nullHint":"NULL means no value; an empty string is shown as a blank cell.","workspace.nullCell":"NULL","workspace.runStatement":"Run this statement","workspace.runSelection":"Run selection","workspace.runAll":"Run all","workspace.explain":"Explain (bytecode)","workspace.explainPlan":"Explain query plan","workspace.plan.summary":"SQLite runs this query in {count, plural, one {# step} other {# steps}}, from top to bottom.","workspace.plan.scan":"Reads every row of {target}, one by one. Quick on small tables, slow on big ones.","workspace.plan.search":"Jumps straight to the matching rows of {target} using an index or the primary key.","workspace.plan.temp":"{clause, select, ORDER {Builds a temporary sorted list to put the rows in order.} GROUP {Builds a temporary list to group the rows.} DISTINCT {Builds a temporary list to remove duplicate rows.} other {Builds a temporary list to process the rows.}}","workspace.explainBytecodeHelp":"These are the low-level steps SQLite runs for this statement, one per line. Each line is an operation (opcode) with its operands (p1 to p5). Use Explain query plan for a plain summary.","workspace.cut":"Cut","workspace.copy":"Copy","workspace.paste":"Paste","workspace.selectAll":"Select all","workspace.info.statements":"Statements","workspace.info.time":"Run time","workspace.info.returned":"Rows returned","workspace.info.changed":"Rows changed","workspace.info.ms":"{ms, number} ms","workspace.writes":"Changes","workspace.writeLine":"Line {line}: {rows, plural, one {# row changed} other {# rows changed}}"},"toolId":"devtools.sql-compiler","app":"devtools","category":"compilers","keywords":["sql","sqlite","postgresql","postgres","online sql","sql compiler","sql playground","run sql","postgres online compiler"],"name":"SQL Compiler","description":"Run SQLite or PostgreSQL queries in your browser and see the results as tables.","input":{"kind":"text","language":"sql","label":"SQL","showLineNumbers":true,"maxLength":65536,"placeholder":"CREATE TABLE ...; INSERT ...; SELECT ...;","acceptFiles":{"accept":".sql,.txt,text/plain","maxBytes":65536}},"settings":{"fields":{"engine":{"kind":"select","label":"Database engine","help":"SQLite starts instantly. PostgreSQL is a real PostgreSQL 18 server: a one-time download of several megabytes that your browser keeps.","default":"sqlite","choices":[{"value":"sqlite","label":"SQLite 3.54"},{"value":"postgres","label":"PostgreSQL 18"}]}}},"trigger":{"mode":"manual","actionLabel":"Run"},"capabilities":{"cancel":true,"progress":true},"workbenchMark":{"text":"SQL","tone":"contrast"},"labels":{"result":"Results","empty":"Press Run to execute your SQL and see the results here.","ready":"Results are ready.","running":"Running SQL…"},"content":{"howToUse":["Pick SQLite or PostgreSQL next to the file name, then write statements in the editor. The starter creates a table, adds rows and selects them on both engines, so you can press Run straight away.","Press Run or Ctrl/Cmd+Enter. Every statement runs in order against a fresh, empty in-memory database.","Read the sentence at the top of the results, then open a result table for each query. Writes list how many rows they changed.","If a statement fails, the message names the line. Earlier results stay visible."],"limitations":["Choose the engine your SQL is written for: SQLite or PostgreSQL 18. MySQL, SQL Server and Oracle syntax may fail on both.","PostgreSQL is downloaded the first time you pick it (several megabytes) and takes a few seconds to start; your browser keeps the download for later visits.","Nothing is saved: each run starts with an empty database and your tables disappear afterwards.","SQL is limited to 64 KiB, 1,000 rows are shown per result table and at most 20 result tables are kept.","A run is stopped after 5 seconds. The CSV download holds every row of a result table, within a size limit."],"faq":[{"q":"Is my SQL sent to a server?","a":"No. SQLite and PostgreSQL both run inside your browser tab as WebAssembly. Your SQL and results never leave your device."},{"q":"Which PostgreSQL version runs, and is it real PostgreSQL?","a":"PostgreSQL 18, compiled to WebAssembly (PGlite). It is the real database server, so features such as SERIAL, ILIKE, JSONB, arrays, CTEs and PL/pgSQL functions work. Extensions that need a separate install are not available."},{"q":"Why does my query work on one engine but not the other?","a":"SQLite and PostgreSQL speak different SQL dialects. For example SERIAL, ILIKE and :: casts are PostgreSQL only, while AUTOINCREMENT and square-bracket names are SQLite only. Switch the engine to the one your SQL is written for."},{"q":"Will my tables still be there next time?","a":"No. Each run opens a new empty in-memory database, so put the CREATE TABLE and INSERT statements in the same script."}],"examples":[{"label":"Starter","text":"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, city TEXT);\nINSERT INTO users (id, name, city) VALUES (1, 'Ada', 'London'), (2, 'Grace', NULL), (3, 'Linus', '');\nSELECT id, name, city FROM users ORDER BY name;\nSELECT count(*) AS people FROM users;\n"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.sql-compiler' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"errors.unknown-case":"Choose a valid text case."},"toolId":"devtools.text-case-converter","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["case","camelcase","snake_case","kebab-case","uppercase","title case","convert"],"name":"Text Case Converter","description":"Convert text between common naming and prose cases.","layout":"side-by-side","input":{"kind":"text","label":"Text to convert","placeholder":"hello smart tools"},"settings":{"fields":{"target":{"kind":"select","label":"Convert to","default":"title","choices":[{"label":"UPPERCASE","value":"upper"},{"label":"lowercase","value":"lower"},{"label":"Title Case","value":"title"},{"label":"Sentence case","value":"sentence"},{"label":"camelCase","value":"camel"},{"label":"PascalCase","value":"pascal"},{"label":"snake_case","value":"snake"},{"label":"kebab-case","value":"kebab"},{"label":"CONSTANT_CASE","value":"constant"}]}}},"trigger":{"mode":"live"},"capabilities":{"copy":true},"workbenchMark":{"text":"Aa"},"labels":{"empty":"Enter text and choose the case to convert it.","ready":"Case-converted text is ready.","running":"Converting text case…"},"content":{"howToUse":["Paste the text or identifier you want reshaped. Output updates as you type.","Pick the target case. The identifier cases (camel, Pascal, snake, kebab, CONSTANT) split the input on spaces, punctuation, and existing camelCase boundaries first.","UPPERCASE and lowercase are the only options that leave punctuation and spacing intact — the rest rebuild the string from its words."],"limitations":["Words are detected from letters and digits only, so every other character is dropped by the identifier cases.","Accents are stripped during word splitting, so naïve becomes naive in camel, snake, kebab, and CONSTANT output.","Title Case capitalises every word; it does not apply editorial rules that keep short prepositions lowercase.","Sentence case capitalises only the first word — existing acronyms are lowercased with the rest."],"faq":[{"q":"Why did my punctuation disappear?","a":"camelCase, snake_case, kebab-case, PascalCase, and CONSTANT_CASE are identifier formats. They are rebuilt from words, so separators other than the target one are dropped."},{"q":"Does it split existing camelCase?","a":"Yes. smartTools is treated as two words, so it converts cleanly to smart_tools."}],"examples":[{"label":"Plain phrase","text":"hello smart tools"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.text-case-converter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.text-diff-checker","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["diff","compare","text","changes","lines","difference","review"],"name":"Text Diff Checker","description":"Compare two texts line by line.","layout":"side-by-side","input":{"kind":"fields","label":"Text Versions","fields":[{"channel":"text","label":"Original text","placeholder":"alpha\nbeta\ngamma","required":true,"multiline":true},{"channel":"secondary","label":"Changed text","placeholder":"alpha\nbeta updated\ngamma","multiline":true}]},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Compare text"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"+/-","tone":"contrast"},"labels":{"empty":"Provide the original and changed text to compare them.","ready":"Line-by-line comparison is ready.","running":"Comparing text line by line…"},"messages":{"sharedDiff.tooLarge":"This comparison is too large to align safely. Compare smaller sections.","sharedDiff.recovery":"Split the inputs into smaller sections and compare them one at a time.","textDiff.changed":"{added, plural, one {# line} other {# lines}} added · {removed, plural, one {# line} other {# lines}} removed","textDiff.identical":"No differences","textDiff.comparison":"Comparing changed text against original text. Whitespace is significant; line endings are normalized.","textDiff.original":"Original text","textDiff.changedText":"Changed text","workspace.editText":"Edit text"},"content":{"howToUse":["Paste the original version in the first field and the changed version in the second.","Click Compare text to see both versions aligned side by side. Removed lines appear on the left with a minus; added lines appear on the right with a plus.","Choose Edit text to return to both editors and compare again. Matching text is reported as No differences, with both versions still visible.","Copy or download the marked-up result to paste into a review comment or a ticket."],"limitations":["The comparison is line-based. A one-character edit is reported as the whole line being replaced; there is no word-level or character-level highlighting.","Lines are matched exactly, including leading and trailing whitespace, so a re-indent registers as a change.","The alignment is capped: the product of the two line counts must stay under four million — roughly 2,000 lines against 2,000 lines. Larger inputs are rejected rather than allowed to freeze the tab.","The output is a readable marker format, not a unified diff with hunk headers, so it cannot be fed to `git apply`."],"faq":[{"q":"Does my text leave the browser?","a":"No. Both versions are compared locally in this tab and are never uploaded."},{"q":"Why is a moved block shown as a delete plus an add?","a":"The alignment finds the longest common subsequence, which has no way to express a move. A relocated block appears as a removal at the old position and an addition at the new one."},{"q":"Are CRLF and LF line endings treated the same?","a":"Yes. Both inputs are split on CR, LF, or CRLF, so a line-ending difference alone does not register as a change."},{"q":"Can I use this output as a patch file?","a":"No. It is a review format, not a unified diff."}],"examples":[{"label":"One edited line","text":"alpha\nbeta\ngamma","secondary":"alpha\nbeta updated\ngamma"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.text-diff-checker' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.text-reverser","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["reverse","backwards","flip","text","words","lines"],"name":"Text Reverser","description":"Reverse characters, words, or lines.","layout":"side-by-side","input":{"kind":"text","label":"Text to reverse","placeholder":"one two three"},"settings":{"fields":{"mode":{"kind":"select","label":"Reverse by","default":"chars","choices":[{"label":"Characters","value":"chars"},{"label":"Words","value":"words"},{"label":"Lines","value":"lines"}]}}},"trigger":{"mode":"manual","actionLabel":"Reverse"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"cba"},"labels":{"empty":"Enter the text you want to reverse.","ready":"Reversed text is ready.","running":"Reversing text…"},"content":{"howToUse":["Paste the text you want reversed.","Choose the unit: Characters flips the whole string, Words flips the word order, Lines flips the line order.","Reverse, then copy the result."],"limitations":["Character mode reverses by Unicode code point, so emoji and non-Latin scripts survive — but multi-code-point sequences such as a flag emoji or an accented letter written with a combining mark will come apart.","Word mode trims the text and collapses every run of whitespace to a single space, so the original spacing is not preserved.","Line mode joins with \\n, so CRLF input comes back LF-only."],"faq":[{"q":"Why did my emoji break in character mode?","a":"Sequences built from several code points — skin-tone modifiers, flags, family emoji — are reversed element by element and lose their joiners. Use word or line mode if the text contains them."},{"q":"Can I reverse lines without changing the words?","a":"Yes, that is exactly what Lines mode does: the last line becomes the first, and each line's contents are untouched."}],"examples":[{"label":"Reverse characters","text":"one two three"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.text-reverser' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.text-sorter","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["sort","lines","alphabetical","order","ascending","descending","list"],"name":"Text Sorter","description":"Sort lines ascending or descending.","layout":"side-by-side","input":{"kind":"text","label":"Lines of text","placeholder":"Banana\napple\nCherry"},"settings":{"fields":{"order":{"kind":"select","label":"Order","default":"asc","choices":[{"label":"A → Z","value":"asc"},{"label":"Z → A","value":"desc"}]},"ci":{"kind":"toggle","label":"Case-insensitive","help":"On, `apple` sorts next to `Apple`. Off, uppercase and lowercase are distinct.","default":true}}},"trigger":{"mode":"manual","actionLabel":"Sort lines"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"A-Z"},"labels":{"empty":"Enter one item per line to sort the list.","ready":"Sorted lines are ready.","running":"Sorting lines…"},"content":{"howToUse":["Paste your list, one item per line.","Pick the direction and decide whether case should matter, then sort.","Sorting uses English collation, so accented letters land next to their base letter rather than after `z`.","Every input line is kept — blank lines and duplicates are sorted, not removed."],"limitations":["This is a lexicographic sort, not a numeric one: `10` sorts before `9`. Pad numbers with leading zeros if you need numeric order.","Blank lines are preserved and sort to the top; duplicates are preserved.","Comparison uses English collation regardless of browser locale, so shared links keep the same ordering. Other languages may have different alphabetical conventions.","There is no sort-by-column or sort-by-field — the whole line is the key."],"faq":[{"q":"Why is `10` before `9`?","a":"Lines are compared as text, character by character, so `1` precedes `9`. Zero-pad to `09` and `10` for numeric order."},{"q":"Does it remove duplicates?","a":"No. Use a duplicate-line remover first if you want a unique sorted list."},{"q":"What happens to leading whitespace?","a":"It is part of the line and affects the sort. Trim your input first if that is not what you want."}],"examples":[{"label":"Mixed case","text":"Banana\napple\nCherry"},{"label":"Numbers as text","text":"9\n10\n1"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.text-sorter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.text-to-binary","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["binary","text","utf-8","bytes","encode","bits","base 2"],"name":"Text to Binary","description":"Encode UTF-8 text as binary bytes.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"Hello 👋"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Encode as binary"},"capabilities":{"copy":true},"workbenchMark":{"text":"T>B"},"labels":{"empty":"Enter text to encode as UTF-8 binary.","ready":"Binary bytes are ready.","running":"Encoding text as binary…"},"content":{"howToUse":["Type or paste the text. It is encoded as UTF-8 first, then each byte is written as eight bits.","Encode. Bytes are separated by a single space and are always zero-padded to eight digits.","Remember that one character is not one byte: ASCII characters take one byte, accented Latin usually two, and most emoji four."],"limitations":["UTF-8 only. There is no option for UTF-16, Latin-1, or any other encoding.","The separator is a fixed single space — there is no way to group by character, insert byte prefixes, or emit a continuous bit stream.","Whitespace in the input is encoded like any other character, so a trailing newline becomes `00001010`.","Output grows to roughly nine times the byte length of the input, so large inputs get unwieldy fast."],"faq":[{"q":"Why does one emoji produce four groups?","a":"It is four UTF-8 bytes. The tool shows bytes, not characters."},{"q":"Can I change the separator or grouping?","a":"No. The format is a fixed space-separated list of eight-bit groups."},{"q":"How do I go back to text?","a":"Use the Binary to Text tool, which reads the same space-separated eight-bit format."}],"examples":[{"label":"ASCII and emoji","text":"Hello 👋"},{"label":"Plain word","text":"binary"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.text-to-binary' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text."},"toolId":"devtools.text-to-hex","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["hex","hexadecimal","encode","utf-8","bytes","dump"],"name":"Text to Hex","description":"Encode UTF-8 text as hexadecimal bytes.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"Hello 👋"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Encode as hex"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"T>0x"},"labels":{"empty":"Enter text to encode as UTF-8 hexadecimal.","ready":"Hexadecimal bytes are ready.","running":"Encoding text as hexadecimal…"},"content":{"howToUse":["Paste the text you want to inspect as bytes.","Encode. Each byte of the UTF-8 encoding becomes two lowercase hex digits, with no separators.","Use it to check exactly what is on the wire — an invisible BOM, a non-breaking space, or a trailing newline all show up here."],"limitations":["Output is lowercase and unseparated. Tools that expect spaced or 0x-prefixed bytes need the string reformatted.","The encoding is always UTF-8; there is no option for UTF-16 or a legacy single-byte codepage.","Text only — binary input cannot be pasted accurately."],"faq":[{"q":"Why is one character several bytes?","a":"UTF-8 is variable width. ASCII is one byte, most accented and Greek/Cyrillic letters are two, most CJK is three, and emoji are four."},{"q":"How do I spot a hidden character?","a":"Look for efbbbf (a byte-order mark), c2a0 (a non-breaking space), or a trailing 0a / 0d0a newline."}],"examples":[{"label":"Text with an emoji","text":"Hello 👋"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.text-to-hex' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedDate.invalid":"{endpoint, select, start {Start date} end {End date} other {Date}} is not a valid date or timestamp.","sharedDate.required":"{endpoint, select, start {Start date} end {End date} other {Date}} is required.","sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","errors.batch-invalid-date":"\"{input}\": Timestamp or date is not a valid date or timestamp.","errors.batch-conversion":"\"{input}\": Conversion failed.","errors.invalid-date":"Timestamp or date is not a valid date or timestamp."},"toolId":"devtools.timestamp-converter","app":"devtools","category":"date-time-tools","keywords":["timestamp","unix","epoch","iso 8601","utc","date","milliseconds","convert"],"name":"Timestamp Converter","description":"Convert Unix timestamps or date text to standard formats.","layout":"side-by-side","input":{"kind":"fields","label":"Unix Timestamp or Date","fields":[{"channel":"text","label":"Timestamp or date","placeholder":"1704067200\n2024-01-01T00:00:00Z","required":true,"multiline":true}]},"settings":{"fields":{"inputUnit":{"kind":"select","label":"Input unit","help":"Auto-detect numeric timestamps or treat them as seconds or milliseconds.","default":"auto","choices":[{"label":"Auto-detect seconds / milliseconds","value":"auto"},{"label":"Seconds","value":"seconds"},{"label":"Milliseconds","value":"milliseconds"}],"pane":"main"},"outputTimezone":{"kind":"select","label":"Output timezone","help":"Show local and UTC dates together, or only one timezone.","default":"local-and-utc","choices":[{"label":"Local time + UTC","value":"local-and-utc"},{"label":"UTC only","value":"utc"},{"label":"Local time only","value":"local"}],"pane":"main"},"useLocalTimezone":{"kind":"toggle","label":"Use local timezone","help":"Use the browser timezone for the locale-formatted date instead of UTC.","default":true},"includeRelativeTime":{"kind":"toggle","label":"Include relative time","help":"Append an English approximation of how far the converted timestamp is from now.","default":false},"twentyFourHour":{"kind":"toggle","label":"24-hour clock","help":"Format the local time without AM or PM.","default":false}}},"trigger":{"mode":"live","debounceMs":200},"capabilities":{"copy":true},"workbenchMark":{"text":"UNIX"},"labels":{"empty":"Enter a Unix timestamp or a date to convert it.","ready":"Timestamp conversions are ready.","running":"Converting timestamp…"},"content":{"howToUse":["Paste a Unix timestamp in seconds or milliseconds, or a date string such as `2024-01-01T00:00:00Z`. The conversions update as you type.","Read ISO 8601 for logs and APIs, the RFC 1123 UTC line for HTTP headers, and the two Unix rows when you need the number in the other unit.","The 'Local' line is a fixed en-US rendering in your browser's own time zone — useful for a sanity check, not a locale-accurate display."],"limitations":["Seconds and milliseconds are told apart by magnitude: a bare number whose absolute value is below 100,000,000,000 is read as seconds, otherwise as milliseconds. A far-future timestamp in seconds is therefore misread as milliseconds.","Non-numeric input goes through the browser's date parser, whose handling of anything other than ISO 8601 is implementation-defined. `01/02/2024` is ambiguous and is not parsed consistently across browsers.","A date with no time zone (`2024-01-01T00:00:00`) is interpreted as local time, while a date-only string (`2024-01-01`) is interpreted as UTC. That inconsistency is in the JavaScript language, not in this tool.","The 'Local' line is formatted with an explicit `en-US` locale so the output is reproducible. It is not localised to your language or regional format.","Sub-millisecond precision is not supported; nanosecond timestamps must be divided down first."],"faq":[{"q":"Seconds or milliseconds — which does it expect?","a":"Either. The magnitude decides: anything under 100,000,000,000 is treated as seconds, everything above as milliseconds. Both rows are always shown in the result."},{"q":"Which time zone is 'Local'?","a":"Your browser's. The date and time formatting is pinned to en-US so the same instant always renders identically, but the zone comes from your system."},{"q":"Why is my date one day off?","a":"Usually the local-versus-UTC rule. `2024-01-01` parses as UTC midnight, so anyone west of Greenwich sees it as December 31 locally. Add an explicit `T00:00:00Z` or an offset."},{"q":"Can I convert negative timestamps?","a":"Yes. Negative values are dates before 1970 and are handled normally."}],"examples":[{"label":"New Year 2024 in seconds","text":"1704067200"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.timestamp-converter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"csv.processing":"Processing delimited data","csv.rows":"Rows","csv.columns":"Columns","csv.download":"Download","csv.completeFile":"Complete generated file","csv.errors.inputRequired":"Delimited input is required.","csv.errors.invalidDelimiter":"Choose a valid delimiter.","csv.errors.emptyTable":"Delimited input has no rows.","csv.errors.inconsistentWidth":"Every row must have the same number of fields.","csv.errors.unexpectedCharacter":"Unexpected character {character} after a closing quote.","csv.errors.unexpectedQuote":"A quoted field must start after a delimiter.","csv.errors.unclosedQuote":"A quoted CSV field is not closed.","csv.errors.streamEncoding":"Invalid UTF-8 at row {row}, column {column}.","csv.errors.streamUnexpectedCharacter":"Unexpected character {character} after a closing quote at row {row}, column {column}.","csv.errors.streamUnexpectedQuote":"Unexpected quote at row {row}, column {column}. Quotes must start at the beginning of a field.","csv.errors.streamUnclosedQuote":"Unclosed quoted field at row {row}, column {column}.","csv.errors.streamFieldTooLarge":"Field at row {row}, column {column} exceeds the {limit, number} byte safety limit.","csv.errors.streamRowTooLarge":"Row {row} exceeds the {limit, number} byte safety limit.","csv.errors.streamWidth":"Row {row} has {actual, plural, one {# column} other {# columns}}; expected {expected, plural, one {# column} other {# columns}}.","csv.recovery.inputRequired":"Enter a value and try again.","csv.recovery.delimiter":"Choose comma, semicolon, tab, or pipe.","csv.recovery.structure":"Check the delimiter, quotes, and field counts, then try again."},"toolId":"devtools.tsv-to-csv","sharing":{"version":1},"app":"devtools","category":"csv-data-tools","keywords":["tsv","csv","convert","tab","spreadsheet","delimited"],"name":"TSV to CSV","description":"Convert tab-separated values to CSV.","outputLanguage":"csv","previewLayout":"table","input":{"kind":"text","language":"tsv","label":"TSV input","surface":"card","acceptFiles":{"accept":".csv,.tsv,text/csv,text/tab-separated-values","maxBytes":104857600,"maxEditableBytes":2000000},"placeholder":"name\tage\nAda\t36"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Convert to CSV"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"T>C"},"labels":{"empty":"Enter tab-separated rows to convert them to CSV.","ready":"CSV output is ready.","running":"Converting TSV to CSV…"},"content":{"howToUse":["Copy a range straight out of a spreadsheet — the clipboard format is already tab-separated — and paste it here.","Convert. Fields containing a comma, a quote, or a line break are quoted and their quotes doubled, so the CSV survives a round trip.","Copy or download the result."],"limitations":["Every row must have the same number of fields. A ragged paste is rejected rather than silently padded.","The output always uses a comma. Use the delimiter converter if you need semicolons for a locale that treats the comma as a decimal separator.","No BOM is written. Some spreadsheet apps need one to detect UTF-8 — add it in your editor if accents come out wrong."],"faq":[{"q":"Why was my input rejected?","a":"Rows had differing field counts. A tab inside a value, or a trailing tab on one line, is the usual cause."},{"q":"Are quotes handled?","a":"Yes. Values containing a comma, a double quote, or a newline are wrapped in quotes with inner quotes doubled."}],"examples":[{"label":"Two columns","text":"name\tage\nAda\t36"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.tsv-to-csv' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"codeRun.source.required":"Write some code to run.","codeRun.source.encoding":"Source code is not valid UTF-8 text.","codeRun.source.nul":"Source code contains a NUL character.","codeRun.source.too-large":"Source code is larger than {max}.","codeRun.stdin.encoding":"Input is not valid UTF-8 text.","codeRun.stdin.nul":"Input contains a NUL character.","codeRun.stdin.too-large":"Input is larger than {max}.","codeRun.ok":"Your program ran successfully in {duration} and printed {lines, plural, =0 {nothing} one {# line} other {# lines}}.","codeRun.okDetail":"It exited with code 0.","codeRun.compileError":"Compilation failed.","codeRun.compileErrorAt":"Compilation failed at line {line}: {message}","codeRun.compileErrorDetail":"Fix the error in the compiler output below, then run again.","codeRun.runtimeError":"Your program stopped with an error (exit code {code}).","codeRun.runtimeErrorDetail":"Check the error output below for the cause.","codeRun.killed":"Your program was stopped by the signal {signal}.","codeRun.killedDetail":"{signal, select, SIGKILL {SIGKILL usually means the memory or process limit was reached.} SIGSEGV {SIGSEGV means the program touched memory it does not own, for example an invalid pointer or unbounded recursion.} SIGABRT {SIGABRT means the program aborted itself, often after a failed assertion or an unhandled error.} SIGFPE {SIGFPE means an illegal arithmetic operation, such as dividing an integer by zero.} SIGXCPU {SIGXCPU means the CPU time limit was reached.} SIGXFSZ {SIGXFSZ means the program tried to write a file larger than allowed.} other {The operating system ended the program with this signal.}}","codeRun.timeLimitRun":"Stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitCompile":"Compilation was stopped after {seconds} seconds of {kind, select, wall {total running time} other {CPU time}}.","codeRun.timeLimitDetail":"Look for an endless loop or work that can be made smaller, then run again.","codeRun.outputLimit":"Your program printed more than the allowed amount of {stream, select, stderr {error output} other {output}}.","codeRun.outputLimitDetail":"The output below is cut off. Print less, then run again.","codeRun.unavailable":"Code execution is not available right now.","codeRun.unavailableDetail":"{reason, select, notConfigured {Running code is switched off on this server.} runtimeMissing {This language version is not installed on the execution server.} other {The execution server did not respond.}} Your code is kept. Try again in a minute.","codeRun.busy":"The execution server is busy.","codeRun.busyDetail":"Your code is kept. Try again in {seconds} seconds.","codeRun.fact.time":"Run time","codeRun.fact.cpu":"CPU time","codeRun.fact.memory":"Memory","codeRun.fact.exit":"Exit code","codeRun.fact.signal":"Signal","codeRun.fact.language":"Language","codeRun.section.stdout":"Standard output","codeRun.section.stderr":"Error output","codeRun.section.compiler":"Compiler output","codeRunner.editor":"{language} source code","codeRunner.stdin":"Standard input (stdin)","codeRunner.stdinHelp":"Type anything your program reads before you press Run. Input cannot be typed while the program is running.","codeRunner.stdinPlaceholder":"Optional. For example: Ada","codeRunner.run":"Run","codeRunner.cancel":"Cancel","codeRunner.runTooltip":"Run your program ({shortcut})","codeRunner.cancelTooltip":"Stop this run. Your code stays as it is.","codeRunner.running":"Running your program…","codeRunner.cancelled":"Run cancelled. Your code is unchanged.","codeRunner.reset":"Reset to starter","codeRunner.resetTitle":"Reset to the starter program?","codeRunner.resetBody":"Your current code is replaced by the starter program and your saved draft is removed.","codeRunner.resetConfirm":"Reset","codeRunner.resetKeep":"Keep my code","codeRunner.upload":"Upload file","codeRunner.uploadFailed":"{name} could not be read as text.","codeRunner.uploadTooLarge":"{name} is larger than {max} KiB. Choose a smaller file.","codeRunner.download":"Download source","codeRunner.version":"{language} version","codeRunner.versionTooltip":"Choose which version runs your code. Each run uses exactly that version.","codeRunner.draftNote":"Your code is saved in this browser only, until you run it.","codeRunner.resultPlaceholder":"Press Run to see what your program prints, or why it stopped."},"toolId":"devtools.typescript-compiler","slug":"typescript-compiler","app":"devtools","category":"compilers","keywords":["typescript","online typescript","run typescript","ts compiler","tsc","typescript playground"],"name":"TypeScript Compiler","description":"Write and run TypeScript 7 code in your browser. Add input, press Run, and read the output or the exact error. Nothing to install.","input":{"kind":"text","label":"TypeScript code","language":"typescript","showLineNumbers":true,"maxLength":65536,"acceptFiles":{"accept":".ts,text/plain","maxBytes":65536},"secondary":{"label":"Standard input (stdin)","placeholder":"Optional. For example: Ada"}},"settings":{"fields":{"version":{"kind":"select","label":"Version","help":"Each run uses exactly this version.","default":"7","choices":[{"value":"7","label":"TypeScript 7.0"},{"value":"6","label":"TypeScript 6.0"},{"value":"5","label":"TypeScript 5.9"}]}}},"resultStats":"status-only","trigger":{"mode":"manual","actionLabel":"Run"},"capabilities":{"cancel":true,"copy":true,"download":true,"network":true},"workbenchMark":{"text":"TS","tone":"contrast"},"labels":{"result":"Result","empty":"Press Run to see what your program prints, or why it stopped.","ready":"Your program finished. The result explains what happened.","running":"Running your program…"},"content":{"seoTitle":"Online TypeScript Compiler — Run TypeScript 7 Code","howToUse":["The editor starts with a small TypeScript program that reads a name from standard input and greets it, so you can press Run straight away.","Write or paste your TypeScript code. Anything your program reads from the keyboard goes in the Standard input box before you run it.","Press Run or Ctrl/Cmd+Enter. The result starts with one sentence saying what happened, followed by the output, error output and exit code.","If something goes wrong the message names the cause, including the line of a compile error. Fix your code and run again. Your code is kept in this browser while you work."],"limitations":["You can run TypeScript 7.0, TypeScript 6.0, TypeScript 5.9. Pick one in the version menu above the editor; each run uses that exact release.","Each run is stopped after 5 seconds of running time (3 seconds of CPU time); compiling may take up to 15 seconds, and is limited to 256 MiB of memory and 64 KiB of output.","Source code and input are each limited to 64 KiB. Command-line arguments are not supported.","There is no network access, no way to install packages and no files that last between runs.","Input cannot be typed while the program runs. Put everything it will read in the Standard input box first.","If many people run code at once, the server may ask you to wait a few seconds. Your code is kept when that happens."],"faq":[{"q":"Is my code sent to a server, and is it saved?","a":"Yes, your code and input are sent to Canopy's execution server so it can run the program. It runs once in an isolated sandbox and is not stored. A draft stays in your own browser so a refresh does not lose your work."},{"q":"Which TypeScript versions can I use?","a":"TypeScript 7.0, TypeScript 6.0, TypeScript 5.9. TypeScript 7.0 is selected first; change it in the version menu above the editor. Each choice is an exact release (7.0.2, 6.0.3, 5.9.3), so results stay the same until the page is updated."},{"q":"Does TypeScript check my types before running?","a":"Yes. The code is compiled first, so type errors are shown as compile errors with the line number, and nothing runs until they are fixed."},{"q":"Why was my program stopped?","a":"Programs that run longer than the time limit, use too much memory or print too much are stopped to keep the service fair. The result tells you which limit was reached."}],"examples":[{"label":"Hello with input","text":"import { readFileSync } from \"fs\";\n\nconst name: string = readFileSync(0, \"utf8\").split(\"\\n\")[0].trim() || \"world\";\nconsole.log(`Hello, ${name}!`);\n","secondary":"Ada"}],"relatedToolIds":["devtools.java-compiler","devtools.c-compiler","devtools.cpp-compiler"]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.typescript-compiler' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"errors.out-of-range":"Unicode code point is out of range."},"toolId":"devtools.unicode-decoder","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["unicode","decode","escape","\\\\u","codepoint","javascript","emoji"],"name":"Unicode Decoder","description":"Decode JavaScript-style Unicode escape sequences.","layout":"stacked","input":{"kind":"text","language":"unicode","label":"Unicode escapes","placeholder":"Hello \\u{1F44B}"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Decode Unicode"},"capabilities":{"copy":true},"workbenchMark":{"text":"\\u>"},"labels":{"empty":"Enter text containing Unicode escapes to decode it.","ready":"Decoded text is ready.","running":"Decoding Unicode escapes…"},"content":{"howToUse":["Paste text containing JavaScript-style escapes — the form you get from a JSON string, a stack trace, or a log line that ASCII-escaped its output.","Decode. Both the four-hex-digit form (\\u00e9) and the braced code-point form (\\u{1F44B}) are supported.","Text without escapes passes through unchanged, so it is safe to run over a whole file."],"limitations":["Only \\u escapes are handled. \\x, \\0, \\n, and other backslash escapes are left alone.","Surrogate pairs written as two \\uD83D\\uDC4B escapes decode correctly because they are recombined by the string itself, but a lone unpaired surrogate stays lone.","A braced code point above U+10FFFF is rejected rather than silently clamped."],"faq":[{"q":"What is the difference between \\u00e9 and \\u{e9}?","a":"Nothing, for values below U+10000. The braced form is the only one that can express a code point above U+FFFF in a single escape."},{"q":"Why is my \\n still a backslash and an n?","a":"Only Unicode escapes are decoded. Other backslash escapes are left untouched on purpose."}],"examples":[{"label":"Emoji code point","text":"Hello \\\\u{1F44B}"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.unicode-decoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.unicode-encoder","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["unicode","escape","code point","utf-16","encode","ascii","emoji"],"name":"Unicode Encoder","description":"Encode text as Unicode code-point escapes.","layout":"stacked","input":{"kind":"text","label":"Text input","placeholder":"Hello 👋"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Encode Unicode"},"capabilities":{"copy":true},"workbenchMark":{"text":">\\u"},"labels":{"empty":"Enter text to encode non-ASCII characters as Unicode escapes.","ready":"Unicode-escaped text is ready.","running":"Encoding text as Unicode escapes…"},"content":{"howToUse":["Paste text containing accents, symbols, or emoji.","Encode. Printable ASCII passes through unchanged, so the result stays readable; only characters above U+007F are escaped.","Characters in the Basic Multilingual Plane become `\\uXXXX`. Anything above U+FFFF — most emoji — becomes the ES6 `\\u{...}` form.","Use this when a file, config, or protocol must be ASCII-only, or to make an invisible character visible while debugging."],"limitations":["The `\\u{...}` form for astral characters is ES6 JavaScript syntax. It is not valid in JSON, in older JavaScript, or in most other languages — those need a surrogate pair instead.","ASCII control characters (tab, newline, carriage return) are below U+007F and so pass through as literal characters rather than being escaped.","Escaping is unconditional above U+007F; there is no option to escape everything, or to escape only selected ranges.","Output is lowercase hexadecimal with no option to change the case."],"faq":[{"q":"Why do I get `\\u{1f44b}` instead of two `\\uXXXX` escapes?","a":"The character is above U+FFFF, so it is emitted as a single code point in the ES6 form rather than as a UTF-16 surrogate pair."},{"q":"Can I paste this into JSON?","a":"Only the `\\uXXXX` escapes. JSON does not accept `\\u{...}` — convert those to a surrogate pair first."},{"q":"Why is my plain English text unchanged?","a":"Everything in it is ASCII, and ASCII is left alone by design so the result stays readable."}],"examples":[{"label":"ASCII with emoji","text":"Hello 👋"},{"label":"Accented text","text":"café"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.unicode-encoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","errors.invalid-escape":"URL input contains an invalid percent escape.","recovery.invalid-escape":"Check for a stray % or an escape that is not followed by two hex digits."},"toolId":"devtools.url-decoder","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["url","decode","percent encoding","uri","query string","unescape"],"name":"URL Decoder","description":"Decode percent-encoded URL text.","layout":"stacked","input":{"kind":"text","language":"url-encoded","label":"Encoded input","placeholder":"hello%20smart%20tools%3Factive%3Dtrue"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Decode"},"capabilities":{"copy":true},"workbenchMark":{"text":"%>"},"labels":{"empty":"Enter percent-encoded text to decode it.","ready":"Decoded text is ready.","running":"Decoding percent-encoded text…"},"content":{"howToUse":["Paste the percent-encoded text — a whole URL, a single query parameter, or a redirect target pulled out of a log.","Decode. %20 becomes a space, %3F a question mark, and multi-byte UTF-8 sequences such as %F0%9F%91%8B are reassembled into the original character.","If the value was encoded twice, decode the output a second time."],"limitations":["This is decodeURIComponent, so it decodes reserved characters too. Running it over a full URL will turn an encoded ? or & inside a parameter into a real delimiter.","A + is left as a plus sign. Form-encoded bodies use + for a space and need that replaced first.","An incomplete or invalid escape such as %zz or a trailing % is rejected rather than passed through."],"faq":[{"q":"Why is my + still a plus?","a":"Percent-encoding and form encoding are different. application/x-www-form-urlencoded uses + for space; replace + with a space before decoding those."},{"q":"Why did decoding fail?","a":"The text contains a malformed escape — a % not followed by two hex digits, or a byte sequence that is not valid UTF-8."}],"examples":[{"label":"Encoded query","text":"hello%20smart%20tools%3Factive%3Dtrue"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.url-decoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.url-encoder","sharing":{"version":1},"app":"devtools","category":"encoding-decoding","keywords":["url","encode","percent encoding","escape","query string","uri","encodeuricomponent"],"name":"URL Encoder","description":"Percent-encode a URL or URL component.","layout":"stacked","input":{"kind":"text","label":"Text or URL","placeholder":"hello smart tools?active=true"},"settings":{"fields":{"component":{"kind":"toggle","label":"Encode component","help":"On encodes a single value — `?`, `&`, `=`, and `/` are escaped. Off encodes a whole URL and leaves that punctuation intact.","default":true}}},"trigger":{"mode":"manual","actionLabel":"Encode"},"capabilities":{"copy":true},"workbenchMark":{"text":">%"},"labels":{"empty":"Enter text or a URL to percent-encode it.","ready":"Percent-encoded value is ready.","running":"Percent-encoding input…"},"content":{"howToUse":["Leave the toggle on when you are encoding one value that will be dropped into a query string or a path segment — that is the common case.","Turn it off only when the input is already a complete URL and you want its structural characters left alone.","Encode, then paste the result into the URL. Do not encode an already-encoded value: `%20` would become `%2520`.","Non-ASCII text is encoded as UTF-8 percent triplets, which is what servers expect."],"limitations":["Component mode does not escape `!`, `'`, `(`, `)`, or `*`, which are legal in a URL but are sometimes rejected by strict OAuth 1.0 and RFC 3986 implementations. Encode those by hand if a signature check fails.","Whole-URL mode leaves `?`, `&`, `=`, `#`, `/`, and `:` untouched, so it cannot make an arbitrary value safe — it only fixes spaces and non-ASCII characters in a URL that is otherwise already well-formed.","The input is not validated as a URL. Junk in, percent-encoded junk out.","This does not encode `+` as a space. Form-style `application/x-www-form-urlencoded` encoding is a different scheme."],"faq":[{"q":"Which mode do I want?","a":"Component, almost always. Switch it off only when you are encoding an entire URL as one string."},{"q":"Why is my space `%20` and not `+`?","a":"`%20` is the URL percent-encoding of a space. `+` is the form-encoding convention and applies only to `application/x-www-form-urlencoded` bodies."},{"q":"Can I decode with this tool?","a":"No — use the URL Decoder for the reverse direction."}],"examples":[{"label":"Value with punctuation","text":"hello smart tools?active=true"},{"label":"Non-ASCII","text":"café & crème"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.url-encoder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.url-query-builder","sharing":{"version":1},"app":"devtools","category":"jwt-api-tools","keywords":["url","query string","querystring","parameters","encode","builder","search params"],"name":"URL Query Builder","description":"Append key/value query rows to a base URL.","layout":"side-by-side","inputSize":{"default":55,"min":35},"input":{"kind":"fields","label":"Base URL and query rows","fields":[{"channel":"text","label":"Base URL","placeholder":"https://example.com/search","required":true},{"channel":"secondary","label":"Query rows","placeholder":"q=smart tools\ntag=dev\ntag=web","multiline":true}]},"settings":{"fields":{"parameters":{"kind":"rows","label":"Query parameters","help":"Add a key and value for each parameter. Repeat a key to include multiple values.","default":[],"keyLabel":"Parameter key","valueLabel":"Value","pane":"input","span":"full"},"encodeValues":{"kind":"toggle","label":"Encode values","help":"Escape reserved characters in appended values.","default":true},"skipEmptyRows":{"kind":"toggle","label":"Skip empty rows","help":"Omit parameters whose value is blank.","default":false},"sortParameters":{"kind":"toggle","label":"Sort parameters","help":"Order parameters by key for stable output.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Build URL"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"?+="},"labels":{"empty":"Enter a base URL, then add any query parameters you need.","ready":"The URL is ready to copy or download.","running":"Building the URL…"},"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","sharedUrl.domainRequired":"Domain is required.","sharedUrl.domain":"Enter a valid domain name.","sharedUrl.absolute":"Enter an absolute http or https URL.","errors.invalid-query-row":"Each query row must use key=value format.","recovery.invalid-query-row":"Give every non-blank line a key, an equals sign, and a value.","workspace.queryParameters":"Query parameters","workspace.addParameter":"Add parameter","workspace.add":"Add","workspace.pasteMultiple":"Paste multiple","workspace.parametersToPaste":"Parameters to paste","workspace.cancel":"Cancel","workspace.key":"Key","workspace.value":"Value","workspace.lineNeedsParameter":"Each line needs a parameter key followed by = and its value.","workspace.emptyImport":"Enter at least one key=value line.","workspace.invalidImport":"Each line needs a parameter key followed by = and its value. For example: tag=dev.","workspace.correctImport":"Correct the pasted lines, or clear them to discard this import. Your other parameter rows will be kept.","workspace.addImportHelp":"One key=value pair per line. These will be added to the rows below.","workspace.applyParameters":"Apply parameters","workspace.addParameters":"Add parameters","workspace.parameterKey":"Parameter key {number, number}","workspace.parameterValue":"Value {number, number}","workspace.removeParameter":"Remove parameter {number, number}","workspace.keyExample":"e.g. tag","workspace.valueExample":"e.g. dev","workspace.urlDetails":"URL details"},"content":{"howToUse":["Put the absolute http or https base URL in the first field. Any query string already on it is kept.","Add parameters in the key/value rows, or use Paste multiple to import key=value lines. Values are trimmed and encoded by default; turn encoding off only when the destination expects raw values.","Repeat a key on several lines to send it more than once — `tag=dev` and `tag=web` produce `tag=dev&tag=web`."],"limitations":["Rows are appended, never replaced. A key already present in the base URL will appear twice.","The split is on the first `=` in the line, so a value may contain `=` but a key may not. A line with no `=`, or one starting with `=`, is rejected.","Encoding follows `URLSearchParams`: a space becomes `+`, not `%20`. Both are valid in a query string, but a server that decodes the query as a path segment will read `+` literally.","Blank lines are skipped. There is no comment syntax — every non-blank line must be a pair.","Only http and https URLs are accepted."],"faq":[{"q":"Why is my space encoded as `+` instead of `%20`?","a":"That is the `application/x-www-form-urlencoded` rule that `URLSearchParams` follows, and it is correct for a query string. Only switch to `%20` if a specific consumer requires it."},{"q":"How do I replace an existing parameter rather than add to it?","a":"Remove it from the base URL first. This tool only appends. The UTM Builder has an explicit replace mode if that is the shape you need."},{"q":"Are my values encoded safely?","a":"Yes. Ampersands, equals signs, and Unicode in a value are percent-encoded, so they cannot break out and create extra parameters."}],"examples":[{"label":"Search with a repeated tag","text":"https://example.com/search","secondary":"q=smart tools\ntag=dev\ntag=web"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.url-query-builder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"errors.inputRequired":"URL or query string is required.","errors.enterValue":"Enter a value and try again.","errors.queryInvalid":"URL or query string is invalid.","errors.queryRecovery":"Paste a complete URL, or just the part after the ? on its own.","result.parameter":"Parameter","result.value":"Value","result.empty":"No query parameters to display","result.emptyValues":"All parameter values are blank. Turn on Keep empty values to include them.","result.noParameters":"This input has no query parameters. Raw contains an empty JSON object."},"toolId":"devtools.url-query-parser","sharing":{"version":1},"app":"devtools","category":"jwt-api-tools","keywords":["url","query string","parameters","parse","json","utm","searchparams"],"name":"URL Query Parser","description":"Parse URL query parameters into JSON.","layout":"side-by-side","outputLanguage":"json","previewLayout":"table","resultView":{"default":"preview","previewLabel":"Preview"},"input":{"kind":"fields","label":"URL or Query String","fields":[{"channel":"text","label":"URL or query string","language":"url","placeholder":"https://example.com/search?q=smart+tools&tag=web","required":true,"multiline":true}]},"settings":{"fields":{"decodeValues":{"kind":"toggle","label":"Decode values","help":"Convert percent escapes and plus signs to text.","default":true},"coerceNumbers":{"kind":"toggle","label":"Coerce numbers","help":"Return numeric values as JSON numbers.","default":false},"keepEmptyValues":{"kind":"toggle","label":"Keep empty values","help":"Preserve parameters whose value is blank.","default":true}}},"trigger":{"mode":"manual","actionLabel":"Parse query"},"capabilities":{"copy":true},"workbenchMark":{"text":"?{}"},"labels":{"result":"Query parameters","empty":"Enter a URL or query string to inspect its parameters.","ready":"Query parameters are ready.","running":"Parsing query parameters…"},"content":{"howToUse":["Paste either a full URL or a bare query string. A leading `?` is optional.","Parse. Each parameter becomes a JSON key. Values are percent-decoded by default, with `+` read as a space.","A key that appears more than once becomes an array of its values in the order they appeared — that is how repeated filters and multi-select parameters arrive.","Use this to check what a redirect, a tracking link, or an OAuth callback actually carried."],"limitations":["Only the query string is read. The path, the fragment (`#...`), and any parameters hidden in the fragment are ignored.","Values stay strings unless number coercion is enabled. Booleans and null-like text are never coerced.","Nested conventions are not expanded: `a[b]=1` produces the literal key `a[b]`, and comma-separated values stay one string.","A key repeated once yields a string and repeated twice yields an array, so a consumer has to handle both shapes.","An empty query produces `{}`, which is a valid answer rather than an error."],"faq":[{"q":"Do I have to strip the URL down to the query first?","a":"No. Paste the whole URL — anything with a scheme or a `?` is parsed as a URL, and everything else is treated as a bare query string."},{"q":"Why is a repeated key an array?","a":"Because the query genuinely carried several values for it. Dropping all but one would lose data."},{"q":"Where did my `#section` parameters go?","a":"The fragment is never sent to a server and is not part of the query, so it is not parsed. Move those parameters before the `#` if you need them."}],"examples":[{"label":"Repeated parameter","text":"https://example.com/search?q=smart+tools&tag=dev&tag=web"},{"label":"Bare query string","text":"?utm_source=newsletter&utm_medium=email"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.url-query-parser' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.utm-builder","sharing":{"version":1},"app":"devtools","category":"jwt-api-tools","keywords":["utm","campaign","url builder","analytics","tracking","google analytics","marketing"],"name":"UTM Builder","description":"Build a URL with UTM campaign parameters.","layout":"side-by-side","inputSize":{"default":55,"min":35},"input":{"kind":"none"},"settings":{"fields":{"url":{"kind":"text","label":"Destination URL","help":"Must be an absolute http or https URL. Any existing query string is kept unless you replace it below.","default":"https://example.com","pane":"input","span":"full"},"source":{"kind":"text","label":"Campaign source","help":"Referrer, e.g. google or newsletter.","default":"newsletter","pane":"input"},"medium":{"kind":"text","label":"Campaign medium","help":"Channel, e.g. email, social, or cpc.","default":"email","pane":"input"},"campaign":{"kind":"text","label":"Campaign name","placeholder":"e.g. spring_launch","default":"launch","pane":"input","span":"full"},"term":{"kind":"text","label":"Campaign term (optional)","placeholder":"Paid-search keyword","default":"","pane":"input"},"content":{"kind":"text","label":"Campaign content (optional)","placeholder":"Link or creative, e.g. hero_cta","default":"","pane":"input"},"parameters":{"kind":"rows","label":"Additional parameters","help":"Use full keys, e.g. utm_id or utm_source_platform.","default":[],"keyLabel":"Parameter key","valueLabel":"Parameter value","pane":"input","span":"full"},"normalization":{"kind":"select","label":"Value normalization","help":"Analytics tools treat Email and email as different campaigns. Lowercasing avoids splitting a report in two.","default":"preserve","choices":[{"label":"Preserve entered case","value":"preserve"},{"label":"Lowercase values","value":"lowercase"}]},"existingQuery":{"kind":"select","label":"Existing query parameters","help":"What to do with a query string already on the destination URL.","default":"merge","choices":[{"label":"Keep and merge","value":"merge"},{"label":"Replace existing query","value":"replace"}]}}},"trigger":{"mode":"manual","actionLabel":"Build campaign URL"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"UTM","tone":"accent"},"labels":{"empty":"Complete the destination and required campaign fields.","ready":"Campaign URL is ready.","running":"Building campaign URL…"},"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","sharedUrl.domainRequired":"Domain is required.","sharedUrl.domain":"Enter a valid domain name.","sharedUrl.absolute":"Enter an absolute http or https URL.","errors.parameter-required":"{parameter} is required.","recovery.parameter-required":"Fill in campaign source, medium, and name — a partially tagged link reports as direct traffic.","errors.extra-missing":"Enter both a key and value, or remove this row.","errors.extra-duplicate":"This key is already used in another extra parameter. Keep one row per key.","errors.extra-standard":"Use the {parameter, select, utm_source {Campaign source} utm_medium {Campaign medium} utm_campaign {Campaign name} utm_term {Campaign term} utm_content {Campaign content} other {campaign}} field instead of an extra {parameter} parameter.","recovery.invalid-extra-parameter":"Edit or remove the extra parameter row, then build the URL again.","workspace.campaignDetails":"Campaign details","workspace.addParameter":"Add parameter","workspace.parameterKey":"Parameter key","workspace.keyExample":"e.g. utm_id","workspace.parameter":"parameter","workspace.parameterValue":"Parameter value","workspace.valueExample":"e.g. spring_2026","workspace.missingParameter":"Enter both a key and value, or remove this row.","workspace.duplicateParameter":"This key is already used in another extra parameter. Keep one row per key.","workspace.standardParameter":"Use the {field} field instead of an extra {key} parameter."},"content":{"howToUse":["Paste the destination URL with its scheme. A bare domain is rejected — analytics links must be absolute.","Fill in source, medium, and campaign. All three are required; the build fails rather than emitting a half-tagged link that reports as direct traffic.","Add term or content only if you need them. Blank fields are omitted from the URL instead of being written as empty parameters.","Use Add parameter for extra UTM or custom tracking keys. Enter the full key and value; remove any row you no longer need.","Choose lowercase normalization if your reports are being split by capitalisation, then build and copy the tagged URL."],"limitations":["Additional parameters are included in the URL, but your analytics platform determines which keys appear in reports.","Values are URL-encoded but not otherwise validated — a typo in a source name produces a valid URL that reports under the wrong name.","Trailing and leading whitespace is trimmed from each value; internal spaces are preserved and percent-encoded.","The tool does not shorten the URL, check that the destination resolves, or verify that your analytics property is receiving the parameters."],"faq":[{"q":"What happens to a query string already on the URL?","a":"By default it is kept and the UTM parameters are merged in. Switch to Replace existing query to drop it first."},{"q":"Why are source, medium, and campaign mandatory?","a":"Most analytics tools discard a partially tagged link and attribute the visit to direct traffic, which is worse than no tag at all."},{"q":"Should I lowercase my values?","a":"Yes, if more than one person builds links. Analytics tools are case-sensitive, so Email and email become two separate rows in the same report."},{"q":"Does a UTM-tagged link expose anything private?","a":"The parameters are visible in the address bar and in any referrer header, so never put a customer name, email address, or token in one."}],"examples":[{"label":"Paid social launch","text":"","settings":{"url":"https://acme.example/pricing?ref=homepage","source":"linkedin","medium":"paid_social","campaign":"spring_launch","content":"hero_cta","normalization":"lowercase","existingQuery":"merge"}}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.utm-builder' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedCrypto.unavailable":"Secure browser cryptography is unavailable.","sharedCrypto.range":"Random range is too large.","sharedCrypto.alphabet":"Choose at least one character group.","sharedEncoding.base64":"Base64 input is invalid.","sharedEncoding.utf8":"Base64 does not contain valid UTF-8 text.","errors.missing-name":"Enter a name to generate this UUID.","recovery.missing-name":"Enter a name and choose its namespace.","errors.invalid-namespace":"Enter a valid namespace UUID.","recovery.invalid-namespace":"Choose a preset namespace or enter a complete UUID with hyphens.","errors.unsupported-version":"Choose a supported UUID version.","errors.invalid-count":"Enter a whole number from 1 to 100 for how many UUIDs to generate."},"toolId":"devtools.uuid-generator","app":"devtools","category":"hashing-crypto","keywords":["uuid","guid","uuid v1","uuid v3","uuid v4","uuid v5","uuid v6","uuid v7","identifier"],"name":"UUID Generator","description":"Generate UUID v1, v3, v4, v5, v6, and v7 identifiers.","input":{"kind":"none"},"settings":{"fields":{"version":{"kind":"select","label":"UUID version","help":"v3 and v5 use a namespace and name. The other versions generate new IDs.","default":"v4","choices":[{"label":"UUID v1 — timestamp","value":"v1"},{"label":"UUID v3 — name-based (MD5)","value":"v3"},{"label":"UUID v4 — random","value":"v4"},{"label":"UUID v5 — name-based (SHA-1)","value":"v5"},{"label":"UUID v6 — reordered timestamp","value":"v6"},{"label":"UUID v7 — time-ordered","value":"v7"}]},"namespace":{"kind":"select","label":"Namespace","help":"Names in different namespaces produce different UUIDs.","default":"6ba7b810-9dad-11d1-80b4-00c04fd430c8","choices":[{"label":"DNS","value":"6ba7b810-9dad-11d1-80b4-00c04fd430c8"},{"label":"URL","value":"6ba7b811-9dad-11d1-80b4-00c04fd430c8"},{"label":"OID","value":"6ba7b812-9dad-11d1-80b4-00c04fd430c8"},{"label":"X.500","value":"6ba7b814-9dad-11d1-80b4-00c04fd430c8"},{"label":"Custom","value":"custom"}]},"customNamespace":{"kind":"text","label":"Namespace UUID","placeholder":"6ba7b810-9dad-11d1-80b4-00c04fd430c8","default":""},"name":{"kind":"text","label":"Name","help":"One UUID per name. Case and whitespace are preserved.","default":"example.com"},"count":{"kind":"number","label":"How many","default":5,"min":1,"max":100},"hyphens":{"kind":"toggle","label":"Hyphens","help":"Off produces the 32-character compact form.","default":true},"upper":{"kind":"toggle","label":"Uppercase","help":"Use uppercase letters in the generated UUIDs.","default":false}}},"trigger":{"mode":"manual","actionLabel":"Generate"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"UUID","tone":"accent"},"labels":{"empty":"Choose a version and generate.","ready":"UUIDs are ready.","running":"Generating UUIDs…"},"content":{"howToUse":["Choose v4 for random IDs or v7 for time-ordered IDs. v1 and v6 use a timestamp and a randomly generated node identifier.","For v3 or v5, select a namespace and enter a name. The same version, namespace, and exact name always produce the same UUID.","For v1, v4, v6, and v7, choose up to 100 IDs per run. Hyphens and uppercase apply to every version.","Generate, then copy or download. All values are computed in this browser tab."],"limitations":["v2 requires legacy DCE Security identity data. v8 has an application-defined layout and no universal generation algorithm; neither is offered here.","v1, v6, and v7 include creation time. v1 and v6 use a random node identifier, not your device's MAC address.","UUIDs are identifiers, not secrets. Do not use them as passwords, API keys, or bearer credentials.","v3 and v5 are deterministic and return one UUID per name. Generating again with the same inputs intentionally returns the same value.","Removing the hyphens produces a 32-character string that most UUID parsers still accept, but some strict ones do not."],"faq":[{"q":"v4 or v7?","a":"v7 if the value is a database primary key — time ordering keeps B-tree inserts local instead of scattering them. v4 anywhere the creation time must not be inferable."},{"q":"Why are v2 and v8 missing?","a":"v2 is a legacy DCE Security format. v8 reserves space for custom application formats, so it needs a specific scheme rather than a generic generator."},{"q":"When should I use v3 or v5?","a":"Use a name-based UUID when the same namespace and exact name should always map to the same identifier. Use the version required by the system you integrate with."},{"q":"Can two of these collide?","a":"Accidental collisions are very unlikely for properly generated random UUIDs. v3 and v5 intentionally repeat when given the same namespace and name."},{"q":"Are these generated on a server?","a":"No. Randomness and name-based hashing run locally in this browser tab; names and UUIDs are never transmitted."},{"q":"Is v7 a real standard?","a":"Yes — RFC 9562 (2024) standardised versions 6, 7, and 8. v7 is the recommended time-ordered format."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.uuid-generator' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"media.watermark-pdf","app":"media","category":"pdf-optimization","keywords":["pdf","watermark","stamp","draft","confidential","overlay","logo","opacity"],"name":"Watermark PDF","description":"Add a text or image watermark to PDF pages.","layout":"stacked","input":{"kind":"files","label":"PDF document, plus a JPG or PNG for an image watermark","accept":"application/pdf,image/jpeg,image/png","multiple":true,"engine":"pdf","maxFiles":2,"maxBytes":52428800,"maxTotalBytes":52428800,"inspect":true},"settings":{"fields":{"watermarkKind":{"kind":"select","label":"Watermark","help":"For an image watermark, choose a JPG or PNG in these settings.","default":"text","choices":[{"label":"Text","value":"text"},{"label":"JPG or PNG image","value":"image"}]},"watermarkText":{"kind":"text","label":"Text","help":"Must fit the standard PDF font. Use an image watermark for other scripts or unsupported characters.","default":"DRAFT","visibleWhen":{"key":"watermarkKind","equals":"text"}},"pages":{"kind":"pages","presets":true,"label":"Pages","help":"Choose which pages receive the watermark, or select pages directly in the preview.","default":"all"},"opacity":{"kind":"slider","label":"Opacity","default":25,"min":5,"max":100,"suffix":"%"},"watermarkSize":{"kind":"number","label":"Size","help":"Font size in points for a text watermark; percentage of the page width for an image.","default":48,"min":1,"suffix":"pt / %"},"watermarkRotation":{"kind":"number","label":"Rotation","default":-30,"min":-180,"max":180,"leadingIcon":"rotate-cw"},"position":{"kind":"position","label":"Position","help":"Anchor point on the page, with a 24-point margin from the edges.","default":"bottom-center"}}},"trigger":{"mode":"manual","actionLabel":"Apply watermark"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"WM","tone":"accent"},"labels":{"empty":"Add a PDF to configure its watermark.","ready":"Your watermarked PDF is ready to download.","running":"Applying watermark…"},"messages":{"progress.savingPdf":"Saving PDF","readiness.chooseWatermark":"Choose a JPG or PNG watermark image.","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.validateImageSelection.noFiles":"Choose at least one image.","media.validateImageSelection.tooManyFiles":"Choose no more than {limit, number} images.","media.validateImageSelection.invalidSize":"A selected file has an invalid size.","media.validateImageSelection.fileTooLarge":"Each image must be 25 MiB or smaller.","media.validateImageSelection.totalTooLarge":"The selected images must total 100 MiB or less.","media.validateDecodedImageDimensions.invalidDimensions":"The image dimensions are invalid.","media.validateDecodedImageDimensions.tooManyPixels":"The decoded image must be 100 megapixels or less.","media.image.unsupportedType":"Choose a supported image file.","media.image.imageSequence":"Multi-image HEIC sequences are not supported.","media.progress.renderingPdfPage":"Rendering PDF page","media.progress.pageComplete":"Page complete","media.validatePdfSelection.noFiles":"Choose at least one PDF.","media.validatePdfSelection.invalidSize":"A selected file has an invalid size.","media.validatePdfSelection.fileTooLarge":"Each PDF must be 100 MiB or smaller.","media.validatePdfSelection.tooManyFiles":"Merge no more than {limit, number} PDFs at once.","media.validatePdfSelection.totalTooLarge":"PDFs selected for merging must total 50 MiB or less.","media.validatePdfSelection.invalidPageCount":"The PDF page count is invalid.","media.validatePdfSelection.tooManyPages":"This operation supports at most {limit, number} pages.","media.parsePageRange.emptyRange":"Enter one or more page numbers.","media.parsePageRange.invalidRange":"Use page numbers such as 1-3,5,8.","media.parsePageRange.reversedRange":"Page ranges must run from lower to higher pages.","media.parsePageRange.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.parsePageRange.duplicatePage":"Page {page, number} is selected more than once.","media.pdf.encryptedPdf":"Encrypted or password-protected PDFs are not supported.","media.pdf.malformedPdf":"The PDF is malformed or unsupported.","media.pdf.emptyRange":"Choose at least one page.","media.pdf.pageOutOfRange":"Choose pages between 1 and {count, number}.","media.pdf.duplicatePage":"Each selected page may appear only once.","media.pdf.invalidPageSize":"Choose valid custom PDF page dimensions.","media.pdf.fileReadFailed":"The PDF could not be read from this device.","media.recovery.pdf.fileReadFailed":"Choose the file again and keep it available until processing finishes.","media.pdf.tooManyPixels":"A rendered PDF page exceeds 100 megapixels.","media.pdf.invalidPreviewSize":"The requested PDF preview size is invalid.","media.pdf.invalidPageSelection":"A requested PDF preview page does not exist.","media.pdf.tooManyPages":"Structural PDF jobs support at most {limit, number} pages.","media.pdf.qpdfFailed":"The qpdf job identifier is invalid.","media.pdf.qpdfFailed2":"qpdf could not rewrite this document. The original file was not changed.","media.pdf.qpdfUnavailable":"Preserve Document compression requires a cross-origin-isolated browser. No fallback was applied.","media.pdf.qpdfUnavailable2":"Preserve Document compression is unavailable in this browser. No fallback was applied.","errors.noFiles":"Choose a PDF to watermark.","errors.emptyWatermark":"Enter watermark text.","errors.unsupportedText":"This text cannot be encoded by the standard PDF font. Use an image watermark for this text.","errors.missingWatermark":"Choose a watermark image.","workspace.watermarkSettings":"Watermark settings","workspace.jpgOrPng25MibMaxPdf":"JPG or PNG · 25 MiB max · PDF and image combined: 50 MiB max","workspace.removeImage":"Remove image","workspace.fileNotAdded":"File not added","workspace.noPages":"No pages match this selection. Choose pages in your PDF.","workspace.approximateWatermark":"Approximate watermark","workspace.pdfDocument":"PDF document","workspace.chooseImage":"Choose a JPG or PNG watermark image.","workspace.enterText":"Enter watermark text.","workspace.planTitle":"{count, plural, one {# page will receive a watermark} other {# pages will receive a watermark}}","workspace.planDetail":"Placement is approximate. Apply the watermark and check the downloaded PDF. Your original stays unchanged.","workspace.replaceImage":"Replace watermark image","workspace.watermarkImage":"Watermark image","workspace.validPages":"Choose page numbers from 1 to {count, number}, or enter all."},"content":{"howToUse":["Add the PDF you want to stamp. It is processed in your browser — nothing is uploaded.","Choose a text or image watermark. For an image, choose a JPG or PNG in the watermark settings.","Set the pages, opacity, size, rotation, and anchor position. Size is a font size in points for text, and a percentage of the page width for an image.","Apply the watermark and download. Check a couple of pages before you distribute the file."],"limitations":["A watermark is decoration, not protection. Anyone can remove it with the same class of tool, so never rely on it to secure a document.","Text watermarks use the standard Helvetica font, which covers Latin characters only. Text it cannot encode is rejected — use an image watermark for other scripts.","Image watermarks accept JPG and PNG only, and a rotated JPEG is re-encoded once so its EXIF orientation is applied.","The watermark is drawn on top of existing content and may obscure it. Lower the opacity or move the anchor if that matters.","Structural jobs are capped at 500 pages, and the PDF must be 50 MiB or smaller."],"faq":[{"q":"Where do I add an image watermark?","a":"Choose JPG or PNG image in the watermark settings, then choose your image. The PDF remains in the main preview while you adjust its watermark."},{"q":"Can someone remove my watermark?","a":"Yes. It is ordinary page content, so treat it as a visual label — a 'DRAFT' or 'CONFIDENTIAL' marker — and not as a security control."},{"q":"Why was my watermark text rejected?","a":"The standard PDF font could not encode it. That happens with non-Latin scripts and some symbols. Render the text as a PNG and use an image watermark instead."},{"q":"How big will my image watermark be?","a":"Size is a percentage of the page width, and the height follows the image's own aspect ratio, so it scales sensibly across mixed page sizes."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.watermark-pdf' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"media.webp-to-jpg","app":"media","category":"image-conversion","keywords":["webp","jpg","jpeg","convert","image","compatibility","background","flatten"],"name":"WebP to JPG","description":"Convert static WebP images to JPG.","input":{"kind":"files","label":"Add WebP images","dropzoneDescription":"WebP · up to 50 files · 25 MB each · processed on this device","accept":"image/webp,.webp","multiple":true,"engine":"image","maxFiles":50,"maxBytes":26214400,"maxTotalBytes":104857600},"settings":{"fields":{"quality":{"kind":"slider","label":"Quality","help":"JPG is lossy. 80 is a good default; above 90 the file grows fast for little visible gain.","default":80,"min":30,"max":100,"suffix":"%"},"background":{"kind":"color","label":"Background","help":"JPG has no transparency, so any transparent pixel in the WebP is flattened onto this colour.","default":"#ffffff"}}},"trigger":{"mode":"manual","actionLabel":"Convert to JPG"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"W2JP"},"labels":{"empty":"Drop up to 50 static WebP images (25 MiB each) to convert to JPG.","ready":"The WebP images and JPG settings are ready.","running":"Converting WebP images…"},"messages":{"progress.decodingImage":"Decoding image","progress.encodingImage":"Encoding image","progress.imageComplete":"Image complete","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.validateImageSelection.noFiles":"Choose at least one image.","media.validateImageSelection.tooManyFiles":"Choose no more than {limit, number} images.","media.validateImageSelection.invalidSize":"A selected file has an invalid size.","media.validateImageSelection.fileTooLarge":"Each image must be 25 MiB or smaller.","media.validateImageSelection.totalTooLarge":"The selected images must total 100 MiB or less.","media.validateDecodedImageDimensions.invalidDimensions":"The image dimensions are invalid.","media.validateDecodedImageDimensions.tooManyPixels":"The decoded image must be 100 megapixels or less.","media.image.unsupportedType":"Choose a supported image file.","media.image.imageSequence":"Multi-image HEIC sequences are not supported.","conversion.action":"Convert to {format}","conversion.running":"Converting images to {format}…","conversion.qualityLabel":"Quality","conversion.qualityHelp":"{format, select, jpg {JPG is lossy. 80 is a good default; above 90 the file grows fast for little visible gain.} other {WebP is encoded lossily here. Raise quality for fine details and sharp text; lower it for smaller files.}}","conversion.backgroundLabel":"Background","conversion.backgroundHelp":"JPG has no transparency, so transparent pixels are flattened onto this colour."},"content":{"howToUse":["Add one or more static WebP files. Decoding and JPG encoding both happen in your browser, so nothing is uploaded.","Pick a quality. 80 suits photographs; raise it when the WebP holds fine text or gradients that JPG would smear.","Choose the background colour. WebP supports transparency and JPG does not, so any transparent area is composited onto this colour.","Run the conversion and download the JPGs — the format to reach for when an editor, printer, or upload form refuses WebP."],"limitations":["Animated WebP files are rejected. Only single-frame images convert; extract the frame you want elsewhere first.","Transparency is lost permanently. Set the background to match wherever the image will sit, or keep the WebP if you still need alpha.","Both formats are lossy, so this conversion compounds the loss. Convert from the most original file you have rather than a re-saved copy.","Metadata is dropped: decoding to raw pixels discards EXIF, GPS, and colour-profile data.","Each image must be 25 MiB or smaller, up to 50 files per run, and no more than 100 megapixels once decoded."],"faq":[{"q":"Why was my WebP rejected?","a":"It is almost certainly animated. Animated WebP is detected from the file's ANIM/ANMF chunks and refused, because a JPG can only hold one frame."},{"q":"Will the JPG be bigger than the WebP?","a":"Usually yes. WebP compresses more efficiently at equal quality, so expect the JPG to grow — that is the cost of the wider compatibility."},{"q":"Why is there a white box where my image was transparent?","a":"That is the background colour. JPG cannot store an alpha channel, so transparent pixels must be flattened onto something; change the setting to match your page."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.webp-to-jpg' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"media.webp-to-png","app":"media","category":"image-conversion","keywords":["webp","png","convert","image","lossless","transparency","compatibility","batch"],"name":"WebP to PNG","description":"Convert static WebP images to PNG.","input":{"kind":"files","label":"Add WebP images","dropzoneDescription":"WebP · up to 50 files · 25 MB each · processed on this device","accept":"image/webp,.webp","multiple":true,"engine":"image","maxFiles":50,"maxBytes":26214400,"maxTotalBytes":104857600},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Convert to PNG"},"capabilities":{"cancel":true,"download":true,"progress":true},"workbenchMark":{"text":"W2PN"},"labels":{"empty":"Drop up to 50 static WebP images (25 MiB each) to convert to PNG.","ready":"The WebP images are ready to convert to PNG.","running":"Converting WebP images…"},"messages":{"progress.decodingImage":"Decoding image","progress.encodingImage":"Encoding image","progress.imageComplete":"Image complete","media.image.canvasUnavailable":"This browser cannot create an image canvas.","media.validateMediaSignature.invalidSignature":"The file does not have a supported signature.","media.validateMediaSignature.unsupportedType":"This file type is not supported by this tool.","media.validateMediaSignature.mimeMismatch":"The file contents do not match its reported type.","media.validateMediaSignature.animatedImage":"Animated WebP files are not supported. Choose a static image.","media.validateMediaSignature.imageSequence":"Multi-image HEIC sequences are not supported. Choose a single image.","media.validateImageSelection.noFiles":"Choose at least one image.","media.validateImageSelection.tooManyFiles":"Choose no more than {limit, number} images.","media.validateImageSelection.invalidSize":"A selected file has an invalid size.","media.validateImageSelection.fileTooLarge":"Each image must be 25 MiB or smaller.","media.validateImageSelection.totalTooLarge":"The selected images must total 100 MiB or less.","media.validateDecodedImageDimensions.invalidDimensions":"The image dimensions are invalid.","media.validateDecodedImageDimensions.tooManyPixels":"The decoded image must be 100 megapixels or less.","media.image.unsupportedType":"Choose a supported image file.","media.image.imageSequence":"Multi-image HEIC sequences are not supported.","conversion.action":"Convert to {format}","conversion.running":"Converting images to {format}…","conversion.qualityLabel":"Quality","conversion.qualityHelp":"{format, select, jpg {JPG is lossy. 80 is a good default; above 90 the file grows fast for little visible gain.} other {WebP is encoded lossily here. Raise quality for fine details and sharp text; lower it for smaller files.}}","conversion.backgroundLabel":"Background","conversion.backgroundHelp":"JPG has no transparency, so transparent pixels are flattened onto this colour."},"content":{"howToUse":["Add one or more static WebP files. Everything is decoded and re-encoded in your browser, so nothing is uploaded.","There is nothing to configure: PNG is lossless and the original pixel dimensions are kept, so the output matches the decoded WebP exactly.","Run the conversion and download the PNGs. Transparency is preserved, because both formats carry a full alpha channel.","Reach for this when something in your pipeline — an older editor, a print workflow, an upload form — will not accept WebP."],"limitations":["Animated WebP files are rejected. PNG holds a single frame, so only static images convert.","The PNG will normally be several times larger than the WebP. Lossless storage of an image that was lossily compressed keeps the artefacts and adds bytes.","Converting to PNG cannot undo the WebP encoder's losses; it only stops further quality being discarded.","Decoding to raw pixels drops EXIF, GPS, and colour-profile metadata.","Each image must be 25 MiB or smaller, up to 50 files per run, and no more than 100 megapixels once decoded."],"faq":[{"q":"Does transparency survive?","a":"Yes. Both WebP and PNG store per-pixel alpha, so transparent and semi-transparent areas come across unchanged."},{"q":"Why is the PNG so much larger?","a":"PNG is lossless: it records every pixel the WebP decoder produced, including its compression artefacts. Photographic content compresses poorly this way."},{"q":"Can I convert an animated WebP?","a":"Not here. The animation is detected and the file refused rather than silently exporting only the first frame."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'media.webp-to-png' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.whitespace-remover","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["whitespace","trim","spaces","blank lines","indentation","clean text"],"name":"Whitespace Remover","description":"Remove selected kinds of whitespace.","layout":"side-by-side","input":{"kind":"text","label":"Text input","placeholder":"Hello    world\n\nNext line."},"settings":{"fields":{"mode":{"kind":"select","label":"Mode","help":"Which whitespace to strip. 'Extra spaces' is the safe default; 'All whitespace' also removes newlines.","default":"extra","choices":[{"label":"Extra spaces","value":"extra"},{"label":"All whitespace","value":"all"},{"label":"Leading","value":"leading"},{"label":"Trailing","value":"trailing"},{"label":"Blank lines","value":"blank"}]}}},"trigger":{"mode":"manual","actionLabel":"Remove whitespace"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"SP-"},"labels":{"empty":"Enter text to remove unwanted whitespace.","ready":"Cleaned text is ready.","running":"Removing whitespace…"},"content":{"howToUse":["Paste the text, then pick the narrowest mode that solves your problem.","'Extra spaces' collapses runs of spaces and tabs to one and trims each line — the usual choice for text pasted out of a PDF or an email.","'Leading' and 'Trailing' strip only one side of every line; 'Blank lines' removes empty lines; 'All whitespace' removes every space, tab, and newline and leaves one unbroken string."],"limitations":["'All whitespace' also removes newlines, so it destroys the line structure. It is for building a single token, not for tidying prose.","'Extra spaces' collapses only spaces and tabs; it does not collapse repeated blank lines.","'Leading' and 'Trailing' match any whitespace, newlines included, so on a run of blank lines they can join lines together.","Zero-width and non-breaking characters that look like spaces are matched by the Unicode-aware modes ('All') but not by the space-and-tab collapse in 'Extra spaces'.","The tool never re-wraps or re-indents; it only removes."],"faq":[{"q":"Which mode should I use for text copied from a PDF?","a":"'Extra spaces'. It collapses the double and triple spaces that PDF extraction inserts while keeping the line breaks."},{"q":"How do I remove indentation but keep the lines?","a":"'Leading'. It strips whitespace from the start of every line and leaves the line breaks in place."},{"q":"Does it touch non-breaking spaces?","a":"'All whitespace' does, because it matches Unicode whitespace. 'Extra spaces' matches only the ASCII space and tab, so a non-breaking space survives it."}],"examples":[{"label":"Padded lines","text":"  Hello    smart tools  \n\n  Next line.  "}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.whitespace-remover' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"toolId":"devtools.word-counter","sharing":{"version":1},"app":"devtools","category":"text-tools","keywords":["word count","character count","sentences","paragraphs","reading time","text statistics","seo"],"name":"Word Counter","description":"Count words, characters, sentences, paragraphs, lines, and reading time.","layout":"stacked","input":{"kind":"text","label":"Text","placeholder":"Smart tools make repeated work faster."},"settings":{"fields":{"countHyphenated":{"kind":"toggle","label":"Count hyphenated words as one word","help":"Off splits `state-of-the-art` into four words, which matches how some editorial word limits are counted.","default":true},"ignoreNumbers":{"kind":"toggle","label":"Ignore standalone numbers","help":"Skips tokens that are purely numeric, such as `2026` or `1,500`.","default":false},"excludeEmails":{"kind":"toggle","label":"Exclude email-like strings","help":"Skips tokens shaped like an address so a contact block does not inflate the count.","default":true},"estimateReadingTime":{"kind":"toggle","label":"Estimate reading time","help":"Shows an estimate based on 200 words per minute, accounting for long unbroken text.","default":true}}},"trigger":{"mode":"live","debounceMs":200},"capabilities":{"copy":true},"workbenchMark":{"text":"W#"},"labels":{"empty":"Enter text to count its words and characters.","ready":"Text statistics are ready.","running":"Counting words and characters…"},"content":{"howToUse":["Paste or type the text. Every count updates as you type — there is nothing to submit.","Adjust the counting toggles to match the convention you are held to. Hyphenation is the one that most often explains a mismatch with another tool.","Read `Characters` for limits that count code points (most CMS fields) and `Characters without spaces` for editorial limits.","Reading time assumes 200 words per minute and treats every five non-space characters as at least one word. Short text is shown in seconds; longer text is rounded up to whole minutes."],"limitations":["Words are whitespace-delimited tokens. Languages that do not separate words with spaces — Chinese, Japanese, Thai — will not be counted meaningfully.","Sentence detection is punctuation-based, so `Dr. Ada` and `3.5` each count as a sentence break.","Paragraphs are runs of text separated by one or more blank lines. A single-spaced document is one paragraph.","`Characters` counts Unicode code points, so an emoji built from several code points counts as more than one character. Byte length is a fourth number again."],"faq":[{"q":"Why does my word count differ from Word or Google Docs?","a":"Almost always hyphenation or email/number handling. Match the three toggles to the other tool's convention and the numbers converge."},{"q":"How is reading time calculated?","a":"It uses 200 words per minute and a five-character word equivalent for long unbroken text. Short text is shown in seconds and longer text in rounded-up whole minutes."},{"q":"Is my text sent anywhere?","a":"Counting happens in this browser tab without uploading the text. Share links include the text and settings in the URL, so anyone with the link can read them."}],"examples":[{"label":"Two sentences","text":"Smart tools make repeated work faster. They should remain easy to trust."},{"label":"Hyphenation and an address","text":"State-of-the-art tooling. Reach us at hello@example.com for 2026 pricing."}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.word-counter' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","errors.xml-invalid-entity":"XML contains an unsupported entity or invalid character reference.","errors.xml-unbalanced":"XML closing tags do not match.","recovery.xml-unbalanced":"Check that every opening tag has a matching closing tag in the same order.","errors.xml-invalid-tag":"XML contains an invalid tag.","errors.xml-multiple-roots":"XML must have one root element.","errors.xml-incomplete":"XML is incomplete or empty.","recovery.xml-incomplete":"Paste the whole document, including its closing root tag."},"toolId":"devtools.xml-to-json","sharing":{"version":1},"app":"devtools","category":"json-tools","keywords":["xml","json","convert","parse","attributes","soap","rss"],"name":"XML to JSON","description":"Convert XML elements and attributes to JSON.","outputLanguage":"json","input":{"kind":"text","language":"xml","label":"XML input","placeholder":"<user id=\"1\"><name>Ada</name></user>"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Convert to JSON"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"X>J"},"labels":{"empty":"Enter XML to convert it to JSON.","ready":"Converted JSON is ready.","running":"Converting XML to JSON…"},"content":{"howToUse":["Paste a single well-formed XML document with exactly one root element.","Convert. Attributes become keys prefixed with @, element text becomes #text when the element also has children or attributes, and repeated sibling names become arrays.","Copy the formatted JSON, or fix the reported error if the tags do not balance."],"limitations":["This is a deliberately small parser, not a full XML processor. Namespaces are kept as literal prefixes. Predefined entities, numeric character references, and CDATA are supported; custom entities are not expanded.","Whitespace-only text is trimmed away, so mixed content (text interleaved with child elements) loses its ordering.","An element that appears once becomes an object; the same element appearing twice becomes an array. Consumers must handle both shapes.","Numbers and booleans stay strings — XML has no types to infer them from."],"faq":[{"q":"Why is my attribute prefixed with @?","a":"So an attribute named id cannot collide with a child element named id. The convention matches most XML-to-JSON mappings."},{"q":"Why did a single-element list become an object?","a":"There is no way to tell a one-item list from a single value in XML without a schema. Normalise with Array.isArray on the consuming side."}],"examples":[{"label":"Element with an attribute","text":"<user id=\"1\"><name>Ada</name><active>true</active></user>"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.xml-to-json' AND spec IS NULL;
UPDATE managed_tools SET spec = $spec${"messages":{"sharedInput.required":"This input is required.","sharedInput.recovery":"Enter a value and try again.","errors.yaml-invalid":"YAML is invalid: {detail}","errors.yaml-invalid-unknown":"YAML is invalid: unknown error","recovery.yaml-invalid":"Check the indentation — YAML does not allow tab characters for indentation."},"toolId":"devtools.yaml-to-json","app":"devtools","category":"json-tools","keywords":["yaml","json","convert","yml","config","parser"],"name":"YAML to JSON","description":"Convert YAML documents to formatted JSON.","outputLanguage":"json","input":{"kind":"text","language":"yaml","label":"YAML input","placeholder":"name: Ada\nactive: true"},"settings":{"fields":{}},"trigger":{"mode":"manual","actionLabel":"Convert to JSON"},"capabilities":{"copy":true,"download":true},"workbenchMark":{"text":"Y>J"},"labels":{"empty":"Enter YAML to convert it to JSON.","ready":"Converted JSON is ready.","running":"Converting YAML to JSON…"},"content":{"howToUse":["Paste a YAML document. Indentation is significant, so copy it verbatim rather than retyping it.","Convert. The result is JSON pretty-printed with a two-space indent.","Copy the JSON, or download it if you are feeding it into a config loader or a fixture file."],"limitations":["Only the first document of a multi-document stream (separated by ---) is converted.","YAML anchors and aliases are expanded, so shared structure becomes duplicated JSON.","YAML types with no JSON equivalent — dates, binary, custom tags — are not representable and will either stringify or fail."],"faq":[{"q":"Why does my YAML fail to parse?","a":"Almost always indentation: tabs are not valid YAML indentation, and a single misaligned key breaks the block. The error message names the line."},{"q":"Is my YAML uploaded anywhere?","a":"No. The conversion runs entirely in this browser tab."}],"examples":[{"label":"Simple mapping","text":"name: Ada\nactive: true"}]}}$spec$::json, updated_at = now()
  WHERE tool_id = 'devtools.yaml-to-json' AND spec IS NULL;

COMMIT;
